WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[70924] = { title = "Community Feast", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[70925] = { title = "Community Feast", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[70926] = { title = "Stolen Totems", description = "", objectives = "Have you come to return our totems?", progress = "Have you come to return our totems?", completion = "Ah! Our totems are very important to us. You have our thanks for returning them, young one!" }
WordHunterWoW_QuestEN[70927] = { title = "More Stolen Totems", description = "", objectives = "Have you come to return our totems?", progress = "Have you come to return our totems?", completion = "There are far too many in these isles that prey on our people. Losing our totems is like losing pieces of ourselves--our heritage, our legacy! You have our thanks for returning these to us, young one." }
WordHunterWoW_QuestEN[70928] = { title = "Hunting Trophy", description = "", objectives = "What have you brought me outsider?", progress = "What have you brought me outsider?", completion = "Clan Shikaar knows a great hunting trophy when we see one. This will earn you much favor in our eyes." }
WordHunterWoW_QuestEN[70929] = { title = "More Hunting Trophies", description = "", objectives = "What have you brought me, outsider?", progress = "What have you brought me, outsider?", completion = "Only the greatest of hunters can boast of this many great hunting trophies. You honor our hunt." }
WordHunterWoW_QuestEN[70930] = { title = "All Tea, No Shadeleaf", description = "Today is a celebration of tea - brewed, iced, and otherwise! Extravagant little cakes and biscuits too.\n\nBut there is a rare ingredient of the Isles I feel could add a whole new dimension of flavor! Deep within the crawler-infested domain of the Shiverweb Vale is a bush laden with the most wondrously uplifting leaf: Coldsnap Sagittate.\n\nThe Dragonscale Expedition was exploring that area recently. Perhaps one of them could assist?", objectives = "Speak with Lilial Dawnburst in Shiverweb Vale.", completion = "A \"Coldsnap Sagittate\"? Hmm..." }
WordHunterWoW_QuestEN[70931] = { title = "Whispered Fragments", description = "I believe Valthrux is trying to communicate to us through the shard we recovered.\n\nWe can use this to our advantage as long as we keep our minds guarded from the artifact's influence.\n\nI was wrong about the Sundered Flame. They have unfortunately collected several shard fragments already. \n\nValthrux's whispers claim they're close to finding its location.\n\nGo and recover the shards from the Sundered Flame before they reach the artifact!", objectives = "Recover 40 Whispering Fragments from the Sundered Flame.", progress = "The whispers... they're... louder now. Do you have the fragments?", completion = "Excellent. With this many shards, I'll be able to easily locate the artifact." }
WordHunterWoW_QuestEN[70932] = { title = "The Life of Spice", description = "To many, meat is essential for any true meal. But what is the essential for any true meat dish?\n\nSpice!!\n\nA spice that surpasses all others in terms of flavor, texture, and rarity lies within these Isles. Unfortunately, it can only be found on elementals that dwell in the depths of the Obsidian Stronghold. It's an area currently occupied by the Djaradin.\n\nPerhaps you can consult with a peculiar troll I met while passing through there. I believe his name was... Griftah.", objectives = "Speak with Griftah at the Obsidian Throne.", completion = "What ya want?" }
WordHunterWoW_QuestEN[70934] = { title = "Salamanther's Embrace", description = "", objectives = "" }
WordHunterWoW_QuestEN[70935] = { title = "Catch and Release: Islefin Dorado", description = "", objectives = "If we over-fish this spot there will be no fish left for anyone. Sustainability is key.\n\nBring me any fish you want to return to the pools.", progress = "If we over-fish this spot there will be no fish left for anyone. Sustainability is key.\n\nBring me any fish you want to return to the pools.", completion = "I will return these to the pools. Managing the fisheries is an important responsibility." }
WordHunterWoW_QuestEN[70936] = { title = "Stolen Tuskarr Totems", description = "Have you come to return our totems?", objectives = "You there, young one! Our warriors take totems with them when they venture out into the Dragon Isles. Our totems are part of our livelihood--they are very important to us. Our enemies delight in taking them as trophies, and we can't let that happen! Please, return any totems you find." }
WordHunterWoW_QuestEN[70937] = { title = "What Valthrux Once Was", description = "<To'tik whispers to you.> \n\nI don't like this. Mysterious artifacts whispering promises of greatness does not sound good.\n\nBut we can't just walk away... otherwise the Sundered Flame will get their hands on it. Whatever \"it\" is...\n\nI'm familiar with ruins like this. The blue dragons often left behind notes on their work. Keep your eyes open, and you may find some around.\n\nWe can use whatever evidence you find to warn Alia and Kattigat.", objectives = "Find clues regarding what the artifact Valthrux really is.", progress = "Did you find anything useful in the ruins?", completion = "Let's see what you've found..." }
WordHunterWoW_QuestEN[70938] = { title = "Community Feasts", description = "There you are, {name}! The soup's on! \n\nYou better hurry up and get to Iskaara. Big Kinook has been looking for you. \n\nOne time he told me to get a slimy, icky spinefish for the soup and I didn't want to, so I yelled: \"No, chef!\"\n\nHe was so mad I thought he was going to throw me in the soup!", objectives = "Speak to Big Kinook at Iskaara in The Azure Span.", completion = "Are you ready to make magic, adventurer? \n\nNo, I don't mean that hand wavy stuff some like to make. I mean the mystical aroma arts, the deep knowledge of ingredients and flavor, and the way a soup speaks to you to let you know what it needs. Is that you salivating? No? Must be me. \n\nLet's get cooking!" }
WordHunterWoW_QuestEN[70939] = { title = "Cooking Utensils", description = "", objectives = "Do you wanna be a great big soup master, too? \n\nI can't wait until I can see over the lip of the big pot! Then I'll finally be big enough to lead a feast!\n\nHere, this is for you! It'll help you on your soupy journey! Let me know if you wanna trade for anything else!" }
WordHunterWoW_QuestEN[70940] = { title = "Tuskarr Champion's Tales", description = "", objectives = "The deeds of the tuskarr of the Dragon Isles are many!\n\nOver the years though, some of our stories have been lost. Many travelers never returned from their journeys with tales to tell. \n\nPlease, if you find any scrolls that document what our lost brethren were able to accomplish, bring them back to me." }
WordHunterWoW_QuestEN[70941] = { title = "Fishing Holes", description = "Hello again! Did you know I'm gonna be the bestest fisherman in the village? I caught a giant piranha once. It tried to eat my face!\n\n<Rowie looks around distractedly.>\n\nOh yeah! I have a message for you. Nunvuq, back in Iskaara, wants to tell you about fishing holes.", objectives = "Speak to Nunvuq at Iskaara in The Azure Span.", progress = "Are the fish biting?", completion = "Hail, fellow fisher. \n\nI'm almost hesitant to tell you of these serene fishing holes. But I must, because not doing so would deny you a bounty of fish and also the pleasure of a relaxing time fishing.\n\nIn telling everyone I worry about crowding my fishing spot, but I'll admit I can only take so much of the quiet. A good conversation with fishing friends is an even better way to relax than fishing alone!" }
WordHunterWoW_QuestEN[70942] = { title = "Highland Fishing", description = "", objectives = "Greetings, friend! I see you're getting to know the ways of tuskarr, and thus the ways of the fish.\n\nIf you'd like, I could make you something that will allow you to tackle fishing in the highland pools of the Dragon Isles. Think you're up for the challenge?" }
WordHunterWoW_QuestEN[70943] = { title = "Harpooning", description = "", objectives = "Well now, you're a fast learner! Your fishing skills continue to improve.\n\nLet's see how you do with a spear. I'll craft for you your very first tuskarr harpoon. We shall see what you can land with it!\n\nI'm sure you won't fail to impress." }
WordHunterWoW_QuestEN[70944] = { title = "Ice Fishing", description = "", objectives = "You've surpassed all of my expectations. And yet you continue to improve! You must hunger to learn more about fishing... \n\nHave you ever wondered what tasty morsels swim under the ice? Ice fishing takes skill, but I think you're up to the challenge.\n\nIf you bring me the right materials, I can get you started." }
WordHunterWoW_QuestEN[70945] = { title = "Netting More", description = "", objectives = "Your nets seem to be faring well in the fishing holes, but I think we can do better!\n\nIf you can get me the materials, I can help you craft some improvements to help you catch even more." }
WordHunterWoW_QuestEN[70946] = { title = "No One May Wield It", description = "What you found makes it sound like the artifact's power has doomed everyone who has used it so far.\n\nThe dragonspawn who lived here killed each other over it. The Sundered Flame seem like they're also getting corrupted by its influence too.\n\nThis isn't an artifact we need to recover. It's one that needs to be destroyed before it can harm anyone else.\n\nWe must convince Alia and Kattigat.", objectives = "Convince Alia to destroy Valthrux.", progress = "Let's hope this works...", completion = "This is worse than I thought. Way worse." }
WordHunterWoW_QuestEN[70947] = { title = "Treasure-Mad Trambladd", description = "", objectives = "" }
WordHunterWoW_QuestEN[70948] = { title = "Hook, Line, and Swelter!", description = "", objectives = "Are you up for an exceptional challenge and added danger in your favorite pastime of fishing? \n\nI can craft something that will allow you to catch the most intense species of fish: the ones that call the lava rivers of the Dragon Isles home!" }
WordHunterWoW_QuestEN[70950] = { title = "Skewering Even Bigger Fish", description = "", objectives = "How is that harpoon working for you? I'd love to hear the tale of your biggest catch with it!\n\nNow, what if I told you we could make harpooning even easier? I have some new designs that will do just that. Take a look!" }
WordHunterWoW_QuestEN[70951] = { title = "Tackling the Tackle Box", description = "", objectives = "" }
WordHunterWoW_QuestEN[70952] = { title = "Abandoned... or Hidden Caches", description = "", objectives = "Let me let you in on a little secret.\n\nSome of our less-than-friendly neighbors are jealous of our fishing prowess--and our fishing spots.\n\nThey trespass on our fishing claims and steal our tackle boxes, stashing them along the shores to not get caught in the act. Let me tell you what to look for, and you might just be able to help yourself to some useful supplies while you're out fishing." }
WordHunterWoW_QuestEN[70953] = { title = "Tuskarr Headwear", description = "", objectives = "Greetings, dear friend. \n\nYou've been so kind to our community here in Iskaara. I have heard of your deeds and wanted to knit you something as a thanks.\n\nPlease, take your pick! I've made many hats to while away the hours of the long winters. I would be happy to trade you for others as well, if you wish!" }
WordHunterWoW_QuestEN[70954] = { title = "Mounting Curiosity", description = "", objectives = "While gnolls remain the primary focus of my research, I'm very curious about the recently returned dragons as well. \n\nAfter intense study and observation, I began jotting down my notes on the subject. It's nowhere near complete, but when it is, I'm sure it will be a helpful guide to you.\n\nIn the meantime, would you like to look at one of my other manuscripts? I've started to trade them for items that will help continue my studies, so if you would like to learn more, visit me again!" }
WordHunterWoW_QuestEN[70955] = { title = "Fascinating Fliers", description = "", objectives = "I saw a drake with a spotted pattern fly by yesterday! That was certainly a first for me, but you probably see many like it in your travels! \n\nThat said, I took detailed notes in case it's a new subspecies. It also had some other fascinating traits I had not seen previously!\n\nIf you'd like to read more of my observations, pick a manuscript to take with you. And if you'd like more reading material, I'll happily trade with you." }
WordHunterWoW_QuestEN[70956] = { title = "Of Azure Scales", description = "", objectives = "Do you enjoy poetry? Wait. If you don't, don't tell me. Hanu might hear you.\n\nIn our travels here, Hanu and I have noticed there are few blue-scaled beasts outside the Azure Span!\n\nI hypothesized some theories on the origin and nature of blue scales and jotted them down. And Hanu wrote a lovely poem about their perfect blue color! \n\nShe is shy about her writing, so she asked me to give it to you. Please, treasure it as I treasure her." }
WordHunterWoW_QuestEN[70957] = { title = "The Sea Out West", description = "Enjoying the greenery around our little scenery, {name}?\n\nIt reminds me of a dish I once tasted from a pair of dryad sisters and their kind treant friend. Sugarbough was their name! A resident of Shady Sanctuary on the western coast of the Plains.\n\nIt was a medley of fresh herbs, veggies, and spices. At the heart of this dish was the most delicious layer of sea kelp you have ever tasted!\n\nWhat? Never tasted sea kelp before? Well you simply must seek some out. And bring back enough to share, please!", objectives = "Speak with Sugarbough at the Shady Sanctuary in the Ohn'ahran Plains.", completion = "Do you require assistance?" }
WordHunterWoW_QuestEN[70958] = { title = "Finest Fungi at the Feast", description = "Fine dining is all about using the finest techniques on the finest ingredients, naturally. The food composed for fine dining is oft locked behind wealth and means, but we would never allow that at The Ruby Feast!\n\nMorsel has informed me of a perfect ingredient for today's theme. One so rare, so exquisite, that it... does not exist yet! Tantalizing, no?\n\nThe bronze have uncovered a portal to a dangerous future. One where a black truffle with untold flavor exists!\n\nYou must go!", objectives = "Speak with Warden Captain Sinjoirmi at the Temporal Conflux in Thaldraszus.", completion = "Oh, <name>? My plate is full, but I will always make room at the table for you." }
WordHunterWoW_QuestEN[70959] = { title = "Cute and Cuddly", description = "", objectives = "Do you love animals?\n\nOf course you do, who doesn't? Even the scary ones are pretty neat!\n\nYou wanna take care of one of the animals I tamed all by myself? I can tame more if you wanna trade for them, too--as long as you promise to take good care of them!" }
WordHunterWoW_QuestEN[70960] = { title = "Trader's Apparel", description = "", objectives = "Hello, adventurer. \n\nI pride myself on my leatherworking skills. I would be honored if you would take this cloak as recognition for your efforts in helping us. \n\nIf you have a penchant for leather armor, I also am happy to make a set of our finest gear for trade." }
WordHunterWoW_QuestEN[70961] = { title = "Shouldering the Needed Armor", description = "", objectives = "Hello again! You've done so much for us, friend! We'd be in dire straits indeed without your assistance. \n\nAs a token of our appreciation, I want you to have a set of my tufted shoulderpads. They should keep you warm on your adventures. \n\nIf you would like me to make you a sturdier set, simply bring me the materials to craft it." }
WordHunterWoW_QuestEN[70962] = { title = "A Comfy Seat", description = "", objectives = "After a long day's work, it's good to relax. I've come up with a comfortable cushion to aid with that. It's very cozy! \n\nWould you like one? I'll gladly make one for you if you can bring me the materials to craft it!" }
WordHunterWoW_QuestEN[70963] = { title = "Wrist Support", description = "", objectives = "Greetings, friend! To aid you in your journeys, I've crafted a fine set of wrist armor for you. \n\nDid I detect a scoff, youngster? Now, let me tell you about the importance of taking good care of your wrists! You should be doing stretches every few hours, and bracing them with armor when engaging in arduous activities! Don't hold them at a odd angle for prolonged periods of time and...\n\n<Arvik continues for some time.>" }
WordHunterWoW_QuestEN[70964] = { title = "Shrug it On!", description = "", objectives = "<Arvik examines your wrist armor and grumbles in vague approval.>\n\nNow, have you been supporting your shoulders? Many don't realize it, but proper shoulderpads are important to help redistribute the weight of your other gear. You'll have back pain later in life without it! \n\n<Arvik rubs his back.> \n\nNot to mention protecting them from falling debris. With dragons, gnolls, centaurs... so much flying in or getting thrown around. Not safe out there. Please, consider my gear and keep your shoulders safe." }
WordHunterWoW_QuestEN[70965] = { title = "Wanted: Watcher's Golden Girdle", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Watcher's Golden Girdle for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nYou may wish to start your search at our northern dig site, where Elementalist Taiyang has reported a malfunctioning Watcher causing trouble.", objectives = "Find the Watcher's Golden Girdle.", progress = "Do you have something for the archives?", completion = "Whew, glad I don't have to wear this heavy thing!\n\nI'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[70966] = { title = "Trading Made Easier", description = "", objectives = "Have you traveled much? You don't look like you have--you're missing one of my sturdy backpacks!\n\nA good pack will make all the difference out in the world. You've helped my people out many times, so I want to offer you one of my best basic packs. \n\nI have many other packs as well! If you would like to offer a fair trade, I will gladly trade you for more." }
WordHunterWoW_QuestEN[70967] = { title = "Fishy Entertainment", description = "", objectives = "Fishing is great. I love it! I eat, sleep, and dream it. And when I'm not fishing, I craft fishing gear!\n\nIf I've learned anything from my many years fishing, it's that you also have to have a little fun out there--change things up, think outside the net!\n\nHere's some gear I dreamed up to help you new fishers along! You can have one for free, but if you'd like both, I'll gladly trade you for the other." }
WordHunterWoW_QuestEN[70968] = { title = "Of the Cloth, of the Community", description = "", objectives = "It is my honor to bestow upon you this gift, for all you have done for the tuskarr. The colors of our community are woven into its cloth, symbolizing how we all are woven together into a community--one that you are now a part of.\n\nWear it with pride, my friend!" }
WordHunterWoW_QuestEN[70969] = { title = "Becoming One of Our Community", description = "", objectives = "Greetings, friend! The tales of your deeds have spread across the Azure Span from Iskaara to Imbu to the Gleamlet. You've proven yourself time and time again, and we are grateful for it.\n\nChieftain Brena has declared that you have earned an honored place within our community... and within our family. You will forever be known as one of Iskaara. Thank you for everything you've done, friend. Please also take this Primal Infusion you can use to have a great item crafted." }
WordHunterWoW_QuestEN[70970] = { title = "Good Intentions", description = "I may know where the artifact is. Alia was whispering frantically when you brought all the shards back.\n\nShe kept saying something about a \"cave\" and how the spiders seemed attracted to it.\n\nThere's no cave in the area in front of us... which leads me to believe there might be one deeper in the ruins.\n\nWe'll stay here and keep your escape path open, {name}. Please save Alia and destroy this cursed artifact.", objectives = "Stop Alia Sunsoar and destroy the artifact Valthrux.", progress = "Let's hope this works...", completion = "To'tik was right. This place is cursed. \n\nWe'll let the Kirin Tor know what happened here, <name>. Thank you for your help. \n\nThis is a lesson I won't soon forget..." }
WordHunterWoW_QuestEN[70971] = { title = "Arms for Every Arm", description = "", objectives = "Have you come to spar? No? Shame.\n\nI know what you have done for our people. It would be an honor if you would wield one of my weapons. Pick which ever one pleases you. \n\nTake your time. I realize my collection is massive. \n\nIf you would like more of my weapons, continue to prove your mettle. Bring me items showing you are not losing your martial prowess, and I will trade you for more armaments!" }
WordHunterWoW_QuestEN[70972] = { title = "Our Loyal, Lanky Steeds", description = "", objectives = "Our ottuks choose only to be ridden by our most esteemed warriors.\n\nI think it is time to see if one will bond with you. They are fiercely loyal, but they love to have fun!\n\nI will leave you and the ottuks to decide which will be your bonded companion. \n\nOttuks that are large enough to ride are rare, and their tack is expensive. If you wish to train another one, my fellow trainers and I must ask for a large trade in return." }
WordHunterWoW_QuestEN[70975] = { title = "Wanted: Everblazing Fireheart", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Everblazing Fireheart for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nSome expedition members have reported seeing a massive fire elemental under control of the Primalists in the north that may provide an opportunity to acquire one.", objectives = "Find the Everblazing Fireheart.", progress = "Do you have something for the archives?", completion = "The Primalists sure do love their elementals, huh?\n\nI'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[70976] = { title = "Slacking and Sledding", description = "As you may know, the children of Iskaara are fiercely independent. They learn from a young age to fend for themselves.\n\nIt's a rite of passage for many of the older kids to sneak off to the iceberg southeast of here. Kiopo, the eldest of our children, is out there right now. Tell him I sent you, and he should offer you one of our sleds!\n\nAh, that reminds me of my younger days... out there with my friends...", objectives = "Seek out Kiopo on the island to the southeast.", completion = "Oh, Murik sent you? He's really nice, so you must be really nice too!\n\nWhy did he send you? A sled? Of course I can give you a sled! \n\nWe have two types. But if you want both, I'm gonna need some good stuff for a trade!" }
WordHunterWoW_QuestEN[70977] = { title = "Scaps Packs", description = "", objectives = "YOU BRING SCAPS HUNGRIES? BRING FEESH?\n\nNO?\n\n<SCAPS watches as you gesture towards his backpack.>\n\nWANT PACK-BACK? \n\n<SCAPS considers this.> \n\nYOU TAKE PACK-BACK, OKAY?\n\nBUT NEXT TIME--BRING FEESH! THEN GIVE PACK! \n\nME HUNGRIES!" }
WordHunterWoW_QuestEN[70978] = { title = "Dragon Isles Champion's Tales", description = "", objectives = "Young one! The Dragon Isles are full of stories that date back generations upon generations.\n\nIf you venture deep within the great halls and vaults of this land, I am sure you can find and reclaim scrolls that detail these stories. If you bring them to me, I'll have a special gift for you in return!" }
WordHunterWoW_QuestEN[70979] = { title = "Magmaton", description = "", objectives = "" }
WordHunterWoW_QuestEN[70981] = { title = "Savory Seas", description = "The smell of the sea! Do you smell it, {name}? Do you smell the multitude of minerals, laden with thick sea salt? Do you??\n\nSuspiciously absent from the delights here today is a rare variety of fish I once tasted near the Iskaara's home in Azure Span. Two Tuskarr fellows were simply roasting one over a fire, and it filled that glacial tundra with the most savory aroma!\n\nSee if you can not find one for us. I know our patrons will be just as ensorcelled by the sea's flavor as I was that day.", objectives = "Speak with Wayun in Whaler's Nook of the Azure Span.", completion = "Please tell me you aren't here with that Ironjaw fellow. We had enough gorloc troubles before he showed up..." }
WordHunterWoW_QuestEN[70983] = { title = "O'nank Shorescour", description = "", objectives = "" }
WordHunterWoW_QuestEN[70984] = { title = "Surge Breaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[70985] = { title = "The Lonely Scout", description = "I know, I know, it's silly. A centaur and a dryad, right? We can't be more different.\n\nBut ever since I first laid eyes on the Emerald Gardens, I really have wanted to get to know one better. I just can't seem to say or do anything to keep them interested in me.\n\nI've heard they're into... plants. And cute baby animals. And maybe killing poachers, but I don't even know where to start.\n\nPlease, you can talk to them, right? Could you ask around and find out what they like? Then maybe I can have a shot.", objectives = "Speak to dryads in Shady Sanctuary.", progress = "Any luck? Please tell me there's hope.\n\nIt would just be so nice.", completion = "Flowers!!\n\n<Scout Santuun smacks her palm on her forehead.>\n\nIt's so obvious. I was overthinking it, like I always do.\n\nThank you, <name>, you're the best!" }
WordHunterWoW_QuestEN[70986] = { title = "Private Shikzar", description = "", objectives = "" }
WordHunterWoW_QuestEN[70987] = { title = "Hearts of Starch", description = "What could be better than a meal you can carry while you explore?\n\nStreet foods are the essence of busy cities this great world over. But not every meal is set for mobility. The core of great on-the-go cuisines is a starch that will hold strong while moving. Breads, potatoes, rices, and beyond are the heart of hand-sized dining.\n\nI would like to treat my Pandaren peer here to a flavorful specimen known as Leapmaize. Morsel introduced it to me when we first met near the titan ruins in the Waking Shores.", objectives = "Speak with Meliane Enorath at the Life Vault Ruins in the Waking Shores.", completion = "Great, you're finally here. I need a dozen more cushions, three tapestries, a scrollshelf, a few more of those enchanted brooms, and...\n\nWait. You're not with the Expedition. What do you want?" }
WordHunterWoW_QuestEN[70988] = { title = "The Egg's the Thing", description = "\"All the world's an egg.\" That is how the saying goes, right?\n\nEggs! They are the core of confections, and one of the great catalysts of culinary creation! They are the fat that puts acids, heats, and salts on their highest pedestals, to their highest potentials!\n\nOur Isles are teeming with fowl of immense strength, but the Breezehunters of the Plains lay eggs primed with flavor!\n\nThey often nest on the Eastern side of the Plains, so ask around the outpost in Rusza'thar Reach.", objectives = "Speak with Ilana at Rusza'thar Reach in the Ohn'ahran Plains.", completion = "Oh! Hello!\n\nSorry about the mess here! I mean, I didn't cause it or anything, I'm just apologizing that you have to deal with it.\n\nNot to imply you wouldn't be able to handle it! Just saying that you might be uncomfortable with the state our furniture is currently in.\n\nNot that this is how we want the furniture set up! We don't want it set up like this, we were planning to... uhm...\n\nWhat did you say you needed?" }
WordHunterWoW_QuestEN[70989] = { title = "Part of a Pack", description = "Perhaps your bakar needs to be shown the proper way to hunt by his own kind.\n\nYou may borrow some of our trained bakar. Take them and bring down the drake that circles the area. \n\nLet us see how Taivan behaves in a pack!", objectives = "Hunt the Ravenous Proto-Drake with Taivan and the pack of hunting bakar.", progress = "Have you brought down that drake yet? My bakar should be more than enough for your quarry.", completion = "<Jadar shakes his head.>\n\nVery disappointing. I'm afraid Taivan just does not have it in him to hunt like a Shikaar. Even with other bakar fighting beside him, he could not shake his unwillingness to attack his enemy. \n\nWhat a waste!" }
WordHunterWoW_QuestEN[70990] = { title = "If There's Wool There's a Way", description = "While most of our wool comes from our own argali flocks, we do sometimes need to pull from the land when the flock grows thin.\n\nThe nearby plains are home to wild argali - they tend to be more temperamental than our clan's flock. If you could take this blade and attempt to shear their wool, it would be a great service to Aylaag.", objectives = "Shear cliffhoof argali for their wool.", progress = "Take care to avoid the horns. They're as sharp as any knife.", completion = "I will get this wool to the artisans who can use it. Thank you." }
WordHunterWoW_QuestEN[70992] = { title = "Wanted: Lost Tuskarr Kite", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Lost Tuskarr Kite for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nSome expedition members have reported seeing such a kite attached to a tuskarr transport along the western coast, but none have been able to reach it as the transport keeps it aloft and out of reach when traveling.", objectives = "Find the Lost Tuskarr Kite.", progress = "Do you have something for the archives?", completion = "I wonder what all the little scrolls on here say? The archivists'll have fun with this one.\n\nI'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[70994] = { title = "Drainage Solutions", description = "Want the honor of assisting world-renowned Head Geologist of the Dragonscale Expedition? That's right. I'm exactly who you think I am. And I'm in a bind!\n\nI was perusing this river for new sedimentary samples, but then the water started to walk away with the most interesting pieces of silt!\n\nI have here my patented water entrapment device, but it's in desperate need of someone to march around and siphon those elementals into it.\n\nThink you're up to the task?", objectives = "Siphon 8 Glittery Streams in the cave east of the Life Vault Ruins.", completion = "Yes, that's it! That's the composition I was looking for! Thank you! Finally, someone knows when to listen to me.\n\nDo me a favor and don't mention this to anyone back at basecamp, got it? My thesis is still in progress, and I'm supposed to be writing about volcanic sedimentary sources. I'm sure you can understand, yeah?" }
WordHunterWoW_QuestEN[70995] = { title = "Wanted: Fenistrasza's Skull", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out Fenistrasza's Skull for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nSome expedition members have reported seeing it in the possession of an outcast djaradin in the western mountains, but no one has been able to convince him to part with it yet.", objectives = "Find Fenistrasza's Skull.", progress = "Do you have something for the archives?", completion = "<Cataloger Jakes frantically tries to prevent the magma pouring out of the skull's eye sockets from burning her other documents.>\n\nOkay, now I KNOW the archivists are putting out these requests just to annoy me!\n\nNevertheless, I'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[70996] = { title = "A Little Kelp for My Friends", description = "Well gosh, it sure sounds like Grimtusk is in a pickle. I'd say I'm done with conflicts on the mainland, but...\n\nFrostbite and I have got a history. And a score to settle.\n\nOh, fiddle! I can't leave the others here undefended... We've an issue with an elemental causing trouble at the beach. I'm the only one who can keep him at bay. Slippery fella... literally.\n\nTell you what. If you will deal with the elemental for me, I'll mosey on over to Grimtusk's camp.\n\nWhaddaya say, champ?", objectives = "Defeat the Wild Kelp Elemental on Longclaw Island.", progress = "How's it going? Did you get that slippery, slimy elemental yet?", completion = "Well I'll be! Guess I'm heading out to help my pal Grimtusk after all!" }
WordHunterWoW_QuestEN[70997] = { title = "Wanted: Ruby Lifeband", description = "<The posted sign is written in hasty scratches.>\n\nExpedition members have reported a Primalist attack on the Ruby Life Pools, threatening the destruction of countless artifacts stored by our dragon allies there.\n\nToddy and Naleidea urge all combat-ready members to join the fight, and seek out the Ruby Lifeband if you are able.\n\nIt is a unique, priceless artifact that must be preserved.\n\nIf acquired, please deliver to Cataloger Jakes for safekeeping until the dragons may safely retrieve it.", objectives = "Find the Ruby Lifeband in the Ruby Life Pools.", progress = "Do you have something for the archives?", completion = "They say this was handcrafted by Alexstrasza herself? Thank the tides you saved it.\n\nI'll ensure this is properly documented and researched while we have it for safekeeping." }
WordHunterWoW_QuestEN[71000] = { title = "Barst Recruited", description = "Well a deal's a deal. If Grimtusk needs a hand killing Frostbite once and for all, then I'm in.\n\nWhat hate I have left in me I reserve for Frostbite. Did Grimtusk tell you what happened? \n\nAll of us who hunted with Grimtusk thought we were unstoppable. Until we met Frostbite. \n\nFrostbite didn't just defeat us. He humiliated us in front of everyone in the hideaway. \n\nWe were all defeated and left bloodied and battered at the hideaway. Frostbite used us as an example.\n\nNow it's time for payback.", objectives = "Let Grimtusk know you've recruited Barst.", completion = "Here's Barst. Just as... annoying as ever." }
WordHunterWoW_QuestEN[71001] = { title = "Wanted: Earthbound Primordial Core", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Earthbound Primordial Core for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nRecent learnings from records recovered from the Obsidian Citadel indicate it may have once been stored in the Dragon's Hoard of Neltharus, although it's current location is unclear.", objectives = "Find the Earthbound Primordial Core in Neltharus.", progress = "Do you have something for the archives?", completion = "I can tell this one's going to be a troublemaker... I'll get the magically sealed containers Naleidea enchanted for problem cases.\n\nDon't worry, I'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[71002] = { title = "Best Spell Ever", description = "<Gently levitating and emanating with arcane magic, this enchanted book contains countless spells and enchantments created by the chaotic yet beautiful mind of Millhouse Manastorm.>", objectives = "Read \"Manastorming for Beginners\" and discover Millhouse's secret spell.", completion = "<Using your own knowledge of the arcane, you begin browsing through Millhouse's notes until you find a worn out page filled with numerous drawings of ducks, big and small. \n\nIn the very center of it are words to Millhouse's newest conjuration with a curious hand note below: \n\n\"Best Spell Ever.\">" }
WordHunterWoW_QuestEN[71004] = { title = "Wanted: Ohuna Mass-Binding Totem", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Ohuna Mass-Binding Totem for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported a particularly powerful Primalist in the Windsong Rise of the Ohn'ahran Plains, who appears to wield the rumored powers of this totem.", objectives = "Find the Ohuna Mass-Binding Totem.", progress = "Do you have something for the archives?", completion = "Not sure I see what all the fuss is about with this one. Feels like every other dirty hunk of rock I've held before.\n\nOh well, I'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[71005] = { title = "Wanted: Fangfall", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the legendary blade Fangfall for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nThe sword was reportedly fractured long ago, but expedition members have reported that the Sundered Flame is recovering fragments of it in ruins of the Ohn'aran Plains.", objectives = "Find 100 Fragments of Fangfall.", progress = "Do you have something for the archives?", completion = "Ooo, I love puzzles! I should ask the archivists if I can help with putting these back together!\n\nI'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[71007] = { title = "Wanted: Disoriented Wishtail", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the legendary Wishtail for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported seeing a colorful fish matching its purported appearance inside a massive water elemental in Azure Span.", objectives = "Find the Disoriented Wishtail.", progress = "Do you have something for the archives?", completion = "<Cataloger Jakes puts her ear close to the fish and listens intently while whispering to it.>\n\nI know you can talk, little guy. Just say something and grant me a wish! It'll be easy!\n\n<Cataloger Jakes sighs.>\n\nIt was worth a shot. I'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[71008] = { title = "Wanted: Stoneheart's Stone Heart", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out Stoneheart's Stone Heart for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported seeing Stoneheart in a cave of central Azure Span.", objectives = "Find Stoneheart's Stone Heart.", progress = "Do you have something for the archives?", completion = "This used to be a beating furbolg heart? The Primalists really are something else...\n\nI'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[71009] = { title = "Elementary, My Dear Drakonid", description = "Grimtusk wants to take another crack at Frostbite, eh? I hate to turn him down, but I left that life behind for the life of a scholar.\n\nI'm trying to uncover the history--and make history. But I'm stumped by this esoteric riddle here in these ancient ruins. \n\nThe riddle is this: if you touch a nearby crystal, it says \"follow the pattern.\" But I haven't the faintest idea what that means!\n\nTell you what. If you can help me crack this riddle, I'll go help Grimtusk finish Frostbite off once and for all.", objectives = "Help Varsek solve the mystery of the Ancient Outlook.", progress = "\"Follow the pattern.\" What could that mean?", completion = "Oh dear... I'm not going to lie, <name>, this isn't my proudest moment." }
WordHunterWoW_QuestEN[71010] = { title = "Wanted: Temporal Spyglass", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Temporal Spyglass for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported overhearing a dwarf bragging about his magical spyglass in the inns of Southern Thaldraszus. We recommend focusing your search in that region.", objectives = "Find the Temporal Spyglass.", progress = "Do you have something for the archives?", completion = "<Cataloger Jake shakes her head as she keeps the spyglass far from her eyes.>\n\nNo thanks. The present holds enough headaches for me. Don't need the past or present butting their unwanted faces in too.\n\nI'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[71011] = { title = "Wanted: Torrential Lily", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Torrential Lily for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported seeing a powerful Primalist in Gelikyr Overlook of Thaldraszus with a magical flower pinned to her collar. It is unknown if that is the legendary Torrential Lily, but it is a good place to start your search.", objectives = "Find the Torrential Lily.", progress = "Do you have something for the archives?", completion = "Just what we needed, another flower that leaks some weird liquid...\n\n<Cataloger Jakes rolls her eyes.>\n\nI'll ensure this is properly documented, researched, and archived for the expedition." }
WordHunterWoW_QuestEN[71012] = { title = "Varsek Recruited", description = "Seems like I'll be able to solve the mysteries of this place just fine in the future. \n\nLet's just never speak of this to Old Grimtusk, OK?\n\nI'll make my way to his hideaway. I think I'll enjoy taking out some pent up aggression on Frostbite.", objectives = "Let Grimtusk know you've recruited Varsek.", completion = "There's Varsek. Guess he finally solved whatever puzzle he was after, eh?" }
WordHunterWoW_QuestEN[71013] = { title = "No Vengeance on an Empty Stomach", description = "Now that we've gotten back to what we aimed to do, we need to have a talk tusk to tusk. That gnoll Frostbite? The one you spoke to?\n\nWe've got a history with him.\n\nThis may take awhile to explain. You go and get some fish while I talk, pup. We need to feed everyone. They need their strength for what's next.", objectives = "Fish 3 Frozen Tail Darters within Grimtusk's Hideaway.", progress = "It's hard work fishing out here. That's the point.", completion = "Now you know what's at stake. \n\nTime to get moving." }
WordHunterWoW_QuestEN[71014] = { title = "A Far Furbolg Friend", description = "Barst was one of the toughest furbolgs I've ever known. It says something about Frostbite that his pack beat him in a fight.\n\nLast I heard, Barst left for some island off the coast of Iskaara. Called it his \"retirement\" or some other garbage.\n\nTell Barst it's time to get back into action. \n\nOh, and don't be fooled by the way he talks. He'll tear you in two if you look at him wrong.", objectives = "Find Barst on Longclaw Island.", completion = "Well, look at you! You made it all the way over here! How can I help you?" }
WordHunterWoW_QuestEN[71015] = { title = "All Brawn, No Brains", description = "Varsek is one of the toughest drakonids you'll ever meet. One of the dumbest ones too, but he'll never admit that.\n\nHe got spooked after Frostbite and started re-evaluating his life or... something. Said he never got to study the ruins left behind by his ancestors. Ran off to be a \"scholar\".\n\nGet Varsek back here. He doesn't belong there anyhow!", objectives = "Find Varsek in the Ancient Outlook.", completion = "It's very nice to meet you, but as you can see, I'm a bit busy trying to solve this puzzle." }
WordHunterWoW_QuestEN[71016] = { title = "Grimtusk's Sister", description = "Last is my sister, Naluki. She helps run the inn at Iskaara now.\n\nJust give her this letter. \n\nDon't open it.", objectives = "Deliver Grimtusk's letter to his sister, Naluki, in Iskaara.", completion = "Why, well aren't you just a fresh fish hopping out of the water! \n\nWhat's this? A letter from Grimtusk?" }
WordHunterWoW_QuestEN[71017] = { title = "Naluki's Letter", description = "Let me guess, Grim told you not to open the letter, right?\n\nLooks like you did as you were told. No wonder he trusts you so much! \n\nGive him this fish head for me. He'll know what it means.", objectives = "Deliver Naluki's fishhead to Old Grimtusk.", completion = "<It's hard to tell, but you think you see a slight smile on Grimtusk's face. It quickly fades away.>\n\nThis will do." }
WordHunterWoW_QuestEN[71018] = { title = "Vault of the Incarnates: Break a Few Eggs", description = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly.\n\nThree should be enough. Four seems excessive.", objectives = "Collect 3 Shards of the Greatstaff from Broodkeeper Diurna within the Vault of the Incarnates on Normal Difficulty.", progress = "The power contained in these shards will allow us to quickly access The Clutchwarren.", completion = "These should allow us to ascend to Diurna's chamber more readily." }
WordHunterWoW_QuestEN[71019] = { title = "Vault of the Incarnates: Break a Few Eggs", description = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly.\n\nThree should be enough. Four seems excessive.", objectives = "Collect 3 Shards of the Greatstaff from Broodkeeper Diurna within the Vault of the Incarnates on Heroic Difficulty.", progress = "The power contained in these shards will allow us to quickly access The Clutchwarren.", completion = "These should allow us to ascend to Diurna's chamber more readily." }
WordHunterWoW_QuestEN[71020] = { title = "Vault of the Incarnates: Break a Few Eggs", description = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly.\n\nThree should be enough. Four seems excessive.", objectives = "Collect 3 Shards of the Greatstaff from Broodkeeper Diurna within the Vault of the Incarnates on Mythic Difficulty.", progress = "The power contained in these shards will allow us to quickly access The Clutchwarren.", completion = "These should allow us to ascend to Diurna's chamber more readily." }
WordHunterWoW_QuestEN[71022] = { title = "Reign of the Ram", description = "Since the argali don't seem to have much respect for Taivan, we should see if he can handle the herd's ram next.\n\nHe's the boss of all the argali here, and quite the stubborn thing. If Taivan can assert dominance over the ram, the herd will start obeying him.\n\nYou can find him just over there, on the hill. Good luck, Taivan. If this doesn't work, I'm afraid there's not much hope for him being a herder!", objectives = "Command Taivan to confront the herd's Stubborn Ram.", progress = "The herd's ram is on the hill just over there. Hopefully Taivan handles this task a little better.", completion = "That could have gone better. Sorry, friend, but I don't think Taivan is cut out for this. \n\nHe's a very nice bakar, but doesn't quite seem smart enough to figure out how to get the argali into the pen, or aggressive enough to take command of the herd away from the ram. \n\nI'm afraid I'm going to have to send you back to Selbekh with bad news." }
WordHunterWoW_QuestEN[71023] = { title = "Renowned with the Valdrakken Accord", description = "Your deeds are certainly in line with your fabled reputation prior to coming to the Dragon Isles. \n\nI wish to assist you further by providing you with additional supplies. Seek me out in Valdrakken.", objectives = "Speak with Unatos in Valdrakken.", completion = "It is my part to acknowledge those whose efforts further the accord and by acknowledgement aid them further. I take pride in aiding one such as yourself. Please take these so they may continue to aid your efforts against the Primalists." }
WordHunterWoW_QuestEN[71024] = { title = "Chaos and Commotion", description = "{name}! Did you hear the noise? There has been an incident on the bottom floor.\n\nOne of my trusted investigators, Erima, was there first. He will require assistance gathering evidence while he tries to interview the crowd.", objectives = "Help Erima investigate the incident at the bottom floor of the Seat of the Aspects.", progress = "May I see that map?", completion = "I am grateful Captain Drine sent you to help.\n\nYou have keen eyes and are resourceful." }
WordHunterWoW_QuestEN[71025] = { title = "Against Overwhelming Odds", description = "Though you puny mortals have come to a truce, I have heard rumor that some of you still harbor grudges.\n\nIf you gather some friends, I know a place you can show the other side who is truly superior.\n\nAnd to make it interesting, if you are successful I have a prize for you.", objectives = "Slay 25 Level 70 Alliance anywhere within the Dragon Isles." }
WordHunterWoW_QuestEN[71026] = { title = "Against Overwhelming Odds", description = "Though you puny mortals have come to a truce, I have heard rumor that some of you still harbor grudges.\n\nIf you gather some friends, I know a place you can show the other side who is truly superior.\n\nAnd to make it interesting, if you are successful I have a prize for you.", objectives = "Slay 25 Level 70 Horde anywhere within the Dragon Isles.", completion = "Well done, <class>. Well done indeed." }
WordHunterWoW_QuestEN[71027] = { title = "WANTED: Mara'nar the Thunderous", description = "Looking for a mighty hunter to take down a rampaging beast!\n\nA thunder lizard named Mara'nar the Thunderous worked his way from Thunderspine Thicket to Primordial Vale, disrupting local wildlife. It has electrified water, knocked down trees, and broken duck nests.\n\nThis menace must be stopped. Slay him and bring one of his plates to Khansguard Jebotai as proof.\n\nMay Ohn'ahra guide you.", objectives = "Slay Mara'nar the Thunderous in Primordial Vale and retrieve one of his plates.", progress = "Hail, traveler.", completion = "Mara'nar has been slain. May his kin learn to stay within their own lands." }
WordHunterWoW_QuestEN[71028] = { title = "Hunting Tactics: Blessing of Ohn'ahra", description = "Your renown with the Maruuk grows. Listen closely, and I will teach you to call upon a blessing of Ohn'ahra to protect you and your allies.", objectives = "Select a blessing of Ohn'ahra for use in the Grand Hunt.", completion = "May the winds of Ohn'ahra guide and protect you.\n\nReturn when your renown grows, and I will train you further." }
WordHunterWoW_QuestEN[71029] = { title = "Hunting Tactics: Companion Training", description = "Your renown with the Maruuk grows once more. For your efforts, I will teach you to command your hunting companion more effectively in combat.", objectives = "Choose an additional companion ability for use in the Grand Hunt.", completion = "Your growth strengthens the clan.\n\nReturn again when your renown grows, and I will continue your training." }
WordHunterWoW_QuestEN[71030] = { title = "Hunting Tactics: Shikaar Mentorship", description = "", objectives = "Your renown with the Maruuk rises. Seek out other Shikaar during the grand hunt, and they will improve your combat prowess while the hunt is on.\n\nCome to me again when your renown grows, and I will train you more." }
WordHunterWoW_QuestEN[71031] = { title = "Hunting Tactics: Proof of Prowess", description = "", objectives = "I see your renown with the Maruuk has grown once more. Let me show you how to carry the thrill of victory through multiple foes.\n\nReturn again when your renown grows, and I will train you further." }
WordHunterWoW_QuestEN[71032] = { title = "Hunting Tactics: Apex Hunter", description = "", objectives = "Your renown has reached its peak, champion. I have one more technique to teach you. No quarry, no matter how powerful, will stand before you." }
WordHunterWoW_QuestEN[71034] = { title = "Dragon Isles Artifacts", description = "", objectives = "Do you have something for the archives?", progress = "Do you have something for the archives?", completion = "Ooo, a new artifact. Let me log it in the ledger and note you returned it. \n\n<Cataloger Jakes makes a notation in her ledger.> \n\nGot it! Keep them coming!" }
WordHunterWoW_QuestEN[71035] = { title = "Multiple Dragon Isles Artifacts", description = "", objectives = "Do you have something for the archives?", progress = "Do you have something for the archives?", completion = "Look at all these artifacts! This might take a minute. \n\n<Cataloger Jakes hastily makes several notes in her ledger.> \n\nGot it! Off with you, now! Come back if you have more!" }
WordHunterWoW_QuestEN[71036] = { title = "Dragon Isles Artifacts", description = "", objectives = "Do you have something for the archives?", progress = "Do you have something for the archives?", completion = "Ooo, a new artifact. Let me log it in the ledger and note you returned it. \n\n<Cataloger Jakes makes a notation in her ledger.> \n\nGot it! Keep them coming!" }
WordHunterWoW_QuestEN[71037] = { title = "Multiple Dragon Isles Artifacts", description = "", objectives = "Do you have something for the archives?", progress = "Do you have something for the archives?", completion = "Look at all these artifacts! This might take a minute. \n\n<Cataloger Jakes hastily makes several notes in her ledger.> \n\nGot it! Off with you, now! Come back if you have more!" }
WordHunterWoW_QuestEN[71038] = { title = "Hunting Trophy", description = "", objectives = "What have you brought me, outsider?", progress = "What have you brought me, outsider?", completion = "Clan Shikaar knows a great hunting trophy when we see one. This will earn you much favor in our eyes." }
WordHunterWoW_QuestEN[71039] = { title = "More Hunting Trophies", description = "", objectives = "What have you brought me, outsider?", progress = "What have you brought me, outsider?", completion = "Only the greatest of hunters can boast of this many great hunting trophies. You honor our hunt." }
WordHunterWoW_QuestEN[71040] = { title = "Stolen Totems", description = "", objectives = "Have you come to return our totems?", progress = "Have you come to return our totems?", completion = "Ah! Our totems are very important to us. You have our thanks for returning them, young one!" }
WordHunterWoW_QuestEN[71041] = { title = "Many Stolen Totems", description = "", objectives = "Have you come to return our totems?", progress = "Have you come to return our totems?", completion = "There are far too many in these isles that prey on our people. Losing our totems is like losing pieces of ourselves--our heritage, our legacy! You have our thanks for returning these to us, young one." }
WordHunterWoW_QuestEN[71042] = { title = "A Titan Relic", description = "", objectives = "Have you found a Titan Relic?", progress = "Have you found a Titan Relic?", completion = "Amazing! This relic is perfectly preserved. I will begin studying it right away.\n\nYour efforts are most appreciated! I will remember my promise to speak well of you to the Valdrakken Accord. \n\nNow, where was I? Yes, this will fit in right over here..." }
WordHunterWoW_QuestEN[71043] = { title = "More Titan Relics", description = "", objectives = "What have you brought me today?", progress = "What have you brought me today?", completion = "How did you find so many of these? This is a veritable treasure trove of relics! One day you must tell me your secret. \n\nOnce again you have greatly increased our knowledge of the titans. The Valdrakken Accord will think well of you indeed!" }
WordHunterWoW_QuestEN[71053] = { title = "Hermit Kill Quest", description = "Help! all these bunnies are eating my flesh! Please, kill them before they kill us all!", objectives = "Kill 5 Bunny of Doom in Training Plaza." }
WordHunterWoW_QuestEN[71058] = { title = "Observing the Wind", description = "", objectives = "<name>, you are a dragonrider, yes? You show great promise as an ally.\n\nLet me give you this, then, to celebrate our growing alliance. And I promise there is more where that came from!" }
WordHunterWoW_QuestEN[71060] = { title = "To Adorn Your Head", description = "", objectives = "Your deeds honor your people, friend <name>. Please accept this helm as a gift in recognition of all that you do for us. \n\nShould you find yourself wanting more, I would be happy to trade with you." }
WordHunterWoW_QuestEN[71066] = { title = "A Useful Curiosity", description = "", objectives = "<name>, you are in luck. One of our crafters created shoes we think you could use. Sky only sees why, but your service to the clan has inspired at least one of us.\n\nHowever, as much as I'd like to, we can't simply give them away. It was costly to create just a single pair of your unusual footwear. But they will be here if you should need them." }
WordHunterWoW_QuestEN[71067] = { title = "Whistling Rocks", description = "", objectives = "Dragonrider! The Aylaag understand that navigating to their camp can be challenging. And you know them--they welcome anyone who will follow their ways.\n\nOne of their nomads dropped off these windstones for you. They are not well-enchanted, but will transport you to the Aylaag camp. A few times, at least. Should that enchantment fade, they could likely make more!" }
WordHunterWoW_QuestEN[71073] = { title = "Mantle of Friendship", description = "", objectives = "My friend! It's a joy to see you again. I have another gift for you!\n\nPlease, take it with my compliments. But don't tell Huseng that I'm giving it away. He wanted me to charge you for it!" }
WordHunterWoW_QuestEN[71074] = { title = "Befriending Wings and Wind", description = "", objectives = "You're just in time, dragonrider. I have a special acquisition from the Ohn'ir. \n\nWith our clans spread so far apart, we often rely on ohuna to relay critical messages. This will allow you to call upon our eagle mail carriers wherever you go. They're not the swiftest, but they are reliable.\n\nNormally I would require a trade, but this is too important a boon. You may have need of it." }
WordHunterWoW_QuestEN[71075] = { title = "Understanding Their Grace", description = "", objectives = "Ah, my friend, you have returned! We were just speaking of how helpful you are!\n\nHere, accept this gift. It is the least we can do for an ally." }
WordHunterWoW_QuestEN[71079] = { title = "Getting to the Point", description = "", objectives = "So they've finally sent you to me, have they? Excellent!\n\nI stock many fine weapons for you to consider. Normally I'd insist on trading for my goods, but today I wish to honor your deeds for my people.\n\nJust don't tell Huseng. He'd never let me hear the end of it if he knew I gave something away... even to a dragonrider." }
WordHunterWoW_QuestEN[71083] = { title = "An Expected Unexpected Gift", description = "", objectives = "Dragonrider! Some of our goods are missing. \n\nI'd bet my back hooves that it's Rondare being too generous again. I've made clear that she can't just give things away. Seems I must have yet another chat with her.\n\n<Huseng grumbles, then realizes something.>\n\nOh, I almost forgot. I wanted to give you this." }
WordHunterWoW_QuestEN[71085] = { title = "Representation Matters", description = "", objectives = "Ah, dragonrider. The clans have been sharing tales of your deeds for several moons now.\n\nThey've all asked that I make your next gift a pennant of their clan's colors so you can represent them on the battlefield. Trouble is, I can only spare one of them. Huseng's on to me.\n\nWhich would you choose?" }
WordHunterWoW_QuestEN[71089] = { title = "Get on the Horn", description = "", objectives = "Friend, the Shikaar have asked me to offer you their ritual hunting horns. They insisted the horns were only for you, and that I was not to use them.\n\nHmph! I'm an excellent hunter. Perhaps the best they will ever see! They just don't know it yet.\n\n<Huseng laughs.>\n\nSo here you are. My stock is open to you, should you want any others." }
WordHunterWoW_QuestEN[71090] = { title = "From the Heart, For the Heart", description = "", objectives = "Ah, dragonrider. I have something for you.\n\n<Huseng holds up chest armor, sized for a <race>.>\n\nWe had to, uh, scale it down to fit you. It is fine make. Too fine to simply give it away. But I can sell it to you for the cost of materials.\n\nYou have proven yourself an ally of the Maruuk. Time for you to look the part!" }
WordHunterWoW_QuestEN[71091] = { title = "The Highest Honor", description = "", objectives = "My friend, you have defended these plains alongside my people, lending your aid to each of our clans without hesitation. You are an outsider no longer, but a familiar face among the centaur.\n\nTo honor our bond, I anoint you with the title of Khansguard and present you with this gift. May you proudly bear the Maruuk name wherever your travels take you." }
WordHunterWoW_QuestEN[71093] = { title = "Legacy of Tyr: Secrets of the Past", description = "To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored.\n\nInconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead.\n\nQueen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there.\n \nWord is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!", objectives = "Enter Uldaman: Legacy of Tyr in the Badlands and recover the disc." }
WordHunterWoW_QuestEN[71094] = { title = "Help Is Our Way!", description = "Hiya! \n\nAre you also here to help? You look very helpful!\n\n<Heleth points to the injured dracthyr.>\n\nThat guy hurt his wing trying to fly all the way up here! He looks like one of those bad guys from downstairs, but I'm not scared of him! I'm gonna help him out anyway, because that's our way!\n\n<Heleth puffs out their chest.> \n\nI'll stand guard over him, while you go find some bandages!", objectives = "Find bandages in the tower above the Cobalt Assembly to heal Venderthvan.", progress = "Finally! New people to play with!", completion = "We're gonna help this bad guy out so good!" }
WordHunterWoW_QuestEN[71095] = { title = "A Claw in Need", description = "Let's see what we can do to help this guy!\n\n<Heleth leans in close and whispers.>\n\nDon't worry, we aren't gonna let him take anything or stuff like that. Let's just have some fun!\n\nIt's been ages since anyone has come up here to check up on us. We're SO bored!\n\n<Heleth winks at you.> \n\nWhy don't you ask him what he wants?", objectives = "Ask Venderthvan how you can help him and do what he says.", progress = "Go ahead, <race>, do all the work for me. It will be a piece of cake to take the artifact from you when the moment is right.", completion = "That looks promising. Give it here. \n\n...what do you mean you're not going to give it to me?" }
WordHunterWoW_QuestEN[71096] = { title = "Is A Claw Indeed", description = "<Venderthven rubs his eyes and groans in pain.>\n\nFine. If you won't give it to me, you can do the work of figuring out how to make it work. \n\nI'll just take it from you when you're done. By force, if necessary.\n\nSo go ahead. Give it a shake or something.", objectives = "Attempt to activate the artifact.", progress = "<Venderthvan is distracted, looking at a toy duck Nezzie is showing him.>", completion = "Huh? Oh, right. The arcana." }
WordHunterWoW_QuestEN[71097] = { title = "A Helping Claw", description = "Alright, you've charged the artifact. Let's turn it on.\n\nAnd stop giving me that look. Don't pretend like you aren't curious to see if it works. \n\nJust give that thing another shake, back away slowly, and let me finish the job.", objectives = "Activate the artifact in the tower above Cobalt Assembly and monitor Venderthvan's actions.", progress = "<Venderthvan looks distracted.>", completion = "Enough... enough!\n\nI didn't sign up for this. \n\nJust take the artifact. Before I think too hard about this and change my mind." }
WordHunterWoW_QuestEN[71135] = { title = "Loose Ends", description = "If there's anything I learned from my time out in the wilderness, it's that if you don't deal with an evil when you find it--if you don't break its bones and dig up its roots, it'll keep growing. And then it'll be harder to kill.\n\nThese mountains were plagued with Frostbite's existence when I was a young pup like you, and it will only get worse once he takes full control of the Snowhide tribe. \n\nI should have done something about him long ago, but we're the only ones who can right that mistake now.", objectives = "Confront Frostbite at the Snowhide Camp in the Azure Span.", progress = "We cannot rest until Frostbite and the Snowhide gnolls have been dealt with.", completion = "Let's never do this again." }
WordHunterWoW_QuestEN[71138] = { title = "Waygate: Rusza'thar Reach", description = "An expeditionary member reported a dormant stone sighting atop a lookout in the Ohn'ahran Plains.\n\nUp fer an adventure?", objectives = "Locate the Dormant Waygate at the Rusza'thar Reach in the Ohn'ahran Plains.", progress = "What are ye waitin' fer?", completion = "Up and runnin' already? That was quick!\n\nI'll hold onto this here vessel. Looks like it's still got some energy wizzin' about!\n\nNever know if if we'll be needin' it again." }
WordHunterWoW_QuestEN[71139] = { title = "Glowing Arcane Jewel", description = "<This jewel seems to be quite powerful. There is an eerie glow to it.\n\nPerhaps it's best to deliver it to the Kirin Tor for it to be placed in a safe spot.>", objectives = "Bring the Glowing Arcane Jewel to Noriko the All Knowing in Camp Antonidas.", completion = "Look at this jewel! I'll make sure it gets to Dalaran immediately for study. \n\nHere, take this for your efforts. We recently uncovered it from another excavation." }
WordHunterWoW_QuestEN[71140] = { title = "Two and Two Together", description = "", objectives = "Defeat Bakhushek in a Pet Battle" }
WordHunterWoW_QuestEN[71141] = { title = "Gills with Gall", description = "Kad'irsza is reckless, but she knows her crabs. The gorlocs have gone too far!\n\nI noticed the gorlocs going to Gurblbrblr for everything. Notably, he is instructing them to take crabs prisoner. We cannot allow this to continue, for the balance of life, and for the safety of those who tend it.\n\nDefeat Gurblbrblr. Remove their means of expanding beyond this river!", objectives = "Kill Gurblbrblr the Invader in Cliffdrip Camp.", progress = "Do not permit the gorlocs to encroach on the wildlife!", completion = "Good. Now the gorlocs will lack the wherewithal to shackle more of these crabs. \n\n... And you have done more than just protect the crabs, <name>. You have protected Kad'irsza as well. I thank you." }
WordHunterWoW_QuestEN[71143] = { title = "The Horde Slayer", description = "Wow! Keep it up, soldier! \n\nSlay a bit more Horde and you will go down in the record books among the Alliance. \n\nBut it won't be easy, the Horde have put a bounty on your head, so watch it!\n\nFor the Alliance!", objectives = "While being hunted by the Horde, slay 10 Horde without dying." }
WordHunterWoW_QuestEN[71144] = { title = "The Alliance Slayer", description = "Yes! Keep going, keep slaying those Alliance dogs!\n\nSlay a bit more Alliance and you may set a new record, {class}.\n\nBut it won't be easy, the Alliance have put a bounty on your head, so watch it!\n\nFor the Horde!", objectives = "With a bounty on your head, slay 10 Alliance without dying." }
WordHunterWoW_QuestEN[71145] = { title = "The Grand Master", description = "", objectives = "Defeat Patchu in a Pet Battle" }
WordHunterWoW_QuestEN[71146] = { title = "Continued Waygate Exploration", description = "<The explorer-in-training hands you a taut, rolled note. Upon investigating, it appears to be from an old friend, Thaelin Darkanvil, seeking your aid.\n\nBefore scurrying off, the critter extends its hand as if it were seeking a treat. Moments later, a loud screech rings out as the curious creature storms off empty handed.>", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", completion = "Ah, my favorite friend returns fer a new adventure!\n\nOh, that's between us just so ye know. Wouldn't want the others tae think they aren't my favorite too!" }
WordHunterWoW_QuestEN[71148] = { title = "Continued Waygate Exploration", description = "<The curious creature before you presents a note--signed and sealed by the Dragonscale Expedition.\n\nA call for assistance from a famed explorer, perhaps.>", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", completion = "What do we have here? It's my most adventurous... erm... adventurer!\n\nCome tae do a bit more explorin'?" }
WordHunterWoW_QuestEN[71149] = { title = "Continued Waygate Exploration", description = "<Surprisingly, the messenger did not leave you with a satchel or a note this time, rather a single item from Thaelin's personal collection.\n\nUpon further investigation, a tiny little message from Thaelin seeks your assistance once again.>", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", completion = "Can't get enough, can ye?\n\nGlad tae see ye again, <name>! Let's get to it." }
WordHunterWoW_QuestEN[71150] = { title = "Continued Waygate Exploration", description = "<The parchment emits an unpleasant, mold-like smell. After struggling to regain focus, it becomes clear Thaelin needs your assistance in seeking answers to newly discovered findings.\n\nThe only question that remains is what to do with this parchment of intolerable odor.>", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", completion = "Ack, ye scared me! Wasn't expectin' ye so soon.\n\nUp fer a bit more explorin' I see." }
WordHunterWoW_QuestEN[71151] = { title = "Continued Waygate Exploration", description = "<The letter is clean, crisp and bears the seal of the Dragonscale Expedition.\n\nThaelin Darkanvil requests your presence.>", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", completion = "The famed explorer returns! I've grown quite fond of our time together, <name>.\n\nWhat say you? Up fer one last hurrah?" }
WordHunterWoW_QuestEN[71152] = { title = "Back to the Main Hall", description = "Now that we've accessed the override consoles, we should be able to get past that barrier.\n\nI'll meet ye back in the main hall and we'll see this through!", objectives = "Rendezvous with Toddy in the main hall.", completion = "All that hard work is about to pay off, <name>." }
WordHunterWoW_QuestEN[71153] = { title = "WQs, Bonus Objectives and Scenarios Oh My", description = "Assist the Tortollan by completing 3 world quests.Upon completion of this quest you will gain:", objectives = "Complete 3 Tortollan world quests." }
WordHunterWoW_QuestEN[71154] = { title = "Talon Toss: Shooting 101", description = "", objectives = "" }
WordHunterWoW_QuestEN[71155] = { title = "The Azure Vaults", description = "We have a problem, {name}.\n\nBeneath the Azure Archives rests the Azure Vault. In my life, I stored many important and dangerous magical curiosities in it.\n\nA large group of Sundered Flame have broken into the vault, convinced it holds some kind of secrets.\n\nPlease, you must go in there and stop this brazen assault before they unleash dangers they do not comprehend.\n\nThese thieves know not what lies within.", objectives = "Stop the Sundered Flame within the Azure Vaults.\n\nYou can access the Azure Vaults solo by queuing for it in Follower Dungeons.", progress = "Do be careful within the vaults.", completion = "Ten thousand years of delaying what I feared in my heart would be the inevitable end for my child. \n\nMalygos and I hoped one day we would find a cure. Though that day never came, I would not change any of our actions.\n\nWe must always strive for hope, even if it seems nonexistent. \n\nI take comfort in knowing at least my child is now reunited with the true Sindragosa and Malygos.\n\nNow go." }
WordHunterWoW_QuestEN[71156] = { title = "Rebel Concerns", description = "", objectives = "" }
WordHunterWoW_QuestEN[71157] = { title = "Waygate: Skytop Observatory", description = "Word from some of our northern explorers is there's another o' those stones high atop the spire to the northeast.\n\nHeard it's quite difficult tae reach bein' so high up and all, but I'm sure ye can find a way!", objectives = "Locate the Dormant Waygate at the Skytop Observatory in The Waking Shores.", progress = "Any luck?", completion = "The spire-seeker returns!\n\nHope it wasn't too much trouble fer ya." }
WordHunterWoW_QuestEN[71160] = { title = "Depth Charge", description = "", objectives = "" }
WordHunterWoW_QuestEN[71161] = { title = "Waygate: Vakthros", description = "Received a report of another of them dormant stones in the wintry region tae the southeast.\n\nNow before ye go gettin' all excited just know this isn't a place most go willingly, but if ye feel the need fer adventure and possible death, this is fer you!\n\nSold ye on it enough yet? Good!\n\nToss on yer warmest attire, then head east until the chill of the wind tickles yer nose and keep goin'. You'll know yer close when ye start feelin' the toughness in yer breath and the chill in yer bones.", objectives = "Locate the Dormant Waygate atop the spire in Vakthros in The Azure Span.", progress = "Keepin' warm I hope.", completion = "Bit chilly, wasn't it?\n\nNow that that's o'er and done with, what's next on yer agenda?" }
WordHunterWoW_QuestEN[71162] = { title = "Waygate: Algeth'era", description = "Another stone. Another spire.\n\nBest be gettin' along on yer journey. This one's quite a trek and dangerous tae boot! At least accordin' tae the ones who discovered it.\n\nAre ye up fer it?", objectives = "Locate the Dormant Waygate atop the spire in Algeth'era in Thaldraszus.", progress = "Can always count on ye tae get the job done.", completion = "I'm startin' tae wonder when this vessel might run out of power. Errr, maybe I'm the only one thinkin' that.\n\nWhat's in this thing anyways?\n\n<Thaelin shakes the vessel, but it makes no sound.>" }
WordHunterWoW_QuestEN[71164] = { title = "Stolen Bandages", description = "", objectives = "" }
WordHunterWoW_QuestEN[71165] = { title = "Waygate: Eon's Fringe", description = "Far across the land in the mountainous regions of Thaldraszus sits a little inn nestled on the mountainside. Just inside the entryway sits a long-forgotten, dormant stone.\n\nWhat say ye? Up fer another adventure, {name}?", objectives = "Locate the Dormant Waygate at Eon's Fringe in Thaldraszus.", progress = "Ye know I'd love tae sit around and talk, but there's work tae do.", completion = "Yer adventurous nature never ceases tae amaze!\n\nI wonder how many more o' these things are out there." }
WordHunterWoW_QuestEN[71166] = { title = "The Oldest Dragonfly", description = "", objectives = "Defeat Swog in a Pet Battle." }
WordHunterWoW_QuestEN[71178] = { title = "Waygate: Shady Sanctuary", description = "Our expedition reports a dormant stone out in the lush hillsides to the southwest. It's quite a journey, but worth sendin' someone with yer knowledge tae investigate.", objectives = "Locate the Dormant Waygate at the Shady Sanctuary in the Ohn'ahran Plains.", progress = "Well? Get on with it!", completion = "Looks like it worked!\n\nI'll keep the vessel safe in case we'll be needin' it again." }
WordHunterWoW_QuestEN[71179] = { title = "Look to the Overlook", description = "{name}, I have another task for you.\n\nThere have been reports of Primalist activity near the Gelikyr Post that threaten our control of Tyrhold.\n\nSpeak with Commander Thadezus and see how you can assist.", objectives = "Speak with Commander Thadezus at the Gelikyr Overlook.", completion = "<Thadezus sighs deeply.>\n\nYou are telling me that Drine sent you?" }
WordHunterWoW_QuestEN[71180] = { title = "You Have to Start Somewhere", description = "", objectives = "Defeat Setimothes in a Pet Battle" }
WordHunterWoW_QuestEN[71181] = { title = "Forgotten Grotto Relics", description = "", objectives = "" }
WordHunterWoW_QuestEN[71182] = { title = "Wayward Archivists", description = "You, dracthyr. \n\nTwo of your kin have been searching the archives just south of here. I have yet to introduce myself, and would appreciate the company.\n\nIf you have the time, I can meet you in the upper archive.", objectives = "Meet Sindragosa in the upper archive in the Azure Archives.", completion = "You are a very jumpy bunch." }
WordHunterWoW_QuestEN[71191] = { title = "Net Worth", description = "Alas, my fishing net was carried away by the stream. <Sigh> I'm not too keen to use fishing poles like my friends...\nIf you happen to find my fishing net around, bring it back to me.", objectives = "Recover Gruff Fisher's Net from ice holes in Azure Span.\n\nYou may unlock only one extra fishing net per day.", progress = "Any luck finding the net?", completion = "You you found it! Alas, too late, I've got a replacement from Tavio in Iskaara already. Feel free to keep it, it's best fit for catching fish in these icy waters." }
WordHunterWoW_QuestEN[71192] = { title = "Predator Control", description = "Greetings friend!\n\nI've been looking for a good place to set up fishing nets around here, but it seems like the population of waddlers around here is too dense - they're eating away most of the juvenile fish before they get a chance to mature.\n\nI've made some effigies to scare at least some of those ravenous birds away. This will help us sustain the abundance of fish across the Dragonsprings. \n\nCan you help me set those up?", objectives = "Set up the Scary Effigies.\n\nYou may unlock only one extra fishing net per day.", progress = "Did you set up enough effigies?", completion = "Well done, my friend! Feel free to set another fishing net now, there should be enough us all." }
WordHunterWoW_QuestEN[71193] = { title = "Underwater Menace", description = "Did you see that? Underwater! A huge, armored, hungry beast! No way I'm getting near water with my net while that monstrosity lurks below. If you want, you can likely lure it out with a handful of Ominous Conches. Those shouldn't be too hard to catch.\n\nTo gain conchs, be sure to have your Iskaaran Harpoon handy as you fish in the Dragon Isles.", objectives = "Use 5 Ominous Conches in the Tyrhold Fishing Hole to summon a huge underwater beast, and bring back something as a proof of its demise.\n\nYou may unlock only one extra fishing net per day.", progress = "You're not afraid of littoral megafauna, are you? Because I am!", completion = "You don't mind sharing some of the meat with me? Why thank you, let me show you the best fishing net spot around in return." }
WordHunterWoW_QuestEN[71194] = { title = "Frogs of Fire", description = "I found a perfect spot for a fishing net, one problem bothers me though... Those Hornspikes. I'm pretty sure they will ravage the nets as soon as it's left alone. What do we do?\n\n...I've got an idea. We treat our lava fishing nets with Icicle Brew to make them heat-resistant. We just need to teach those hornspikes to keep away from that smell.\n\nToss a flask of Icicle Brew at a hornspike, and then deal some damage to them. Just make sure not to kill them, they won't learn if they're dead, would they?", objectives = "Teach a couple of Hornspikes to avoid Icicle Brew.\n\nYou may unlock only one extra fishing net per day.", progress = "Did you teach them to keep away from the smell of Icicle Brew?", completion = "Well done! Feel free to use the fishing net spot now, there's enough room for us all." }
WordHunterWoW_QuestEN[71195] = { title = "To Tame A Thunderspine", description = "I guess this is Lizi's new favorite spot. She hasn't been interested in coming back home. After all, she is a wild beast.\n\nI have to tell you... I haven't spoken to Meluun since we saved Lizi. I know she was right, but I don't know how to approach her. She doesn't seem to approve of anything I do. I know I have to focus more on my training.\n\nMeluun makes a stomping good curry that Lizi would love. Do you think you could ask her for it? She's usually working in the Ohn's house west of the springs.", objectives = "Collect Meluun's Green Curry in the Ohn'iri Springs and 150 Dragon Isles Supplies.", progress = "Did you talk to Meluun yet?", completion = "I can smell the curry from here! Oh, by the ancestors, Lizi will be so happy! I'll take this as a sign that Meluun hasn't cast me out of her good graces completely." }
WordHunterWoW_QuestEN[71196] = { title = "To Tame A Thunderspine", description = "I'm so happy that Lizi is safe and sound with us.\n\nHowever, her wounds are healing slower than expected. I hope that the magic inflicted upon her didn't cause permanent damage.\n\nCould you help me gather insect ichor? I know, it sounds gross! It's actually the base of many healing ointments.", objectives = "Collect 20 Fluorescent Fluid from insects around the Dragon Isles and 150 Dragon Isles Supplies.", progress = "Have you returned with more ichor? I hate to see Lizi still in pain.", completion = "I'll go apply it to her wounds right away. It should offer immediate relief." }
WordHunterWoW_QuestEN[71197] = { title = "To Tame A Thunderspine", description = "Lizi is healed, but she's still nervous about leaving her spot. In the wild, she'd forage about a musken's weight of plants a day. It's impossible for me to do that! We need her to move out of the water and to the grasses.\n\nI'll keep trying to coax her out, but in the meantime, could you help me forage? I hear there are especially nutritious high-fiber leaves in the Emerald Gardens. Please bring back any you can find!", objectives = "Lizi is healed, but she's still nervous about leaving her spot. In the wild, she'd forage about a musken's weight of plants a day. It's impossible for me to do that! We need her to move out of the water and to the grasses.\n\nI'll keep trying to coax her out, but in the meantime, could you help me forage? I hear there are especially nutritious high-fiber leaves in the Emerald Gardens. Please bring back any you can find!", progress = "Lizi is healed, but she's still nervous about leaving her spot. In the wild, she'd forage about a musken's weight of plants a day. It's impossible for me to do that! We need her to move out of the water and to the grasses.\n\nI'll keep trying to coax her out, but in the meantime, could you help me forage? I hear there are especially nutritious high-fiber leaves in the Emerald Gardens. Please bring back any you can find!", completion = "This should tide her over until she can forage by herself again." }
WordHunterWoW_QuestEN[71198] = { title = "To Tame A Thunderspine", description = "Lizi's doing so much better. She's moving around with ease and consuming everything edible in sight.\n\nI learned today that thunderspines enjoy eating fish--especially piranhas! How fascinating! It is how they keep the piranha population in check at home.\n\nWill you go fish some? Mind your fingers!", objectives = "Lizi's doing so much better. She's moving around with ease and consuming everything edible in sight.\n\nI learned today that thunderspines enjoy eating fish--especially piranhas! How fascinating! It is how they keep the piranha population in check at home.\n\nWill you go fish some? Mind your fingers!", progress = "Lizi's doing so much better. She's moving around with ease and consuming everything edible in sight.\n\nI learned today that thunderspines enjoy eating fish--especially piranhas! How fascinating! It is how they keep the piranha population in check at home.\n\nWill you go fish some? Mind your fingers!", completion = "Those piranhas sure look...crunchy. I'm glad a predator exists for them." }
WordHunterWoW_QuestEN[71199] = { title = "To Tame A Thunderspine", description = "Everyone is curious about Lizi, but the truth is, she sticks out like a sore hoof. Lizi herself is starting to wander more and more, as if she's looking for something.\n\nShe mostly rests by the water on the mud. I'm sure it's fine, but I know thunderspines like to make a bedding from grasses.\n\nI've got an idea better than grasses. Will you help me gather wool from the plains? I'll weave her a blanket and some toys.", objectives = "Everyone is curious about Lizi, but the truth is, she sticks out like a sore hoof. Lizi herself is starting to wander more and more, as if she's looking for something.\n\nShe mostly rests by the water on the mud. I'm sure it's fine, but I know thunderspines like to make a bedding from grasses.\n\nI've got an idea better than grasses. Will you help me gather wool from the plains? I'll weave her a blanket and some toys.", progress = "Everyone is curious about Lizi, but the truth is, she sticks out like a sore hoof. Lizi herself is starting to wander more and more, as if she's looking for something.\n\nShe mostly rests by the water on the mud. I'm sure it's fine, but I know thunderspines like to make a bedding from grasses.\n\nI've got an idea better than grasses. Will you help me gather wool from the plains? I'll weave her a blanket and some toys.", completion = "Perfect! This will do! I've not met an animal that doesn't like soft things." }
WordHunterWoW_QuestEN[71202] = { title = "Mini Manafiend Melee", description = "", objectives = "Defeat Arcantus in a Pet Battle." }
WordHunterWoW_QuestEN[71205] = { title = "Hydro Tuskarr", description = "", objectives = "" }
WordHunterWoW_QuestEN[71206] = { title = "Eye of the Stormling", description = "", objectives = "Defeat Stormamu in a Pet Battle." }
WordHunterWoW_QuestEN[71209] = { title = "Beast of the Plains", description = "I think Lizi is ready to be a beast of the plains again. She's so friendly to you and I now, but I can tell she wants to return to the wild.\n\nOne day, when I am a Windsage, I will explore all of the world beyond these springs. But first--my midseason initiate trials! How time flies.\n\nI made a saddle and reins from the wool you gathered. Lizi will be happy to come at your call.\n\nPlease take her on all the adventures, {name}.", objectives = "Accept Lizi's Reins.", completion = "Don't forget to visit me sometime! Goodbye, <name>!" }
WordHunterWoW_QuestEN[71210] = { title = "To Dragonbane Keep!", description = "<Flaps drops a slightly singed note into your hand.>\n\n{name}, the Obsidian Outcasts have heard tales of your bravery. Our former home, Dragonbane Keep, has fallen into djaradin hands. We can't let that stand. Join us in reclaiming our territory.\n\n- Boss", objectives = "Travel to the Waking Shores and join the Obsidian Outcasts on the Siege of Dragonbane Keep.", progress = "We must take the Keep!", completion = "Another battle is won, but the war continues." }
WordHunterWoW_QuestEN[71212] = { title = "Attackin' the Brackenhide", description = "", objectives = "" }
WordHunterWoW_QuestEN[71219] = { title = "The Wayward Waywatcher", description = "It seems some of our younger Waywatchers have grown lax in their duties of late.\n\nWaywatcher Nori has asked me to check in on her younger sister Alvi, who is stationed at the mouth of the Passage of Time. Apparently her recent performance has been less than satisfactory.\n\nIf you head east and happen to encounter Waywatcher Alvi, please remind her of the importance of her position, and let her know that her sister is rather worried about her.", objectives = "Find Waywatcher Alvi.", completion = "Oh, gracious, a traveler. Please forgive me, I am a bit of a mess at the moment." }
WordHunterWoW_QuestEN[71225] = { title = "Blown Through Wind: Rhuzast", description = "", objectives = "" }
WordHunterWoW_QuestEN[71226] = { title = "Kill  Rock Snails", description = "Help! all these bunnies are eating my flesh! Please, kill them before they kill us all!", objectives = "Kill 5 Bunny of Doom in Training Plaza." }
WordHunterWoW_QuestEN[71227] = { title = "Aerial Challenges", description = "<Flaps flaps his wings excitedly, dropping both a note and a singed rodent at your feet.>\n\nDragonrider! Your flight prowess has become well known. Come test yourself in Aerial Challenges across the Dragon Isles.\n\nSpeak to any Bronze Timekeeper to get started.", objectives = "Speak to a Bronze Timekeeper to learn about aerial challenges.", completion = "Another challenger? Welcome! \n\nAerial Challenges are timed races on courses throughout the Dragon Isles. Beat track times to earn your rank." }
WordHunterWoW_QuestEN[71229] = { title = "Call of the Plains", description = "<Roki drops a message into your hand.>\n\n{name}, Clan Aylaag has heard tales of your great deeds. We invite you to meet our clan and share our ways.\n\nHadari Khan", objectives = "Speak to Hadari Khan in the Ohn'ahran Plains.", completion = "Your aid is welcome, Dragonrider. There is much to be done around our camp." }
WordHunterWoW_QuestEN[71230] = { title = "Tuskarr Fishing Gear", description = "Hi again, {name}.\n\n<Rowie looks around and hums a little tune.>\n\nOh right! Tavio was making me a new net and said she could make you one too. She can make some other fishing gear too if you bring her all the stuff.\n\nYou should go talk to her.", objectives = "Speak to Tavio at Iskaara in The Azure Span.", completion = "My family is known as the best weavers of nets and crafters of harpoons. If you bring me the supplies I need, I can craft some new tools for you." }
WordHunterWoW_QuestEN[71231] = { title = "Call of the Hunt", description = "<Roki drops the note into your hand>\n\n{name}, Clan Shikaar invites you to the Grand Hunt. Meet with Trainer Frodrum in the Ohn'ahran Plains.", objectives = "Speak to Trainer Frodrum in the Ohn'ahran Plains.", completion = "Dragonrider! Your aid will be welcome in the coming hunts." }
WordHunterWoW_QuestEN[71232] = { title = "Renown of the Dragon Isles", description = "There is still much that must be done to aid the Dragon Isles.\n\nI would ask you speak with Koszaru. He has much information regarding who needs help within this land.", objectives = "Speak with Koszaru within Valdrakken.", completion = "Good to see you, <name>. \n\nThere are many sources of power within the Dragon Isles, as long as you know where to look!" }
WordHunterWoW_QuestEN[71233] = { title = "Falling Water", description = "I love waterfalls. \n\nWant to know what's better than a waterfall? \n\nTwo waterfalls. \n\nAnd the only thing better than that is... well, check out Three-Falls to the west of here and you'll see!\n\nThe innkeeper there is quite nice.", objectives = "Talk to Willa at Three-Falls Lookout in the Azure Span.", completion = "Welcome to Three-Falls Lookout! \n\nWe're pretty high up, and there's rushing water everywhere--so look out!" }
WordHunterWoW_QuestEN[71234] = { title = "Nook News", description = "You there, {race}. \n\nYou look well-travelled. \n\nMy cousin Wayun was bringing a catch over from Whaler's Nook and mentioned that some... strange folk have set up camp over there.\n\nThey appear to be behaving themselves, but would you mind checking in on Wayun?\n\nHe can be a bit salty.", objectives = "Visit Whaler's Nook in the Azure Span.", completion = "Another one?\n\nOh joy." }
WordHunterWoW_QuestEN[71235] = { title = "Field Mages", description = "Lok'tar, {race}. \n\nIf you have the time, we have two mages doing fieldwork nearby who I'm sure could use a hand.\n\nThis is a dangerous land in the best of times. \n\nThese are not the best of times.", objectives = "Check on the Kirin Tor mages near Slyvern Plunge in the Azure Span.", completion = "We don't need your help.\n\nBut we'll take it." }
WordHunterWoW_QuestEN[71238] = { title = "The Ruby Feast!", description = "Attention to all aspiring culinarians!\n\nDoes your heart desire the ultimate flavors of this world? Do you seek out opportunities for grand exploration? Are you willing to risk life and limb for complete strangers?\n\nIf this is you, come speak with the eminently distinguished, world-renowned chef duo, Rumiastrasza and Morsel! Currently hosting The Ruby Feast in the city of Valdrakken!", objectives = "Speak with Chefs Rumiastrasza and Morsel at The Ruby Feast.", completion = "Is this about the posters? Did they actually work?!" }
WordHunterWoW_QuestEN[71239] = { title = "Lost to the Skies", description = "I need a favor, and you look like the favor-doing type.\n\nAn ol' pal of mine, Harleen Chirpsnide, was supposed to meet me in the city a few days ago. We was planning to eat our way through The Ruby Feast, get a trim at the barbershop, then visit that swanky auction house they got here.\n\nBut she ain't shown up. She gets lost in her work plenty, but I'd feel a lot more comfortable knowing where she was.\n\nTry the mountains south of here. She mentioned she'd be swinging by on her way in.", objectives = "Locate Harleen Chirpsnide in the Bluefeather Cliffs.", completion = "Ol' Fizzlecrank is worried, eh? Guess the drinks are on me when I finish up here." }
WordHunterWoW_QuestEN[71241] = { title = "Duck, Duck, Trap", description = "The grove called the Primordial Vale is rich with the magic of the old dragons. A type of slyvern there are prized by my kin for their fur, but they are elusive and hard to find.\n\nInstead of having you try to track them down, you can find some of our hunting traps in the area. Use meat from the nearby waterfowl to reset them - I will send some of our clan to retrieve whatever gets caught.", objectives = "Reset the Clan Aylaag hunting traps at the Primordial Vale.", progress = "The fowl in the area are the preferred source of food for the slyverns.", completion = "Thank you. Our clan will hopefully be able to use the resulting pelts for trade." }
WordHunterWoW_QuestEN[71242] = { title = "Supporting the Storm Researchers", description = "This looks like a large cluster of overflowing power from creatures within the Primalist Storm.\n\nThere's bound to be a researcher in Valdrakken who'll want this.", objectives = "Bring the Elemental Overflow Cluster to a researcher in Valdrakken.\n\nProvided item:", completion = "Oh, marvelous! This is just what we were looking for, thank you." }
