WordHunterWoW_QuestEN[72040] = { title = "Dragon Isles Supplies", description = "", objectives = "Welcome back, adventurer. Looks like you've been authorized a supply allotment increase. Good for you! You certainly have earned it. I know I've told you this before, but we appreciate your help and look forward to what you'll do next!" }
WordHunterWoW_QuestEN[72041] = { title = "Dragon Isles Supplies", description = "", objectives = "Welcome back, adventurer. I am glad that I have been authorized to increase your supply allotment, as you certainly have earned it. I know I tell you this all the time, but I do hope you continue to aid our efforts." }
