WordHunterWoW_QuestEN[72050] = { title = "Balgar", description = "", objectives = "" }
WordHunterWoW_QuestEN[72052] = { title = "Ruby Lifeshrine Loop - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[72058] = { title = "What Hoof We Here: Tarolekk", description = "", objectives = "" }
WordHunterWoW_QuestEN[72060] = { title = "Special Treatment", description = "<The mud mask looks curious about your intentions, but it is cornered on this branch!>", objectives = "Return the sunglasses to Zeldis. Again.", progress = "I know my sunglasses are amazing, but come on now. This is the second time an ooze has run off with them!\n\nHow am I supposed to be gorgeous in these conditions?\n\nWait, did you find them again?!", completion = "Oh, wow. Look at all that snot on them.\n\n<Zeldis pauses.>\n\nYou know, I think they were going out of style anyway.\n\nKeep that sludge away from me. \n\nOr keep it as a pet, whatever floats your boat." }
WordHunterWoW_QuestEN[72061] = { title = "Stormcaller Veldra", description = "", objectives = "" }
WordHunterWoW_QuestEN[72062] = { title = "Valducken", description = "Quack! Quack!\n\n<The mother duck is alerted to your presence.>\n\nQuack quack quack quack! Quack quack quack! Quack quack quack quack quack.\n\n<A gurgling noise from the duck's stomach interrupts her intense quacking. She does not have much food around for her ducklings as she attends to her nest. Perhaps addressing this problem will warm her up to you?>", objectives = "" }
WordHunterWoW_QuestEN[72063] = { title = "Return Yennu's Toy Boat", description = "<This hand made toy boat resembles the ships of the Tuskarr. Yennu, the young Tuskarr, was musing about a boat, it must belong to him>", objectives = "Return the toy boat to Yennu alongside the river in the Ohn'ahran Plains.", completion = "My boat! Thank you so much." }
WordHunterWoW_QuestEN[72067] = { title = "Relaxation Time!", description = "You there! \n\nYou look exhausted. Worn down. In extreme need of some R&R. I have just the thing! The Serene Dreams Spa is the place for you!\n\nEnjoy our new you-ga classes, they are AMAZING! Or perhaps a mud mask facial treatment is more your speed? I recommend both!\n\nTo get to the spa, head north just out of the city!", objectives = "Go to the Serene Dreams Spa.", completion = "How delightful. I am so glad you're joining us! However, we could really use some help." }
WordHunterWoW_QuestEN[72068] = { title = "Aiding the Accord: A Feast For All", description = "Our allies require your aid, {name}!\n\nYour efforts throughout the Isles have not gone unnoticed. Our trusted allies to the south, the Iskaara Tuskarr, seek to celebrate your accomplishments with a feast of all feasts!\n\nJourney to the lands of Iskaara whilst continuing your work alongside the allies of the Accord. When you reach the shimmering waters of the southern lands do not hesitate to participate in the celebrations!", objectives = "Travel to Iskaara in The Azure Span and participate in a Community Feast. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", progress = "Back so soon? Where does the time go?", completion = "You look well-traveled, <name>... and well fed. Your adventurous endeavors bring stability to our lands and comfort to our allies." }
WordHunterWoW_QuestEN[72069] = { title = "Subglacial Refill", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Seems we have caught almost all the fish under the ice. Could you catch some more from the Timbertooth Trail downstream, bring it here, and drop it into an ice hole?", objectives = "Collect fish to restock the fishing hole and throw it into an Ice Hole.", progress = "Have you dropped those fish yet?", completion = "Good work, I can already see more fish flickering under the ice." }
WordHunterWoW_QuestEN[72071] = { title = "Round Two, Fish!", description = "How do you feel about doing a little fishing, then, {name}?\n\nThere's a school of bait fish just offshore that the dumb beast attacks whenever they gather, forgetting that it's already dead.\n\nSwim out there and wave that lure around, maybe do your best impression of a wounded seal, and it won't be able to resist.", objectives = "Slay Mochoby.", progress = "It's out there. I can feel it.", completion = "Now who's up one?" }
WordHunterWoW_QuestEN[72072] = { title = "Dragonsprings Drop", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", objectives = "Collect fish to restock the fishing hole and mount your drake to drop them from above.", progress = "Have you dropped those fish yet?", completion = "Ha! The legends are true, how fantastic!" }
WordHunterWoW_QuestEN[72074] = { title = "Highland Habitat", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", objectives = "Collect fish to restock the fishing hole and mount your drake to drop them from above.", progress = "Have you dropped those fish yet?", completion = "Ha! The legends are true, how fantastic!" }
WordHunterWoW_QuestEN[72075] = { title = "Hot Stock", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lava lakes are not always abundant with hot-loving fish. They say, pools were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", objectives = "Collect fish to restock the fishing hole and mount your drake to drop them from above.", progress = "Have you collected those fish yet?", completion = "Ha! The legends are true, how fantastic!" }
WordHunterWoW_QuestEN[72079] = { title = "Community Feast", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[72083] = { title = "Me Lucky Lure", description = "Ya find me in a low place, {race}, and it's not because I'm dead.\n\nI died on the hunt, making sure the beast that killed me crew wouldn't live to kill again. There's nothing wrong with that, it's what me Pa would have wanted.\n\nNo, the problem is that the fight was a draw!\n\nThe beast's spirit is still out there, as sure as I stand here before ya. But, being a ghost, I can't even reclaim me lucky lure from the critters that picked me body clean to have another go!\n\nWould ya mind helping me out?", objectives = "Recover Captain Haab's Lucky Lure.", progress = "No, I don't know which one ate it. I was busy being dead at the time.", completion = "No fish can resist me lucky lure, living or dead!" }
WordHunterWoW_QuestEN[72089] = { title = "To Skytop Observatory", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[72090] = { title = "Disrupting the Primalist Plan", description = "", objectives = "" }
WordHunterWoW_QuestEN[72113] = { title = "Shapes Beyond the Veil", description = "", objectives = "Greetings, dear friend.\n\nYou have done much to aid us in your time here, but I can sense fate calls you elsewhere.\n\nIn honor of the many souls you have rescued on your journey, and to serve as a guiding light for those you have yet to encounter, please accept this gift. May it serve as a reminder of what wonder life can bring when given a little assistance." }
WordHunterWoW_QuestEN[72114] = { title = "Acrosoth", description = "", objectives = "" }
WordHunterWoW_QuestEN[72116] = { title = "Liskron the Dazzling", description = "", objectives = "" }
WordHunterWoW_QuestEN[72117] = { title = "Cultural Exchange", description = "", objectives = "Outsider, you are proving yourself useful. Let this warm you on cold nights. And when it does, remember that we are friends.\n\n<Huseng grins.>\n\nI see you doing great things for our people, <name>." }
WordHunterWoW_QuestEN[72121] = { title = "The Great Shellkhan", description = "", objectives = "" }
WordHunterWoW_QuestEN[72122] = { title = "Erstwhile Ecologists", description = "The wounded are stabilized, but something still troubles me, {name}.\n\nA pair of dragonspawn ecologists had come to the outpost to study the wetlands. I haven't seen scale nor claw of them since the attack, and it's become worrisome.\n\nIf you're venturing out, would you mind keeping an eye out, and making sure they're safe?\n\nAnd do take care. Rumor has it those wetlands are gorloc-infested.", objectives = "Check in on the wayward ecologists.", completion = "An attack? On Dragonheart Outpost?\n\nWell, that does sound serious. But as you can see, we're dealing with our own crisis here." }
WordHunterWoW_QuestEN[72126] = { title = "Slurpo, the Incredible Snail", description = "", objectives = "" }
WordHunterWoW_QuestEN[72127] = { title = "Captain Lancer", description = "", objectives = "" }
WordHunterWoW_QuestEN[72128] = { title = "Enkine the Voracious", description = "", objectives = "" }
WordHunterWoW_QuestEN[72129] = { title = "Aiding Khadgar", description = "Welcome to Dalaran, {name}. I'm glad you made it through safely.\n\nSpeak to me within the Violet Citadel. There's much to do.", objectives = "Meet Khadgar within the Violet Citadel in Dalaran.", completion = "Good to see you again, <name>. \n\nThe Broken Isles is in in dire need of aid." }
WordHunterWoW_QuestEN[72130] = { title = "Forgotten Gryphon", description = "", objectives = "" }
WordHunterWoW_QuestEN[72131] = { title = "Overstocking", description = "", objectives = "Greetings, dragonrider. I was just looking through my stock of supplies and marveling at the abundance.\n\nThis embarrassment of riches is thanks, in part, to your efforts. It is only right that I offer you a share of it.\n\nBut don't tell anyone. I have a reputation to uphold." }
WordHunterWoW_QuestEN[72134] = { title = "An Adventurer's Aid", description = "We've discovered that there are many issues around the land which we float above, the Broken Isles.\n\nWe'll do what we can from here. I want you to look at the nearby map to see who you can aid first.", objectives = "Use the Scouting Map to choose your first zone.", completion = "Fine choice, adventurer. Let's get to work." }
WordHunterWoW_QuestEN[72135] = { title = "Neltharus: Secrets Within", description = "We have a problem, traveler. The djaradin first emerged from within Neltharus, which means they must be ransacking the halls! \n\nNeltharus contains many treasures. But more importantly, it contains knowledge: the history of our flight and its fall from grace. Both Sabellian and Wrathion have been looking for more information regarding Neltharion's life and work.\n\nGo! See what you can recover before the djaradin plunder it all!", objectives = "Recover from Neltharus 12 Neltharion's Notes, 3 Obsidian Journals, and a Research Tome.\n\nYou can access Neltharius solo by queuing for it in Follower Dungeons.", progress = "Have you found any items?", completion = "These items are wonderful! There is a trove of information here to study!" }
WordHunterWoW_QuestEN[72137] = { title = "Hatchling Plans", description = "", objectives = "My friend, get this thing away from me. Trade for it. Please. They call it a \"Hoofhelper\" but it's really just a nuisance. Always getting in the way. Not nearly big enough to be useful yet. I want it gone.\n\nWhat? No, I can't just give it to you. My wife would never forgive me." }
WordHunterWoW_QuestEN[72154] = { title = "Skag the Thrower", description = "", objectives = "" }
WordHunterWoW_QuestEN[72155] = { title = "Spread the Enchantment", description = "Algeth'ar Academy has put in an order for more enchanting rods. We need everyone to pitch in if we are going to fill the order on time. Could you be of assistance?", objectives = "Craft 2 Runed Draconium Rods for Soragosa in Valdrakken.", progress = "Hurry! We are running out of time!", completion = "Thank you. With this order filled, the Academy will be churning out more enchanters in no time!\n\nHere, study this. Even as a skilled enchanter, there is more for you to learn." }
WordHunterWoW_QuestEN[72156] = { title = "A Fiery Flight", description = "The forge is cooling! Quick, can you help me? Bring me some Rousing Fire. Perhaps it will help!", objectives = "Gather 15 Rousing Fire for Sekita the Burrower in Valdrakken.", progress = "The forge is nearly out! Do you have them?", completion = "Yes, yes!\n\nThis will work.\n\nTake my field notes when you go. There must be something in there that will teach you about mining." }
WordHunterWoW_QuestEN[72157] = { title = "The Weight of Earth", description = "I have an order for several hundred tons of Primal Molten Alloy, but I have run out of Rousing Earth. I know it's a heavy ask, but I can make it worth your while!", objectives = "Gather 15 Rousing Earth for Sekita the Burrower in Valdrakken.", progress = "My clients are breathing down my neck. Do you have them?", completion = "Perfect. Just what I needed.\n\nTake these old field notes. There must be something in there that will teach you about mining." }
WordHunterWoW_QuestEN[72158] = { title = "A Dense Delivery", description = "Our scales are tough, but we can always use more protection. Only the densest of hides will do for our armor--a challenge to gather, but perhaps one you are up to?\n\nI've seen your skills. Go and gather some hides for our stores.", objectives = "Gather 2 Dense Hides for Ralathor the Rugged in Valdrakken.", progress = "Only the best will do for our crafts.", completion = "Ah! These are excellent quality. I was right about you." }
WordHunterWoW_QuestEN[72159] = { title = "Scaling Down", description = "Scales have a multitude of purposes--they offer protection, but in some cases, they also offer a keen reflective surface. Many of our finest mirrors are in fact scales.\n\nThose mirrors also happen to be in high demand. Gather some scaled hides for me, and I'll share some of my crafting secrets.", objectives = "Gather 2 Lustrous Scaled Hides for Ralathor the Rugged in Valdrakken.", progress = "Have you found any hides?", completion = "Ah! These will work perfectly. Your skills continue to impress me.\n\nAs promised, take these notes. I'm sure you can learn more from them." }
WordHunterWoW_QuestEN[72166] = { title = "Proving in Battle", description = "You mortals do so love to squabble over whatever grounds you come across, so be it.\n\nIt will at least be amusing either way. For me, that is. Let us see what how well you can 'prove yourself'.", objectives = "Obtain Honor in Random Battlegrounds.", progress = "Why have you returned? You have proven nothing.", completion = "You succeeded. As to be expected, that was an easy battle. Here take these rewards, they should help if you ever have to be in a real battle." }
WordHunterWoW_QuestEN[72167] = { title = "Proving in War", description = "You wish for a 'real challenge' do you? So be it. I know of some large-scale conflicts that could possibly challenge even me.\n\nI am quite curious to see how you fail... I mean do. Let us see if you can prove yourself to me.", objectives = "Obtain Honor in Epic Battlegrounds.", progress = "Why have you returned? You have proven nothing.", completion = "Well, then. I suppose I am forced to concede my assumptions about you and be impressed. But only a little. Here, you have earned this." }
WordHunterWoW_QuestEN[72168] = { title = "Proving in Skirmishes", description = "You are confident in your tactical abilities, eh? I am told that small-scale skirmishes occur amongst you mortals. Go off and find some rivals to match up against.\n\nLet us see what you can prove, then return to me.", objectives = "Obtain Honor from Arena Skirmishes.", progress = "Why have you returned? You have proven nothing.", completion = "It seems like that went relatively well. You can take these." }
WordHunterWoW_QuestEN[72169] = { title = "Proving in Arenas", description = "You really love conflict, eh? Good news for you - we have that in common. Combatants like yourself meet in predetermined settings to fight each other. Partake in that, and if successful you may be rewarded.\n\nLet us see what you can prove, then return to me.", objectives = "Obtain Honor in Rated Arenas while in a Party.", progress = "Why have you returned? You have proven nothing.", completion = "You did accomplish what you set out to, so here is my end of the bargain." }
WordHunterWoW_QuestEN[72170] = { title = "Proving Teamwork", description = "I am intrigued by how much mortals like you thrive on conflict. I am told there are others like yourself that combat each other in predetermined teams. Seek out some other mortals to join with to attempt this challenge.\n\nLet us see what you can prove, then return to me.", objectives = "Obtain Honor in Rated Battlegrounds.", completion = "I am surprised you were successful in this task. I suppose you have earned these." }
WordHunterWoW_QuestEN[72171] = { title = "Proving Solo", description = "Your eagerness in finding conflict on your own pleases me. If you are that confident in your own skills, well I will be here to watch, for entertainment. \n\nLet's see what you can prove, then return to me.", objectives = "Complete 12 rounds of Solo Shuffle.", progress = "Why have you returned? You have proven nothing.", completion = "It seems like all of your training is starting to pay off. You can take these." }
WordHunterWoW_QuestEN[72172] = { title = "Essence, Shards, and Chromatic Dust", description = "We seem to be in constant need of basic components. Essence, shards... and our stock of Chromatic Dust is almost always depleted.\n\nIf you wouldn't mind helping us stock up, perhaps we can make it more than a day into the week without needing to replenish our supply.", objectives = "Craft 10 Chromatic Dust for Soragosa in Valdrakken.", progress = "We're already out of Chromatic Dust for the day! Have you finished any yet?", completion = "Thank you. I'm sure the supply will last a bit longer this time.\n\nHere, study this in your free time." }
WordHunterWoW_QuestEN[72173] = { title = "Braced for Enchantment", description = "The Dragonscale Expedition has requested some enchantments for their gear.\n\nThe Dragon Isles can be a treacherous place. I don't blame them for needing some bracer upgrades.", objectives = "Craft 2 Writ of Leech for Soragosa in Valdrakken.", progress = "The Dragonscale Expedition await the enchantments.", completion = "I'll get these sent off to the Dragonscale Expedition right away.\n\nTake this to expand your enchanting knowledge." }
WordHunterWoW_QuestEN[72175] = { title = "A Scept-acular Time", description = "There are some exciting orders to fill this week! The students at Algeth'ar Academy have been going horns over heels for these fun scepters.\n\nWhy don't you assist with some of the scepters?", objectives = "Craft 3 Scepter of Spectacle: Fire and 3 Scepter of Spectacle: Air for Soragosa in Valdrakken.", progress = "The Algeth'ar students are getting restless.", completion = "Wonderful! The students will love these.\n\nTake this to expand your enchanting knowledge." }
WordHunterWoW_QuestEN[72181] = { title = "LFGDungeons - DF - Normal Random - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[72182] = { title = "LFGDungeons - DF - Normal Random - Nth", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[72184] = { title = "LFGDungeons - DF - Raid Finder - 1st", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[72185] = { title = "LFGDungeons - DF - Raid Finder - Nth", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[72187] = { title = "LFGDungeons - DF - Heroic Random - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[72188] = { title = "LFGDungeons - DF - Heroic Random - Nth", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[72189] = { title = "Garden Variety", description = "Are you enjoying the butterfly garden?\n\nYou know, there's a much larger garden just to the south of here. An older drakonid by the name of Gryrmpech tends to it.\n\nHe could always use an extra pair of hands. He has an 'assistant', but I've never actually seen him. I can't imagine he's of much help.\n\nIf you stop by, be sure to let him know that Xina sent you.", objectives = "Speak with Gyrympech.", completion = "Oh praise the Titans, help at last!" }
WordHunterWoW_QuestEN[72190] = { title = "Reservoir Reservations", description = "{class}! I know someone who is in dire need of your skills.\n\nTyrhold Reservoir has just been attacked by Primalists. I was lucky to make my escape when I did. I fear the others may not be so lucky.\n\nIt's just to the north of here. Find Zuttiki, she'll be able to fill you in on the details.\n\nIf she's still alive, that is.", objectives = "Find Zuttiki.", completion = "Talikka made it out alive?" }
WordHunterWoW_QuestEN[72191] = { title = "Short-Supply Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[72192] = { title = "Halls of Infusion: Entropy to Order", description = "The Primalists wish to bring elemental chaos back to this world and will stop at nothing to see their goal accomplished.\n\nI have received disturbing news that they have infiltrated the Halls of Infusion deep below Tyrhold. They attempt to disrupt the works of Keeper Tyr for their own nefarious purposes.\n\nPlease, you must put an end to any Primalist threat within those sacred halls, {name}.", objectives = "Enter the Halls of Infusion and defeat the Primal Tsunami.\n\nYou can access the Halls of Infusion solo by queuing for it in Follower Dungeons.", progress = "Have you cleared the halls of Primalist threat, <name>?", completion = "The Halls of Infusion are once again safe thanks to your assistance, <name>." }
WordHunterWoW_QuestEN[72193] = { title = "The Algeth'ar Academy", description = "I understand that the Algeth'ar Academy is open to the world once more. \n\nLong ago, its sacred halls were only open to dragons, but in the years that have passed the Headteacher has seen the wisdom of welcoming any who wish to learn. She has asked for my recommendation on any promising new students. \n\nAs a great ally to dragonkind, it would be an honor to have you attend our great academy. I leave the decision to enroll up to you, but I am sure Doragosa would love to at least give you a tour.", objectives = "Tour the grounds of Algeth'ar Academy.\n\nYou can access Algeth'ar Academy solo by queuing for it in Follower Dungeons.", progress = "I hope you enjoy your time at the Academy. It really is a remarkable place.", completion = "It seems you had an eventful first day. It's a good thing you're accustomed to the unexpected." }
WordHunterWoW_QuestEN[72240] = { title = "The Obsidian Warders", description = "This Toddy's enthusiasm is admirable. But I hope it does not blind her to the dangers awaiting us in the Dragon Isles.\n\nRegardless, the Obsidian Warders are duty-bound to protect the expedition.\n\nI must speak with Wrathion and the Lord Commander about the mission ahead.\n\nMy fellow dracthyr are exploring the city. Seek out Dervishian, my trusted lieutenant, and inform her that we are to rally at the docks. She will relay my orders to the rest.", objectives = "Deliver the scalecommander's orders to Dervishian and the Obsidian Warders.", progress = "Ye think a dracthyr can fly faster than a gryphon?", completion = "I'm pleased the dracthyr are comin' with us.\n\nCan't wait to challenge that scalecommander to a race on ol' Wildfeather.\n\nMy gryphon will best his leathery ol' wings any day!" }
WordHunterWoW_QuestEN[72241] = { title = "Lessons From Our Past", description = "I am Emberthal, a scalecommander of the dracthyr. Wrathion aided us after we awakened from our long stasis, and now it is my turn to help him.\n\nNo doubt you have questions about my people and our history. Until recently, I did as well. \n\nBut Nozdormu, the Timeless One, has revealed lost truths about the dracthyr. He granted me a vision of our origins... and why we were locked away. \n\nLet me tell you of the things I have seen.", objectives = "Speak with Scalecommander Emberthal.", progress = "There is much we can learn from one another.", completion = "Now you know the truth.\n\nThe past is the past. It is time for the dracthyr to seek a new future alongside the other peoples of Azeroth." }
WordHunterWoW_QuestEN[72242] = { title = "Dragon Isles Engineering", description = "", objectives = "Hi there! Welcome to the Dragon Isles! Hey, you seem like a fellow explosion enthusiast. Can I show you a couple gadgets I've been working on?\n\nI can teach you some new engineering schematics!" }
WordHunterWoW_QuestEN[72243] = { title = "Dragon Isles Herbalism", description = "", objectives = "Welcome to the Dragon Isles, friend!\n\nThis verdant land is so different and so beautiful. Of course, as an herbalist you would know this!\n\nI can show you how to locate the herbs unique to the Dragon Isles, if you would like." }
WordHunterWoW_QuestEN[72244] = { title = "Dragon Isles Inscription", description = "", objectives = "Good day!\n\nYou must be the new scribe. Let me show you what I've translated so far of these draconic glyphs.\n\nI can teach you new inscription techniques of the Dragon Isles." }
WordHunterWoW_QuestEN[72245] = { title = "Dragon Isles Alchemy", description = "", objectives = "Welcome to the Dragon Isles! You seem like a skilled alchemist. Can I share with you some of what I've learned about draconic techniques?\n\nI can teach you everything I know about alchemy. Then you can explore the Isles, too." }
WordHunterWoW_QuestEN[72246] = { title = "Serene Dreams", description = "Welcome to the Serene Dreams Spa!\n\nI must apologize. We are not able to admit new guests at this time due to circumstances beyond our control.\n\nLet me refer you to the Spa Manager, Xijan Thornpaw. He is qualified to answer all your questions.", objectives = "Speak to the spa manager.", completion = "Welcome to the Serene Dreams Spa! With us, you may partake of many relaxing activities!\n\nOh! Are you here to help? I would be honored to have your assistance." }
WordHunterWoW_QuestEN[72247] = { title = "Dragon Isles Jewelcrafting", description = "", objectives = "Hey, you. You like smooth things? Shiny things?\n\nLook at you. Of course you do.\n\nI can teach you how to make the smoothest, shiniest things imaginable. Just say the word. I'll make it happen." }
WordHunterWoW_QuestEN[72249] = { title = "Dragon Isles Tailoring", description = "", objectives = "<Zayn looks up and down your outfit with a judgmental eye.>\n\nAllow me to give you a few pointers in tailoring." }
WordHunterWoW_QuestEN[72250] = { title = "Dragon Isles Cooking", description = "", objectives = "<Head Chef Stacks makes a series of cooking-related sounds and gestures. His whisks whirl! His burners bluster and spit! He bangs on his frying pan with the gravity of a great gong!\n\nThe entire inn applauds his wisdom.\n\nIn watching this elaborate pantomime, you find yourself miraculously better at cooking.>" }
WordHunterWoW_QuestEN[72251] = { title = "Dragon Isles Cooking", description = "", objectives = "<Head Chef Stacks makes a series of cooking-related sounds and gestures. His whisks whirl! His burners bluster and spit! He bangs on his frying pan with the gravity of a great gong!\n\nThe entire tent applauds his wisdom.\n\nIn watching this elaborate pantomime, you find yourself miraculously better at cooking.>" }
WordHunterWoW_QuestEN[72252] = { title = "Dragon Isles Fishing", description = "", objectives = "Come to join the hunt? Um, I mean... the fish? The fishing hunt?\n\n<Danielle adjusts her grip on her fishing rod with an awkward cough.>\n\nYou look like you know a thing or two about fishing, anyway. Here, let me show you how fishing works on these isles." }
WordHunterWoW_QuestEN[72253] = { title = "Dragon Isles Fishing", description = "", objectives = "Fishing is all about feeling the water beneath you. Eventually the water becomes the sky, and the sky becomes the water, and you are floating amongst the clouds, like a kite! And your fishing rod is your kite string!\n\n...or perhaps that is the volcanic fumes. But either way, fishing is very relaxing. I would delight in sharing the art with you." }
WordHunterWoW_QuestEN[72254] = { title = "Fisherman Tinnak's Ghost", description = "", objectives = "" }
WordHunterWoW_QuestEN[72256] = { title = "The Dark Talons", description = "Naleidea is enthusiastic, but she's a historian, not a soldier. She knows nothing of the dangers we'll face in the Dragon Isles.\n\nNot that anyone needs to worry. After all, the Dark Talons will be protecting the expedition.\n\nI'm going to discuss mission logistics with Ebyssian and your Horde leaders.\n\nMy lieutenant, Kodethi, is exploring the city along with the other dracthyr. Be a good soldier and let him know we are going to rally at the zeppelin tower. He'll relay my orders to the others.", objectives = "Deliver the Scalecommander's orders to Kodethi and the Dark Talons.", progress = "Do you suspect that a dracthyr could outpace a boat over the entire trip to the Dragon Isles? Exhaustion would take its toll, surely?", completion = "I am pleased to have the dracthyr accompanying us on the expedition.\n\nTheir unique perspective should prove valuable, and learning more of their own history will help them come to terms with their current circumstances.\n\nAs I've said before, history heals every wound." }
WordHunterWoW_QuestEN[72259] = { title = "Vault Artifacts", description = "", objectives = "Have you found another artifact?", progress = "Have you found another artifact?", completion = "As you bring me more artifacts, our knowledge of the Incarnates and their time period increases.  \n\nYou have my thanks. As a member of the Dragonscale Expedition, I want you to know how important your contributions are. And as a researcher, I want you to know the wealth of discoveries I have made from the artifacts you have brought me is a long-time dream come true. \n\nPlease, take these supplies and use them well." }
WordHunterWoW_QuestEN[72260] = { title = "Vault Artifacts", description = "", objectives = "Have you found more artifacts?", progress = "Have you found more artifacts?", completion = "Thank you again for your generous contribution of artifacts.\n\nOur study of the Incarnates continues successfully largely due to your dedicating to finding and donating artifacts. Your patronage of the Dragonscale Expedition is truly appreciated. \n\nPlease, have more supplies on us!" }
WordHunterWoW_QuestEN[72261] = { title = "More Than a Prison?", description = "<The ancient artifact appears elemental in nature. Lillian Brightmoon in Valdrakken might be able to tell more.>", objectives = "Bring the Ancient Vault Artifact to Lillian Brightmoon.", progress = "Have you brought me something to study?", completion = "The Incarnates were locked away in the Vault, but aside from that we know very little either about it or its prisoners.\n\nArtifacts like this can shed light on their culture, their history, and... their power. Studying them could improve our odds in defeating the primalists. Bring me more of these I will reward you with supplies.\n\nOh, and I will pen a note to Caretaker Jakes reminding her of your continued assistance of the Dragonscale Expedition." }
WordHunterWoW_QuestEN[72263] = { title = "Cavalry Has Its Place", description = "Evoker! This place still has herds of vorquin!\n\nI managed to round a few up that could be used as mounts for when your wings are tired. Remember how to ride?\n\nThis one is to be issued to you as the scalecommanders are ordering you all over the place. Please take good care of it.", objectives = "Learn to ride your personal vorquin mount.", completion = "<class>, this place still has herds of vorquin!\n\nI managed to round up a few of the more agreeable creatures that could be used as mounts for when your wings are tired. Remember how to ride?\n\nI was ordered to issue one to you as the scalecommanders are ordering you all over the place. Take good care of it." }
WordHunterWoW_QuestEN[72266] = { title = "The Waking Shores", description = "The drakonid Sendrax is looking for help in aiding all of the newcomers within the Waking Shores.", objectives = "Meet with Sendrax within the Waking Shores.", completion = "Oh, hello! I do have a good idea on what you can do to help us out now." }
WordHunterWoW_QuestEN[72267] = { title = "Ohn'ahran Plains", description = "The green dragonflight needs the aid of adventurers. To do so, you must ally with the centaur of the plains.\n\nAmbassador Taurasza can be of aid.", objectives = "Meet Ambassador Taurasza in the Rubyscale Outpost.", completion = "We have much to discuss, you and I." }
WordHunterWoW_QuestEN[72268] = { title = "Azure Span", description = "The Kirin Tor need all the help they can get tracking down the Blue Dragon Oathstone.\n\nSome of their mages have been spotted in the Ohn'ahran Plains looking for help.", objectives = "Speak with Masud the Wise within the Ohn'ahran Plains.", completion = "Ah, another adventurer! We could use your aid." }
WordHunterWoW_QuestEN[72269] = { title = "Thaldraszus", description = "Alexstrasza the Life-Binder is arranging a meeting of the Seat of the Aspects to discuss the threat of the Primalists.\n\nShe has put out a call for any willing adventurers to come help.", objectives = "Travel to Valdrakken and meet with Alexstrasza the Life-Binder.", completion = "Welcome to Valdrakken, <name>. Let us begin." }
WordHunterWoW_QuestEN[72279] = { title = "Dragon Isles Supplies", description = "", objectives = "Greetings adventurer. Please, take these supplies to aid you in your efforts to help our community!" }
WordHunterWoW_QuestEN[72280] = { title = "Dragon Isles Supplies", description = "", objectives = "Welcome, <race>. I have more supplies for you in thanks for your continued support of our community. May your steps be sure and your catch secure!" }
WordHunterWoW_QuestEN[72281] = { title = "Dragon Isles Supplies", description = "", objectives = "Ah, our paths meet again, <name>. I am glad you have returned to us safely. Your deeds have made you honored among the Iskaara. Please, take these supplies as a token of our thanks!" }
WordHunterWoW_QuestEN[72282] = { title = "Renown Supplies", description = "", objectives = "Greetings, <class>. You've proved your worth to the Valdrakken Accord. Here are some supplies to help you aid our cause. Don't let us down!" }
WordHunterWoW_QuestEN[72283] = { title = "Renown Supplies", description = "", objectives = "Your victories against the Primalists have caught the attention of the Accord, <class>. They have decided to reward you handsomely... in the hopes you will continue fighting for the cause, of course. \n\nPlease, take this larger allotment of supplies. Use them to defend the Dragon Isles!" }
WordHunterWoW_QuestEN[72284] = { title = "Renown Supplies", description = "", objectives = "<name>! The <class> everyone in the Valdrakken Accord knows by name. Your feats have far outstripped my... I mean... our expectations.\n\nAs a reward, the Accord has allotted for you their finest supplies. They hope you may be part of the answer to the Primalist threat." }
WordHunterWoW_QuestEN[72291] = { title = "Story of a Memorable Victory", description = "That was a good fight! \n\nElder Poa in Iskaara will be interested in listening to the story of that victory.", objectives = "Tell the story of your victory to Elder Poa in Iskaara.", progress = "The most amazing stories might happen with anyone.\n\nOur deeds make us who we are, and I'm always eager to learn of the most impressive acts and make them inspiration to others.", completion = "What's that? You have a story for me? Sit down, let me hear it!\n\n<Elder Poa listens to your tale of a victory over a peculiar foe.>\n\nThat was thrilling! Thank you for sharing that with me, young one." }
WordHunterWoW_QuestEN[72292] = { title = "Story of a Spectacular Victory", description = "That was a majestic fight!\n\nElder Poa in Iskaara will be interested in listening to the story of that impressive victory.", objectives = "Tell the story of your victory to Elder Poa in Iskaara.", progress = "The most amazing stories might happen with anyone. Especially if one fearlessly ventures into an enemy lair...\n\nOur deeds make us who we are, and I'm always eager to learn of the most impressive acts and make them inspiration to others.", completion = "Oh, you have a story for me? Sit down, let me hear it.\n\n<Elder Poa listens to your tale of a victory over a peculiar foe.>\n\nThat was thrilling! Thank you for sharing that with me, young one. I will remember this tale!" }
WordHunterWoW_QuestEN[72293] = { title = "Adventuring in the Dragon Isles", description = "Oh, I know what you can do!\n\nThe Dragonscale Expedition has posted a very fine looking map of the Dragon Isles nearby. \n\nTheir drawings are quite accurate and detailed, if I do say so myself. Sorry, you're not here for an art review.\n\nYou should go check it out to see what areas of the Dragon Isles could use your help!", objectives = "Review the Scouting Map to choose an area within the Dragon Isles to support.", completion = "<Your decision has been made. You can return to the scouting map at any time to choose another location.>" }
WordHunterWoW_QuestEN[72294] = { title = "Expedition Crafting Knowledge", description = "", objectives = "Lok'tar, adventurer. You must be the new scribe helping out the expedition! I was told to pass along this notebook. Our scribes put their pens together for a few notes to help jump start your crafting here in the Dragon Isles. Come back to me when you're through with them. I may have more for you." }
WordHunterWoW_QuestEN[72295] = { title = "Expedition Crafting Knowledge", description = "", objectives = "There's my favorite hardworking scribe! Everyone's been talking about the quality of your inscription work, <name>. To reward you, I've asked the master scribes to come up with more instructions and exercises to help you master your craft. You've done me proud, <class>. Now get back to work!" }
WordHunterWoW_QuestEN[72296] = { title = "A Gift of Knowledge", description = "", objectives = "Ah, dragonrider! I know that you're a leatherworker of no small skill, but we Maruuk have methods you would do well to learn.\n\nOur crafters assembled these notes to aid your progress. Perhaps you'll visit with them and share some of your knowledge as well.\n\nBetween friends, there are no secrets under the sky!" }
WordHunterWoW_QuestEN[72297] = { title = "A Gift of Secrets", description = "", objectives = "<name>, the heart of a centaur beasts within you... and you have shown greater dedication to your craft than we could ever have imagined.\n\nWhen last we spoke of your leatherworking skills, I shared the first portion of our masters' crafting wisdom. But you have proven there are no techniques you cannot master.\n\nHere are the rest of their notes. I know you will make good use of them." }
WordHunterWoW_QuestEN[72298] = { title = "Valdrakken Accord", description = "Assist the tortollans by completing 3 world quests.Upon completion of this quest you will gain:", objectives = "Complete 3 tortollan world quests.Assist the tortollans by completing 3 world quests.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[72299] = { title = "Expedition Crafting Knowledge", description = "", objectives = "Enchanting, eh?\n\n<Boss Magor looks at a list.>\n\nYep, we need more of those. No experience? No problem! I've got a manual here that will help you get started. Spend some time honing your skills, and I may have more to give you to help. Welcome to the Dragon Isles, <race>." }
WordHunterWoW_QuestEN[72300] = { title = "Expedition Crafting Knowledge", description = "", objectives = "An engineer! We have need of your skill here in the Dragonscale Expedition. I have some schematics and notes put together by some master engineers in Orgrimmar. I've been asked to pass them along to anyone on the expedition that has an interest in engineering. Practice, and later on I may have more that will help increase your skill." }
WordHunterWoW_QuestEN[72301] = { title = "Expedition Crafting Knowledge", description = "", objectives = "We need professionals and crafters of every kind in the expedition. Even jewelcrafters! Don't know much about jewelcrafting myself, but I have a book here donated by a master jewelcrafter that will help you get started. Hone your skill and come back to me. I may have more to help you later." }
WordHunterWoW_QuestEN[72302] = { title = "Expedition Crafting Knowledge", description = "", objectives = "So you're here to mine the new frontier, eh? Well, you'll definitely have that opportunity here on the expedition. Got an old miner's almanac here for you if you want to study up on your skills. Swing your pickaxe a few times and get a feel for it then come back to me. I'm sure there are more books and notes around that'll help you out." }
WordHunterWoW_QuestEN[72303] = { title = "Expedition Crafting Knowledge", description = "", objectives = "Ah, you're a tailor you say? Good. I can't even thread a needle, but I have some patterns left by the last expedition tailor that you can practice on. Once you're ready for more, come back and I may have something else that well help you.\n\nWhat happened to the last tailor? Why, it's said that at night you can still hear him... Nah, just kidding. Went home to be with his family." }
WordHunterWoW_QuestEN[72304] = { title = "Expedition Crafting Knowledge", description = "", objectives = "Back already, enchanter? Good for you! We need more hard workers here in the expedition. If you're ready for more work, I've got another, more advanced manual here for you. Keep up the good work!" }
WordHunterWoW_QuestEN[72305] = { title = "Expedition Crafting Knowledge", description = "", objectives = "Throm-ka, engineer. Seems you've been busy! Your feats of engineering have not been unnoticed by the Dragonscale Expedition! I've received more advanced schematics for you to try. You've impressed some important people, it seems. Keep up the good work, <name>!" }
WordHunterWoW_QuestEN[72306] = { title = "Expedition Crafting Knowledge", description = "", objectives = "<name>! You've made your mark on the Dragonscale Expedition with your jewelcrafting skill. When people think \"jewelcrafting,\" they think \"<name>!\" And I've got just what you need to cement your reputation: a book on advanced jewelcrafting. Maybe it will help you master your craft, eh?" }
WordHunterWoW_QuestEN[72307] = { title = "Thieving Gnolls", description = "", objectives = "" }
WordHunterWoW_QuestEN[72308] = { title = "Expedition Crafting Knowledge", description = "", objectives = "<name>! Glad to see you've safely returned. I admit I was a bit worried about you out there mining the wilds of the Dragon Isles. Your mining has been very helpful to the Dragonscale Expedition, but if you want to help out more, here's an advanced almanac that can help you increase your skill." }
WordHunterWoW_QuestEN[72309] = { title = "Expedition Crafting Knowledge", description = "", objectives = "Welcome back, tailor. I hear you're doing well for yourself. Many say you're... a cut above the rest! I'm sorry, <name>. I couldn't resist. If you'd like to stay there, here are more patterns and notes to improve your tailoring courtesy of the Dragonscale Expedition. Good luck!" }
WordHunterWoW_QuestEN[72310] = { title = "A Gift of Knowledge", description = "", objectives = "Ah, dragonrider! I know that you're a skinner of no small skill, but we Maruuk have methods you would do well to learn.\n\nOur skinners assembled these notes to aid your progress. Perhaps you'll visit with them and share some of your knowledge as well.\n\nBetween friends, there are no secrets under the sky!" }
WordHunterWoW_QuestEN[72311] = { title = "A Gift of Knowledge", description = "", objectives = "Ah, dragonrider! I know that you're a alchemist of no small skill, but we Maruuk have methods you would do well to learn.\n\nOur alchemists assembled these notes to aid your progress. Perhaps you'll visit with them and share some of your knowledge as well.\n\nBetween friends, there are no secrets under the sky!" }
WordHunterWoW_QuestEN[72312] = { title = "A Gift of Knowledge", description = "", objectives = "Ah, dragonrider! I know that you're a blacksmith of no small skill, but we Maruuk have methods you would do well to learn.\n\nOur smiths assembled these notes to aid your progress. Perhaps you'll visit with them and share some of your knowledge as well.\n\nBetween friends, there are no secrets under the sky!" }
WordHunterWoW_QuestEN[72313] = { title = "A Gift of Knowledge", description = "", objectives = "Ah, dragonrider! I know that you're a herbalist of no small skill, but we Maruuk have methods you would do well to learn.\n\nOur herbalists assembled these notes to aid your progress. Perhaps you'll visit with them and share some of your knowledge as well.\n\nBetween friends, there are no secrets under the sky!" }
WordHunterWoW_QuestEN[72314] = { title = "A Gift of Secrets", description = "", objectives = "<name>, the heart of a centaur beasts within you... and you have shown greater dedication to your craft than we could ever have imagined.\n\nWhen last we spoke of your alchemy skills, I shared the first portion of our masters' crafting wisdom. But you have proven there are no techniques you cannot master.\n\nHere are the rest of their notes. I know you will make good use of them." }
WordHunterWoW_QuestEN[72315] = { title = "A Gift of Secrets", description = "", objectives = "<name>, the heart of a centaur beasts within you... and you have shown greater dedication to your craft than we could ever have imagined.\n\nWhen last we spoke of your blacksmithing skills, I shared the first portion of our masters' crafting wisdom. But you have proven there are no techniques you cannot master.\n\nHere are the rest of their notes. I know you will make good use of them." }
WordHunterWoW_QuestEN[72316] = { title = "A Gift of Secrets", description = "", objectives = "<name>, the heart of a centaur beats within you... and you have shown greater dedication to your craft than we could ever have imagined.\n\nWhen last we spoke of your herbalism skills, I shared the first portion of our masters' crafting wisdom. But you have proven there are no techniques you cannot master.\n\nHere are the rest of their notes. I know you will make good use of them." }
WordHunterWoW_QuestEN[72317] = { title = "A Gift of Secrets", description = "", objectives = "<name>, the heart of a centaur beasts within you... and you have shown greater dedication to your craft than we could ever have imagined.\n\nWhen last we spoke of your skinning skills, I shared the first portion of our masters' crafting wisdom. But you have proven there are no techniques you cannot master.\n\nHere are the rest of their notes. I know you will make good use of them." }
WordHunterWoW_QuestEN[72318] = { title = "Iskaaran Crafter's Knowledge", description = "", objectives = "Ah, an enchanter! One who appreciates an ancient art.\n\nOur ancestors were master enchanters. Now that you are helping us, we'll share our knowledge with you. With enemies all around us we must demand the best from everyone in our community, and I hope that includes you as well. \n\nHere are notes that should get you caught up on the basics. Speak to me when you wish to learn more." }
WordHunterWoW_QuestEN[72319] = { title = "Iskaaran Crafter's Knowledge", description = "", objectives = "A fellow lover of nature! Good.\n\nAll tuskarr respect the cycle of nature. Herbalists are highly regarded in our community! We have a long tradition of using the gifts of the land in both ritual and medicine. Our elder herbalists are very learned but also... tend to keep to themselves. But they have left behind notes and drawings for those who want to follow their path into the wilderness. Use them well and come back to me for more learning later." }
WordHunterWoW_QuestEN[72320] = { title = "Iskaaran Crafter's Knowledge", description = "", objectives = "Jewelcrafting? Hm, the profession always appealed to me. Who wouldn't be tempted by the glittering treasures of the earth?\n\nLike many of your kind, we have perfected the art of jewelcrafting. And we've also preserved our knowledge for the future. If you wish to help us, jewelcrafter, we can share our knowledge." }
WordHunterWoW_QuestEN[72321] = { title = "Iskaaran Crafter's Knowledge", description = "", objectives = "Greetings, leatherworker.\n\nWe tuskarr prize our ability to work with leather. Our culture has used skins and fur to protect us from the elements and from injury for many generations. You'll find no finer leatherwork anywhere. Because you wish to help us, we'll share our skills with you. I have here patterns and notes that will put you on the path to mastery of tuskarr leatherwork." }
WordHunterWoW_QuestEN[72322] = { title = "Iskaaran Crafter's Knowledge", description = "", objectives = "You wish to learn about skinning? You've come to the right people.\n\nWe pride ourselves on the quality of our hides and furs. Our hunts bring back only the finest pelts, and our hunters guard their secrets carefully. Or at least some do. I have notes from some of our most prolific hunters that I can share with you. It should get you started skinning like a tuskarr!" }
WordHunterWoW_QuestEN[72323] = { title = "Iskaaran Crafting Mastery", description = "", objectives = "The aspiring enchanter returns! Have you mastered your first studies? Good!\n\nNormally, you would now be assigned an enchanter mentor to guide you. But these are desperate times. Instead, I have more notes from out master enchanters. May they serve you well, and may you use them to help our community." }
WordHunterWoW_QuestEN[72324] = { title = "Iskaaran Crafting Mastery", description = "", objectives = "Hail, herbalist! I see you have returned from your travels in the wilderness.\n\nI've heard rumors that your talents have grown, and you've greatly aided our community. In thanks, I have gathered more notes and drawings for you to help you increase your skill. May you use them well!" }
WordHunterWoW_QuestEN[72325] = { title = "Iskaaran Crafting Mastery", description = "", objectives = "Jewelcrafter! I am glad to see you again.\n\nI've heard whispers that your jewelcrafting rivals that of the most talented craft masters. I wouldn't know. Both a fine gem and glass glitter to me! But what I do know is that your bravery continues to help our community. As a reward, I have gathered more notes from our craft masters to give to you." }
WordHunterWoW_QuestEN[72326] = { title = "Iskaaran Crafting Mastery", description = "", objectives = "Leatherworker! It is good to see you return.\n\nI trust you want to learn more of our leatherworking secrets. Ha ha ha! Of course you do. I will not keep them from you. Your bravery has made you famous among our people. Here... I have more patterns and notes to help you master your craft. One day we may not be able to tell your leatherwork from our own!" }
WordHunterWoW_QuestEN[72327] = { title = "Iskaaran Crafting Mastery", description = "", objectives = "Ah, our aspiring skinner has returned. I can tell by your hands you have been hard at work. Excellent!\n\nOn a normal day in a normal time, I would help find a master to guide you. But this is not a normal day or time, and we must manage with what we have. Please, accept these notes to help you master your craft. Your work and your bravery make you a valued friend of the tuskarr." }
WordHunterWoW_QuestEN[72328] = { title = "Our Ferocious, Armored Steeds", description = "", objectives = "Hello again, friend! Do you think another ottuk will bond with you? Well, we shall see. \n\nI will leave you and the ottuks to feel out if there is another bond. I will say that a pack of ottuk fighting together is a fearsome sight. I almost pity your enemies!  \n\nI remind you that ottuk tack is expensive, especially war kit. If you wish to train another one, my fellow trainers and I must ask for a large trade." }
WordHunterWoW_QuestEN[72329] = { title = "Crafting Your Start", description = "", objectives = "A blacksmith, eh? If you want to spend your days covered in soot, be my guest. \n\nBut if you want to learn blacksmithing from our masters, you need to put some work in. They've left notes for people like you who want to improve. \n\nTake them. They're a little singed, but legible. Get some practice in and maybe they'll help you in person later on." }
WordHunterWoW_QuestEN[72330] = { title = "Crafting Your Start", description = "", objectives = "So you want to be an engineer, eh? I'll bet you want to learn from our master engineers too.\n\nGood luck then. Their time and skills are too in demand for them to make time for \"aspiring\" engineers.\n\nI'll tell you what... I have some of their notes handy. Maybe if you practice on the schematics they've jotted down, you'll show your skill and get their attention!" }
WordHunterWoW_QuestEN[72331] = { title = "Crafting Your Start", description = "", objectives = "Inscription? A noble pursuit. It requires a keen mind, a steady hand, and quiet.\n\nIf you're looking for training, I don't think you'll make any friends of our master scribes by disturbing them. But I do have some notes they left here for those who want to learn their art.\n\nPerhaps if you practice from their notes, they will gift you with greater knowledge later!" }
WordHunterWoW_QuestEN[72332] = { title = "Crafting Your Start", description = "", objectives = "You'd like to learn about mining? Really? Do you enjoy wandering around in the dark? Or do you just really like explosives?\n\nNo, don't tell me. Probably best not to know.\n\nOur master miners are away doing what they do best. But I do have some notes that they left for aspiring miners. Sorry about all the smudges and scribbles. I imagine it's hard to write by headlamp light." }
WordHunterWoW_QuestEN[72333] = { title = "Crafting Your Start", description = "", objectives = "You want to learn tailoring from our masters?\n\n<Dothenos looks you up and down and frowns>\n\nWell, I wouldn't go calling on them in that outfit. Here... I have some patterns they selected for aspiring tailors to try. Get some practice in and come back to me later--preferably in something more fashionable, <race>." }
WordHunterWoW_QuestEN[72334] = { title = "Crafting for Expertise", description = "", objectives = "Ah, you have returned! I knew that you would.\n\nOur master scribes have seen your work and are proud to call you one of their own. They have passed along these meticulously crafted notes for you to further your studies.\n\nWell done, scribe!" }
WordHunterWoW_QuestEN[72335] = { title = "Crafting for Expertise", description = "", objectives = "Been hard at work, <name>? I can tell. You're a shade paler than you were before. Occupational hazard, isn't it?\n\nOur master miners have heard word of your diligence and have left you more of their notes to help increase your skill.\n\nIf you get to work now, I'm sure you'll be a master in no time!" }
WordHunterWoW_QuestEN[72336] = { title = "Crafting for Expertise", description = "", objectives = "<Dothenos looks you up and down again.>\n\nHmph, well... fashion is subjective, I suppose. But I can't argue with results.\n\nYour tailoring prowess has attracted the attention of our tailoring masters. Here are more patterns and notes to help you achieve even higher levels of expertise!" }
WordHunterWoW_QuestEN[72337] = { title = "Greater Obsidian Key", description = "Bring me an assembled Key", objectives = "Collect 1 Assembled Key", progress = "Find me a Greater Obsidian key, and we shall unlock the full potential of the Obsidian Citadel.", completion = "This key will allow us to access more of the Citadel's lost secrets." }
WordHunterWoW_QuestEN[72338] = { title = "Greater Obsidian Key", description = "Bring me an assembled Key", objectives = "Collect 1 Assembled Key", progress = "Find me a Greater Obsidian key, and we shall unlock the full potential of the Obsidian Citadel.", completion = "This key will allow us to access more of the Citadel's lost secrets." }
WordHunterWoW_QuestEN[72339] = { title = "Engine of Innovation", description = "Tyr believed that the Engine of Innovation would be necessary for the battles to come. \n\nYou have proven yourself worthy and overcome all the challenges set before you. You may now unlock Engine's full potential.", objectives = "Insert the newly attuned Power Core into the Engine of Innovation.", completion = "You have proven yourself worthy and overcome all the challenges set before you. \n\nYou may now unlock the Engine's full potential." }
WordHunterWoW_QuestEN[72354] = { title = "The Great Vault", description = "Over the years, the Aspects and their kin acquired many remarkable artifacts and armaments. The Aspects ordered the construction of an enchanted vault where they could be stored for safe-keeping until such a time as a worthy soul came in search of that which lay within.\n\nYou will find this Great Vault within the walls of the bank. Perhaps, if you prove your mettle, it will grant you a piece of the Aspects' ancient hoard.", objectives = "Obtain a piece of loot from the Great Vault.", progress = "The vault seems to know when a worthy soul approaches. You need not be afraid. Go on. Give it a look.", completion = "So you were able to open it after all? Even those ancient magics recognize your knack for heroic exploits. \n\nIt would be wise to check the vault regularly. No doubt the treasures that lie within will prove useful in the battles to come." }
WordHunterWoW_QuestEN[72358] = { title = "Cascade", description = "", objectives = "" }
WordHunterWoW_QuestEN[72360] = { title = "Reviving the Machine", description = "Like all Titanic artifice, Tyrhold contains many wonders. Long ago, Keeper Tyr left behind a machine called the Revival Catalyst for the Aspects so that they could empower their forces should the need for battle arise. It holds great power.\n\nAs an ally of dragonkind, they offer the use of this machine to help you brave the trials that are to come. But first, you must seek it out. The catalyst is a great boon, and will provide a keen advantage against your foes should you make use of it.", objectives = "Seek the Revival Catalyst.", progress = "Hail, adventurer. What would you ask of me?", completion = "Keeper Tyr knew that conflict would be inevitable. To aid his friends, he created the Revival Catalyst.\n\nIts function is quite remarkable. Offer the catalyst one of the pieces of equipment you have acquired during your travels and it shall be imbued with the wisdom and might of Tyr himself. Imbue enough pieces and you may even find your skills revived in new and unique ways." }
WordHunterWoW_QuestEN[72363] = { title = "Good at Doings, Not Understandings", description = "", objectives = "Ah, dragonrider. Welcome back. Here's some dust. No, I don't know what it really is either. The Ohn'ir mystics say it's supposed to help you commune with our ancestors. That the ancestors are all around us. Seems optimistic, if you ask me.\n\nI can't claim to understand the Ohn'iri. The sky's honest truth is that I don't really want to. They're good people, mostly, but they're strange. Unnerving. But also allies, and they asked me to give it to you. And to make more available if you want it. So I do." }
WordHunterWoW_QuestEN[72364] = { title = "Zarizz", description = "", objectives = "" }
WordHunterWoW_QuestEN[72365] = { title = "[test] Learn to spend talent points", description = "", objectives = "" }
WordHunterWoW_QuestEN[72372] = { title = "Taming the Dragon...kin", description = "", objectives = "The blood of the dragon has touched many creatures in this land. Though not all of them can be reasoned with, that does not preclude them from becoming stalwart companions.\n\nThere is a deep bond that one must build when befriending dragonkin. Of course it comes naturally to my kind, but I can give you a book that will teach you our methods.\n\nAfter that, it is up to you to achieve the bond needed to keep them by your side." }
WordHunterWoW_QuestEN[72373] = { title = "Aiding the Accord: The Hunt is On", description = "Our allies from the Ohn'ahran Plains have sent word-a request-for any and all who hunt these lands to lend their aid to their cause.\n\nWhilst continuing your efforts across these Isles, pay a visit to our allies at one of their hunting camps and assist in their efforts.\n\nThere is much to be done. Best not delay.", objectives = "Assist the Maruuk on a Hunt within the Dragon Isles. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", progress = "Has our renowned traveler returned with more news of success?", completion = "Oh my. You did all of that and return in one piece? Quite impressive.\n\nPlease accept this as a token of our appreciation." }
WordHunterWoW_QuestEN[72374] = { title = "Aiding the Accord: Dragonbane Keep", description = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future.\n\nNow then, to business.\n\nA lingering djaradin threat moves upon the Waking Shores deep within the smoldering inferno of Dragonbane Keep. We must move to disrupt their advances.\n\nWe await your return, {name}.", objectives = "Travel to The Waking Shores and lay siege to Dragonbane Keep. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", progress = "Do you bring news of your success?", completion = "My, my. What wondrous news! The Accord will be most pleased by your efforts. \n\nPlease accept this as a token of our gratitude." }
WordHunterWoW_QuestEN[72375] = { title = "Aiding the Accord: The Isles Call", description = "Your actions have not gone unnoticed.\n\nAcross the Isles, our allies seek to ensure the safety of all who venture throughout these lands. There are, however, some who would seek to end your... work, as it impedes in their plans.\n\nDo what you must to ensure our allies are protected.", objectives = "Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", progress = "Travels treating you well? Not too many enemies made along the way, I should hope.", completion = "Ah, you return! I should not act surprised, but alas, here we are.\n\nPlease accept this as a small token of our appreciation." }
WordHunterWoW_QuestEN[72380] = { title = "Together We Are Unstoppable", description = "{name}, you must tell Alexstrasza and Nozdormu what has happened.\n\nKhadgar and I will meet you at the Seat of the Aspects momentarily.", objectives = "Return to the Seat of the Aspects and inform Alexstrasza about what happened after the defeat of Raszageth in the Vault of the Incarnates.", progress = "What has happened, <name>?", completion = "We stand united against the Incarnates, <name>.\n\nTogether, we will protect this world." }
WordHunterWoW_QuestEN[72381] = { title = "Dragonscale Expedition", description = "Assist the Tortollan by completing 3 world quests.Upon completion of this quest you will gain:", objectives = "Complete 3 Tortollan world quests.Assist the Tortollan by completing 3 world quests.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[72382] = { title = "Iskaara Tuskarr", description = "Assist the Tortollan by completing 3 world quests.Upon completion of this quest you will gain:", objectives = "Complete 3 Tortollan world quests.Assist the Tortollan by completing 3 world quests.Upon completion of this quest you will gain:" }
