WordHunterWoW_QuestEN[72545] = { title = "Creche Fallen", description = "This is my failure, {name}. \n\nI led these dracthyr here. They knew death was a possibility, but they also trusted me to be there for them.\n\nI should have been down there, clearing the ruins, not up here trawling through books. \n\n<Emberthal balls her fists.>\n\nI need you to retrieve their horn signets. We need to give them honors.", objectives = "Collect the Horn Signet of Tetsos, Horn Signet of Arrosh, Horn Signet of Ekrati and Horn Signet of Hermin in the Lost Atheneum.", progress = "Hmm? Sorry. My thoughts are... elsewhere, right now.", completion = "<Emberthal gives you a solemn nod.>\n\nThank you, <name>." }
WordHunterWoW_QuestEN[72546] = { title = "Academic Assistance", description = "{name}! I've made a breakthrough with tha Winterpelt dialect. Ya helped get tha ball rollin' on this, so I felt like I ought ta keep ya apprised of the situation.\n\nMeet me in Theron's Watch and I'll tell ya all about it.", objectives = "Meet Sonova Snowden in Theron's Watch.\n\nProvided item:", completion = "Good to see ya again, <name>." }
WordHunterWoW_QuestEN[72547] = { title = "Academic Acquisitions", description = "I'll head up tae the village an' give 'em the bad news--or try. Winterpelt's a right tricky dialect tae learn.\n\nI need ye tae get out there an' find me some furbolg writin' samples tae study if we ever hope tae communicate properly.\n\nThe Primalists've wiped out or converted most o' the remainin' furbolg in the Span, so go shake 'em down until whate'er cultural artifacts they have drop out.\n\nI'll need at least five tae start, but bring me as many as ye can, and I'll keep teachin' ye what I learn.", objectives = "Recover furbolg artifacts from Primalists in the Azure Span.", progress = "What've ye got for me?", completion = "Not a bad start, <name>.\n\nI'm goin' tae need a lot more if we ever want to have a conversation, though!" }
