WordHunterWoW_QuestEN[72551] = { title = "A Living History", description = "The Winterpelt finally trust us enough to ask for aid.\n\nWe must nurture this trust so we may one day clasp their paws in friendship!\n\nThis Winterpelt, Jyrra of the, uh, Fuzzy Feet, says their elders went into hiding during the Primalist attack on their village. I don't yet understand their language, but it seems the elders left markers to help the clan find them later.\n\nIt's time to let the Winterpelt elders know it's safe to come home. Will you convey this message? It seems a simple enough task.", objectives = "Follow the markers to find the hidden Winterpelt elders.", completion = "Wait... is it true? You've come from our village? \n\nHas the fighting stopped?" }
WordHunterWoW_QuestEN[72552] = { title = "Gathering Together", description = "I haven't heard an outsider speak 303-our tongue. Your 303-grasp is a bit basic...\n\nBut only a friend of the clan would speak it at all!\n\n303-I am Elder Mhaz. If it is safe to return home, we should set off soon. But many of us are weak with sadness of the heart--and grumbling of the stomach. I would not put you at risk gathering fresh meat, but could you gather roots for us? \n\nWe have already gathered ones that are close. I hope this comfort food will lift our spirits enough to return!", objectives = "Gather 8 roots for Elder Mhaz.", progress = "The roots grow around the bases of the large trees. We have not ventured east because there are many worms. Perhaps there are more there?", completion = "I'm glad to see you have returned safely!" }
WordHunterWoW_QuestEN[72553] = { title = "More Effort, More Reward", description = "We're not sad. We're starving. 303-That's the truth of it. A few tasty roots won't 303-be enough.\n\nElder Mhaz doesn't recognize strength, but I do. It should be 303(100)-trivial for you to bring us some fresh meat! The 303-worms to the east should be easy prey.\n\nPlease, bring back 303-what you can carry!", objectives = "Collect 12 pieces of meat from worms.", progress = "Worm meat should be easy enough. Pick on the little worms if you're not up for the bigger ones.", completion = "I knew I was right about you, <class>." }
WordHunterWoW_QuestEN[72554] = { title = "Break Him", description = "You handled those little worms with such ease!\n\nHowever... Saza hasn't come back. The giant worm, Icebreaker, has been hunting us for 303-weeks. It took two of our elders while we gathered food 303-and injured me when I tried to avenge them. And now, with Saza missing, I fear the worst.\n\nFind Saza, and get rid of that worm!", objectives = "Find Saza and kill the large worm, Icebreaker.", completion = "So. It was Icebreaker?\n\n<Matron Fherg cries out in a mournful howl.>\n\nOur bright, brave cub... Oh, Saza...\n\nAnyone here would gladly give up their lives in trade for Saza's. Icebreaker's death brings some comfort, but it will not bring her back. \n\nSaza's loss will be felt by all of us." }
WordHunterWoW_QuestEN[72555] = { title = "Dragonflight (70) E", description = "", objectives = "Upon completion of this quest you will gain:" }
