WordHunterWoW_QuestEN[72558] = { title = "Our Honored Ancestors", description = "It is time to take the next step to understanding the Winterpelt. That step is a spiritual one. \n\nThey look to their ancestors for advice as they choose their path forward. We can learn from them too.\n\nBut the Winterpelt rite to call their ancestors is... intricate. And long. \n\nIt would be rude to copy their ritual anyway. We'll do it our way with Rustpine Spiritspeaker incense.\n\nCome! Let us reveal their ancestors' wisdom and learn more about our new friends!", objectives = "Use Radza's incense to allow spirit sight.", progress = "When you're ready, the incense will allow you to see spirits.", completion = "Can you see them?" }
WordHunterWoW_QuestEN[72559] = { title = "History Heist", description = "When the Primalists raided our village, they took more than our lives; they stole the heart 303-of our community--our priceless historical documents! \n\nI will not stand for records of our traditions, 303-rituals, and rich history taken from us! We still have lessons to learn from them.\n\nPlease, recover them from those looting Primalist scouts 303-so they can be preserved!", objectives = "Find the stolen Winterpelt \"documents.\"", progress = "Did the ancestor send you on a mission?", completion = "These pieces are incredible! What a horrible loss this would have been to the Winterpelt." }
