WordHunterWoW_QuestEN[72584] = { title = "Setting Your Very Own Net", description = "Want to try out your net? Go to the river mouth to the south of Waking Shores, and find a place where the fish are abundant. There should be a good spot for setting up a net.", objectives = "Set up a fishing net in the River Mouth Fishing Hole.", progress = "Don't forget, south of Waking Shores. Go.", completion = "Good. Don't forget to pick up your fishing net in a few hours. We don't want the fish to go to waste!" }
WordHunterWoW_QuestEN[72585] = { title = "Open Orientation", description = "You have done much for the Dragon Isles, hero. \n\nThere are many who are grateful for your contributions and want to welcome you more wholly into their communities. Go to them and orient yourselves with each group and their specialties. \n\nI think you will find that just as you have much to offer the Dragon Isles, many here have much they wish to offer you in return!", objectives = "Complete the Orientation quests in each major faction hub: Dragonscale Basecamp, Maruukai, Iskaara, and Valdrakken.", completion = "You've met everyone? Excellent. Maybe they will stop sending me emissaries, then. \n\nI hope you will continue to strengthen the bonds you have made with these communities. You have only to benefit each other." }
WordHunterWoW_QuestEN[72586] = { title = "Additional Academic Acquisitions", description = "Keep 'em comin'!\n\nThe more examples o' furbolg writin' ye collect for me tae cross reference, the better.", objectives = "Recover furbolg artifacts from Primalists in the Azure Span.", progress = "Don't stop now; we got ourselves a language tae learn!", completion = "I'll get right on catalogin' this batch." }
WordHunterWoW_QuestEN[72587] = { title = "Astonishing Academic Acquisitions", description = "Where did ya get that beauty?\n\nTha Primalists seem a lot more interested in destroying civilizations than preserving their history, which makes a find like this all tha more precious.\n\nI'll get out me good rubbing stick for this one!", objectives = "Recover an Intact Scribe Stick from Primalists in the Azure Span.", progress = "I cannae wait to get to work on this!", completion = "Nothing like a fresh artifact to start tha day off right." }
WordHunterWoW_QuestEN[72588] = { title = "Primalist Pillagers", description = "I'm startin' tae grasp the basics of Winterpelt, but what I'm pickin' up is grim.\n\nSeems a band of Winterpelt foragers fell afoul o' the nearby Primalists. The winters here are as harsh as any in Dun Morogh, an' the supplies they were gatherin' will be sorely missed.\n\nWhy don't ya see about recoverin' what ye can. With prejudice, if ye don't mind.", objectives = "Reclaim supplies from the Primalists.", progress = "There's a whole village dependin' on these supplies, so don't skimp on what ye bring back.", completion = "Maybe next time the thievin' Primalists will keep their mitts tae themselves." }
WordHunterWoW_QuestEN[72589] = { title = "Honor Their Sacrifice", description = "There's nothin' we can do for the foragers the Primalists killed, but we can at least try an' provide some closure tae their kin.\n\nSee if ye can find anythin' of a personal nature on the fallen. I'm sure the Winterpelt will appreciate whatever ye can bring them.", objectives = "Recover personal effects from the fallen Winterpelt Foragers.", progress = "How many did the Primalists kill?", completion = "It's not much, but it's somethin'. And that's what matters." }
WordHunterWoW_QuestEN[72590] = { title = "Ursol's Wisdom", description = "We have strayed from wise Ursol's path, trading focus for obsession and contemplation for fear.\n\nGather cones from the mighty Rustpines. As their roots stretch deep into the earth, take strength from the waters, reach into the winds, and are ripened by fire, they will be a symbol of our renewed commitment to true balance.\n\nTake to the skies on that drake of yours and you should be able to gather enough. The upper branches are the best place to find them.\n\nOffer them to Ursol at his nearby shrine.", objectives = "Gain Ursol's blessing.", progress = "Balance must be restored.", completion = "Our path forward is clear now. Thank you for your part in this." }
WordHunterWoW_QuestEN[72591] = { title = "A Debt That Must Be Paid", description = "{name}, I have heard you cultivated good relations with the centaur of the Ohn'ahran Plains. I would like to ask a favor.\n\nBaine left for the plains a few days ago in search of a group of missing tauren. I offered to accompany him, but he insisted on going alone.\n\nThe tauren of Thunder Bluff have a long and bloody history with the centaur of Kalimdor, as does Baine. While the Maruuk centaur are unrelated, I still have my concerns.\n\nYour presence could help smooth tensions. I hope.", objectives = "Find Baine in the Ohn'ahran Plains.", completion = "Ah, <name>. Mayla sent you? \n\nWhile I prefer to do this alone, I admit your relationship with the centaur might be useful." }
WordHunterWoW_QuestEN[72592] = { title = "Scars from the Past", description = "A tribe of tauren came to the Dragon Isles led by a close friend of mine, Bovan Windtotem. No one has heard from them since they entered these plains.\n\nIf they have gone missing, then I must find them. Unfortunately, I underestimated the size of this place. \n\nYou have an existing relationship with the centaur. Will you go speak with them and see if they have any information on Bovan or his tribe? \n\nPerhaps they can help narrow down my search.", objectives = "Ask the Maruuk centaur about the disappearance of Bovan Windtotem.", progress = "Thank you for your help. I would be... uncomfortable dealing with the centaur directly.", completion = "I sent you to get information, not to invite one of them to join us! Can you not just send her home?!" }
WordHunterWoW_QuestEN[72593] = { title = "A Tomul-tuous Beginning", description = "Since the dragons returned, we've seen an overwhelming number of outsiders passing through the plains. Normally we keep a close eye on our borders, but their sheer numbers, combined with the Nokhud threat, have made it difficult to track them.\n\nOne scout reported a group of outsiders that matched your description traveling along the eastern road. We should start our search there.\n\nAs for your friend, my khan gave me a command. A huffy companion won't stop me from carrying it out.", objectives = "Meet Tomul and Baine on the eastern road near the Watering Hole.", completion = "It seems the centaur here are not all that different from those in Kalimdor.\n\n<Baine eyes Tomul suspiciously.>" }
WordHunterWoW_QuestEN[72594] = { title = "Delivering Bad News", description = "As soon as we arrived, Baine was whisked away. Bovan is still missing, so he is speaking to someone named Tagar.\n\nOf course I've been left out here in the cold. It seems they still don't trust me.\n\nIn any case, you should go in and speak with the tauren. Take the items you found and try to identify who they belonged to. At the very least, you can let the families know what we've discovered so far.\n\nBut... be gentle, {name}. For some of them, this may be the worst day of their lives.", objectives = "Speak to the tauren and identify to whom the items you found belonged.", progress = "Tagar has known me since I was a child. He was my father's second-in-command for many years.\n\nLong ago, he was responsible for sending Rexxar, Rokhan, and Chen Stormstout on a mission to rescue me from the centaur.\n\nBut they needed aid to complete that mission... and that is when they met Bovan Windtotem.", completion = "Thank you for what you have done for these people.\n\nAs for Tomul, I hate to admit it, but she seems to be proving her worth.\n\nDespite her grating personality." }
WordHunterWoW_QuestEN[72595] = { title = "The Search for Bovan Windtotem", description = "According to this survivor, the centaur took them completely by surprise. Bovan led many of the braves against the centaur, hoping to buy time for the others to escape. \n\nHe succeeded, but Bovan and most of the braves have not returned. We must find him, {name}.\n\nI need you to search the surrounding area. If you find survivors, tell them to make their way back here.\n\nIf you find fallen tauren... take something recognizable to bring back to their families.", objectives = "Search the surrounding area for the missing tauren.", progress = "What have you found?", completion = "I have spoken to the survivors, and no one has seen Bovan since the battle. \n\nThis headdress you found on the deceased tauren does not belong to him, so he is either still missing... or captured.\n\n<Baine's expression hardens.>" }
WordHunterWoW_QuestEN[72597] = { title = "Ursoc's Strength", description = "It has been many years since we last offered sacrifices to mighty Ursoc, but we will need his blessing if we are to restore balance among our people.\n\nHis shrine is hidden in the mountains to the east where few would stumble upon it by chance.", objectives = "Gain Ursoc's blessing.", completion = "Thank you, outsider. Though the news you bring is grim, we will honor Ursoc's memory as best we are able." }
WordHunterWoW_QuestEN[72598] = { title = "Words of the Winterpelt", description = "The Winterpelt Chief sent word while ye were out that he wanted tae speak with ye again.\n\nAnd, thanks tae all the work ye been puttin' in, we could actually understand the message!\n\nWe're on the cusp o' somethin' great here, {name}. Think of it... The trade routes we could establish! The cultural exchange that could take place! The papers I could publish!\n\nWell? What are ye standin' around for? Go see what he wants!", objectives = "Speak with Kranac Sagesnow.", completion = "It seems... strange to speak of our traditions to an outsider. But if the ancestors spoke through you... \n\nI have task for you, <name>... one that I hope will set us on the right path." }
WordHunterWoW_QuestEN[72599] = { title = "Joint Rescue Operation", description = "Tomul says the attacks on the Windtotem were carried out by an enemy clan known as the Nokhud. \n\nJust down this road is their closest outpost, and the most likely location where tauren prisoners would be taken.\n\nThe task is simple--rescue the captives. We do not know how many there are, or how long they have been here, so we must hurry.\n\nI speak from experience when I say centaur do not keep their captives for long.", objectives = "Rescue 6 Windtotem Captives.", progress = "Did you find the captives?", completion = "We have scoured the camp and saved who we could, but Bovan is not among the captives." }
WordHunterWoW_QuestEN[72600] = { title = "A Proper Shikaar Send-Off", description = "We're here to rescue the captive tauren, but I have a personal request.\n\nThe place we are assaulting was once my home. The Nokhud took over after a surprise attack during the civil war.\n\nTake these Shikaar banners. When you kill a Nokhud or one of their allies, plant a banner on their corpse. I want to send a message--if they continue to occupy our home, they will pay in blood.", objectives = "Plant a Shikaar Banner on 15 slain Nokhud centaur or their allies.", progress = "How many banners did you place?", completion = "I saw the banners all across the highlands. It will not change what happened, but it puts a smile on my face." }
WordHunterWoW_QuestEN[72601] = { title = "Bovan's Last Hope", description = "If Bovan is not here, the Nokhud could have taken him anywhere. We might have one last chance to find him, but it's a long shot.\n\nWe still have Bovan's necklace. One of the Ohn'ir mystics might be able to use it to help divine his location. I've only heard about this ritual, so I have no idea if it will work.\n\nGo to the Ohn'iri Springs and look for Boku. I'm sure he will help us.\n\nBaine and I will make sure the tauren we rescued get back safely. We'll meet you at the Ohn'iri Springs.", objectives = "Find Boku at the Ohn'iri Springs.", completion = "Tomul has filled me in on what you need!" }
WordHunterWoW_QuestEN[72602] = { title = "Optimistic Mystic", description = "I'm sure I can find this Bovan Windtotem--but I will need a few items from you.\n\nFirst, I need a selection of flowers that grow at the base of the springs. They have the specific properties we are looking for.\n\nNext, I require the heart of a salamanther. A stronger heart will better our chances--look for the strongest you can find!\n\nI can gather the rest of the materials on my own.", objectives = "Collect a Strong Salamanther Heart and 8 Geyser Flowers.", progress = "Did you find everything?", completion = "Yes, this will do nicely! Since your friend does not wish to enter the springs, I've set up here." }
WordHunterWoW_QuestEN[72603] = { title = "What Words Are Worth", description = "Let me just grind these flowers and... there we are, all ready! \n\nTake these items and place them in the incense burner. Together with Bovan's necklace, I can entreat Ohn'ahra to help us find him. \n\nWith luck, she will give us a vision.", objectives = "Place the items in the incense burner and witness the vision.", progress = "Let us hope this works.", completion = "At least I have one reliable ally. Thank you, <name>." }
WordHunterWoW_QuestEN[72604] = { title = "Desperate Rescue", description = "I should have known I could not trust the centaur. They may provide token amounts of aid, but they would never risk themselves for us.\n\nLet us focus on the matter at hand. We cannot allow Bovan to remain in centaur captivity! I will set out immediately for Nokhudon Hold. \n\nMeet me there as quickly as you can.", objectives = "Meet Baine Bloodhoof outside Nokhudon Hold.", completion = "You have arrived. Good." }
WordHunterWoW_QuestEN[72605] = { title = "Saving Bovan Windtotem", description = "Time is against us, {name}. We must find Bovan as quickly as possible.\n\nThis hold is teeming with centaur. Our search will go faster if we split up--and it will be easier to slip by the patrols.\n\nTake one of these potions I brought. It should help you go undetected, but beware of the Nokhud wardogs. If Tomul spoke correctly, they will sniff you out.\n\nSearch the area for Bovan. If you find him, get him out. Do not wait for me.", objectives = "Search Nokhudon Hold for Bovan Windtotem.", progress = "I was too late...", completion = "I was too late..." }
WordHunterWoW_QuestEN[72606] = { title = "See Red", description = "Nokhud. Gelkis. Magram. Kolkar. They are all the same...\n\nThey plague the land. They murder my people. No more!\n\nI will end this centaur threat. Here! Now!", objectives = "Slay centaur within Nokhudon Hold.", progress = "I will make them pay for what they have done.", completion = "<After cutting through dozens of centaur, Baine is visibly fatigued. He is breathing hard and covered in wounds.>\n\nJamoku... was responsible for all of this...\n\nI will not... let him escape..." }
WordHunterWoW_QuestEN[72607] = { title = "Old Hatreds", description = "<Baine is still breathing heavily from his recent battles.>\n\nI will not leave... until Jamoku pays... for what he has done...\n\nI will avenge Bovan... no matter the cost...", objectives = "Slay Jamoku.", completion = "Jamoku is dead, as are many of the centaur. We have avenged Bovan and the others.\n\n<Baine grimaces as he touches a wound on his side.>\n\nIn hindsight, perhaps we should not have taken on the entire Nokhud army. Luckily, Tomul's timely arrival helped even the odds.\n\n<Baine glances at Tomul.>\n\nA centaur fighting to save a tauren... I never would have believed it." }
WordHunterWoW_QuestEN[72609] = { title = "Case Closed", description = "You are lucky we arrived when we did. We intercepted the Nokhud reinforcements about to flank you during your fight with Jamoku.\n\nWe lost two of our number in that battle. Their bodies have already been recovered. Bovan's is the last.\n\nThe Nokhud will not take long to rally and hunt us down. We must leave now.\n\nHead to Toghusuq Village, where the tauren are encamped. We will meet you there.", objectives = "Meet Scout Tomul and Baine Bloodhoof at Toghusuq Village.", completion = "Baine hasn't said much since we left Nokhudon Hold. I did not realize just how much this Bovan meant to him until now.\n\nAs for me, I will head back to Maruukai after this funeral. My khan's command has been fulfilled, even if this was not the outcome we would have liked." }
WordHunterWoW_QuestEN[72611] = { title = "Letting Go", description = "The Shikaar lost two of their own during the battle. All of Tomul's reinforcements... they volunteered to help, of their own will.\n\nI... have much to consider.\n\nAfter speaking with the Shikaar, we decided to honor our dead together. We have blended our funerary rites into one ceremony for this occasion.\n\nWe would be honored if you would stay and participate.", objectives = "Speak to Baine Bloodhoof about the funeral.", progress = "These centaur... may the Earth Mother embrace them.", completion = "Bovan is gone, but his people remain. Why did he bring them here? What did he see in his visions?\n\nThe Windtotem have always been nomads. Perhaps he saw that they might finally find a home.\n\nOr... did he know what would happen with the centaur? Did he bring us here to make peace with them? Or to make peace with the hatred in our own hearts?\n\nAll I know for certain is I must continue to live according to his ideals. In that, I can honor his life and memory." }
