WordHunterWoW_QuestEN[72640] = { title = "Dragon Isles Supplies", description = "", objectives = "Ah, our paths meet again, <name>. I am glad you have returned to us safely. Your deeds have made you honored among the Iskaara. Please, take these supplies as a token of our thanks!" }
WordHunterWoW_QuestEN[72641] = { title = "Dragon Isles Supplies", description = "", objectives = "Ah, our paths meet again, <name>. I am glad you have returned to us safely. Your deeds have made you honored among the Iskaara. Please, take these supplies as a token of our thanks!" }
