WordHunterWoW_QuestEN[72809] = { title = "Insert Coin", description = "", objectives = "The Warcraft Rumble game machine stands before you.\n\nDo you dare play?", progress = "The Warcraft Rumble game machine stands before you.\n\nDo you dare play?", completion = "You did great!" }
WordHunterWoW_QuestEN[72810] = { title = "A Shattered Path Through Time", description = "I've been reading some books about this cataclysm that happened to Azeroth.\n\nYou know what's tough? Seeing places you were used to get destroyed by a dragon.\n\nYou know what's even tougher? Fighting in those places and surviving!", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", progress = "Good thing the Dragon Isles didn't get hit by this cataclysm.", completion = "You're looking tougher already!\n\nLet's see how tough you are next time we talk. Remember, being tough is all about consistency!" }
