WordHunterWoW_QuestEN[73021] = { title = "A Lesson in Responsibility", description = "The daycare is always looking for new activities to enrich the education of the whelps.\n\nLasztak has suggested a class pet might help teach the whelps responsibility. Sir Pringly has been my personal companion for some time, and I believe his calm demeanor and sense of fun would serve the position well.\n\nSir Pringly will need his own habitat for the daycare, however. If you would gather materials, we can prepare a space just for him.", objectives = "Gather materials for Sir Pringly's habitat.", progress = "There is a particular way that Sir Pringly likes his habitat constructed. If you get the materials I listed, he should like it.", completion = "The habitat is looking wonderful, <name>. I hope Sir Pringly will be on his best behavior." }
