WordHunterWoW_QuestEN[73026] = { title = "Booty Bay", description = "Land of pirates, swindlers, and raiders! Zeros, once just a captive whelpling, has built a mighty reputation as an auction house trader in one of the most cutthroat places on Azeroth.\n\nHowever, his recent investment blunder made the front page of the Booty Bay Journal. Rescue him before his debt is collected by the Baron.", objectives = "Speak to Senegos for more information.", completion = "You think I know anything about Booty Bay? Why yes, I do..." }
