WordHunterWoW_QuestEN[73031] = { title = "Champion of the Winterpelt", description = "Thank you for all that you have done, {name}.\n\nIt is all too easy to turn within and simply continue on as you always have.\n\nThe Winterpelt will rejoin the world. We will return to the path our ancestors strayed from.\n\nAnd we will never forget your part in this.\n\nI have gathered the tribe and our new allies together to celebrate. Speak with me when you are ready to begin.", objectives = "Speak to Kranac to begin the celebration.", progress = "Shall we begin?", completion = "Thank you, friend." }
WordHunterWoW_QuestEN[73032] = { title = "Southern Reach Route - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[73033] = { title = "Caldera Coaster", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[73034] = { title = "Caldera Coaster - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[73035] = { title = "Path of Trust", description = "Radza sent me to find you and tell you to come to her. She set her incense burner out which means she's going to perform a ritual.\n\nThat means whatever she wants is important.\n\nRadza's just west of here. I wouldn't keep her waiting!", objectives = "Speak with Radza Thunderclaw in Winterpelt Hollow.", completion = "Thank you for coming to see me. The Winterpelt shaman have begun to trust us! We have much work to do..." }
WordHunterWoW_QuestEN[73036] = { title = "Medicinal Fungi", description = "When we happened upon these poor souls, it was clear they were attacked by djaradin. The poison on those brutes' weapons is preventing me and their leader, Narvra, from healing them.\n\nI noticed peculiar mushrooms on some crystals nearby. I have seen their like before, and I may be able to fashion an antidote from them.\n\nCan you harvest some while Voraxian and I keep watch here?", objectives = "Collect 10 Drooping Mushroom Cuttings from the Viridian Throne.", progress = "Do you have the cuttings? I'm not sure how long these poor people have.", completion = "Thank you. This looks like what we need. \n\nIt will take me a while to purge them, but we should be able to make it work." }
WordHunterWoW_QuestEN[73037] = { title = "Healing Crystals", description = "Greetings! \n\nApologies if I seem... distracted. I have been beside myself worrying about my injured friends. \n\nBut maybe you, gentle{class}, can assist us?\n\nNarvra needs aid in healing us. Shards from crystal elementals have healing properties. I feel terrible asking to harm a fellow elemental, but if you could... obtain some from them, that would greatly aid my friends.\n\nDon't worry--the elementals will regenerate in time. My friends' needs come first, however impolite our gathering methods may be.", objectives = "Collect 10 Viridian Heartcrystals from enemies in the Viridian Throne.", progress = "Have you retrieved the crystals? I'm worried about Butterfingers; he's not doing well.", completion = "<Narvra winces.>\n\nThank you. These crystals should allow us to heal everyone once again.\n\nMyself included." }
WordHunterWoW_QuestEN[73038] = { title = "A Room Without a View", description = "This vault is of Black Dragon make which means its contents are my flight's property.\n\nNormally I would have suggested we venture in together, but I was not expecting aggressive watchers. I will protect Rupert while you search for artifacts for us to examine.\n\nTo keep you safe, I will cast a spell on you I use when fighting the gronn.", objectives = "Recover artifacts from the Buried Vault.", progress = "Did you find anything of interest?", completion = "Ah, the downside of spending all my life in Outland. I have no idea what these artifacts are... \n\nYou say you found a journal? \n\nWe should bring these back to the Dragonscale team. They may know more.\n\n<Voraxian notices you looking at the dead watchers around him.>\n\nAh yes, we had a bit of excitement while you were in the vault. No matter, it has been handled." }
WordHunterWoW_QuestEN[73039] = { title = "Restless Death", description = "What could lead someone to do this... \n\nI can perform a ritual that might aid these poor creatures passing on. Take these totems and place them along the river. With enough anchor points, I should be able to help them move on.\n\nWe'll move ahead to look for a ritual site.", objectives = "Place anchor totems in the Acidbite Ravine to allow Narvra to start a cleansing ritual.", progress = "Have you placed the anchor totems?", completion = "Thank you, <name>. Give me a moment. We will begin the ritual shortly. \n\nLet us hope we can bring rest to these souls." }
WordHunterWoW_QuestEN[73040] = { title = "Bringing Disorder to Order", description = "How incredibly rude! I know we did not bring gifts, but this is hardly the way to greet visitors! There is no excuse for such terrible manners! Scoundrels! Cads! Brutes!\n\n<Rupert coughs into his hand.>\n\nWhat I meant to say was these watchers appear to be a threat. Anyone who tunnels in here could be in danger. \n\nWould you be able to make this place safer by eliminating them?", objectives = "Eliminate 6 Enraged Watchers in the Buried Vaults.", completion = "Good show, <name>. This place is much safer now. Those Ruffians will not bother anyone else." }
WordHunterWoW_QuestEN[73041] = { title = "Respite", description = "Thank you for everything you have done for us. \n\nWe've been able to get back on our feet now, and Butterfingers has cooked up a meal. \n\nWe lost a member of our team and everyone is still a bit shaken... We could do with the morale boost of a good meal.\n\nWould you like to join us?", objectives = "Join the Dragonscale team in the Zaralek Cavern for a meal.", progress = "Thank you, <name>. I think we needed that small break.", completion = "Returning these artifacts is the least we can do. And the opportunity to study additional artifacts is tantalizing!\n\nThank you for helping us, <name>. This opportunity for study will be huge for the Dragonscale Expedition." }
WordHunterWoW_QuestEN[73042] = { title = "A Tower Yonder", description = "{name}, I... don't want to ask more of you, but could you help us finally complete our mission?\n\nWe were ordered to investigate the Gaze of Neltharion. We were defeated on our first approach, but with an escort of two dragons and the mighty {name}, I'm not as worried about the djaradin.\n\nI want us to move out soon. Could you scout out the tower first for us?", objectives = "Investigate the Gaze of Neltharion in the Sulfur Wastes.", progress = "Did you scout out the tower?", completion = "You were attacked by what?! Are you okay? \n\nWhat did you find? Another book?\n\nTellywin, come and take a look at this!" }
WordHunterWoW_QuestEN[73043] = { title = "A Ghastly Legacy", description = "We need to give these creatures peace.\n\nWhile you are down there assisting Voraxian, please end their suffering. Even a temporary release from this existence will help relieve their burden. In the meantime, Narvra can work on her ritual.", objectives = "Eliminate 10 Ghostly Researchers and Failed Experiments in the Acidbite Ravine.", completion = "Thank you <name>.\n\nWhat was done here... I am worried about Voraxian.\n\nI am glad you went with him." }
WordHunterWoW_QuestEN[73044] = { title = "Cataloging Horror", description = "I... I need to bring the evidence of this insanity back to my flight. It may destroy us, but my people need to know what happened here. \n\nI borrowed some cataloging cameras from Tellywin. Can you join me in documenting these atrocities?\n\nI can provide you with a similar protection to that which I gave in the vault. I will leave any fighting to you; I cannot bring myself to cause any more suffering than my flight has already wrought. \n\nLet us be done with this as swiftly as possible.", objectives = "Use the Cataloging Camera to take pictures of experiment dumping sites in the Acidbite Ravine.", progress = "I can barely believe what was done here...", completion = "Thank you. To know that this was occurring before my flight's fall...  sickens me to my core. \n\nI will take these photographs to our leaders. If we cannot learn from our history, we are doomed to repeat it." }
WordHunterWoW_QuestEN[73045] = { title = "Stain Removal", description = "We can begin the ritual whenever you are ready.\n\nLet's help these spirits pass on.", objectives = "Complete the cleansing ritual.", progress = "We need to complete this ritual, <name>.", completion = "Thank you <name>.\n\nAs Sytorian passed, the ritual was unblocked and we were able to complete it. In time, the last remnants of his actions will fade.\n\nYou have helped so many today. I don't know if we can ever repay you. For now though. I think we should return to camp." }
WordHunterWoW_QuestEN[73046] = { title = "Cavernous Capers", description = "While we wait for Veritistrasz and Narvra to nurse the rest of the camp back to health, I thought we might take a short jaunt.\n\nI sensed a cavern on our way here, and... I feel like I may need a bit of spelunking to take my mind off what just happened...\n\nFancy joining me?", objectives = "Travel with Rupert from the Dragonscale Camp in the Zaralek Cavern.", progress = "Well! I say! Gosh!", completion = "How very rude! \n\nWhy, we turn up, we introduce ourselves politely, and we are attacked!\n\nRuffians!" }
WordHunterWoW_QuestEN[73047] = { title = "Terrestrial Tunneling", description = "I have to say that I am quite done with this place.\n\nWould you like to return to camp?", objectives = "Return to the Dragonscale Expedition camp in the Zaralek Cavern.", completion = "Oh, everyone appears to be back on their feet! Jolly good!\n\nAnd Butterfingers appears to have laid out quite the feast!" }
