WordHunterWoW_QuestEN[73069] = { title = "Sindragosa and Malygos's Rest", description = "The preparations are now complete. Kalecgos and Alexstrasza should be here soon with the remaining essences of Sindragosa and Malygos.\n\nBoth suffered such violent ends. I heard even with his last breath, Malygos cursed Alexstrasza.\n\nAnd Sindragosa--she was slain ten thousand years ago by Nelthar... by Deathwing. Yet she was reanimated by the Lich King and slain by adventurers. I can only imagine the state this essence is in...\n\nForgive my ramblings. Kalecgos and Alexstrasza should be here shortly.", objectives = "Observe Kalecgos and Alexstrasza putting Sindragosa and Malygos's remains to rest.", completion = "Thank you for aiding Senegos, <name>.\n\nIt's time to return to the archives." }
WordHunterWoW_QuestEN[73071] = { title = "A Brew for the Ages", description = "Legends speak of an ale brewed by Neltharion himself. Yet this ale has been lost to the ages! If those stories are true, and doubtless they are, we may find the recipe within this vault. \n\nIpfelkofer and I found three keys to this vault, so we decided to look around. Hopefully, our thirst for discovery will be quenched.\n\nIf we found that recipe, imagine the excitement in the brewing community! We could even feature that ale at the next Brewfest! First round will be on me.", objectives = "Find 15 Recipe Pages", progress = "Have you found that recipe? \n\nI bet you it's a porter... or maybe a stout... something dark and just a little bitter.", completion = "Our operation is a success! Now that we've got the recipe, we won't be needing these. So help yourself.\n\nSo what should we call this ale? Deathwing Dark? Black Flagon? Beyond the Dark Porter?\n\nAnyway, that was amazing. I need a drink." }
WordHunterWoW_QuestEN[73076] = { title = "Return to the Reach", description = "Long ago, the Reach was our training ground. Now it's time to return. The island may still hold secrets from our past.\n\nScalecommander Emberthal has gone on ahead. She awaits the arrival of any who would lend us their aid. We'll need all the help we can get finding a foothold in the Reach. Safe travels.", objectives = "Meet Emberthal in the Forbidden Reach.", completion = "You came from the mainland? Our call for aid has been answered, then.\n\nOur allies have come from every corner of the isles, but our base of operations is far from secure.\n\nCome, <class>. There is much to do." }
WordHunterWoW_QuestEN[73077] = { title = "This Might Sting", description = "Relax. This Sundered Flame is merely poisoned. He won't die. Probably.\n\n He will just be in pain.\n\n<Patroclosa looks at you, then sighs.>\n\nI suppose if you wanted to spare him this fate, you could collect bile from the Quartzite Sporebats that roam this valley. It contains a natural antivenom that would ease his suffering. But I will not waste my healing magic on a murderer.\n\nAnd you may as well bring back loamshrooms, to help him keep the bile down. Though it's a kindness he doesn't deserve.", objectives = "Collect 8 Spongy Loamshrooms and 6 helpings of Quartzite Spore Bile.", progress = "We all have to find our own path. I just wish ours was a little bit easier...", completion = "I hope that was the right thing for her. Don't judge Patri too harshly. She hasn't been the same since losing Ekrati.\n\n<Tezelari still manages to smile at you.>\n\nNothing to do but keep going, right?" }
WordHunterWoW_QuestEN[73078] = { title = "Dragonrider Racing - Stormsunder Crater Circuit", description = "", objectives = "" }
WordHunterWoW_QuestEN[73079] = { title = "Dragonrider Racing - Morqut Ascent", description = "", objectives = "" }
WordHunterWoW_QuestEN[73080] = { title = "Dragonrider Racing - Aerie Chasm Cruise", description = "", objectives = "" }
WordHunterWoW_QuestEN[73081] = { title = "Stress Fractures", description = "Another member of the Sundered Flame has been apprehended on Scalecommander Emberthal's behalf. A messenger, Amythora thinks.\n\nWe must decide what to do with him. In the meantime, it would be helpful if you could see if he has any important information.\n\nHe is well-guarded, so don't worry about him putting up a fight. Some passing Dracthyr offered their aid-- said they were companions of the Scalecommander! And they knew just how to handle Sundered Flame prisoners.", objectives = "Investigate the captured Sundered Flame messenger.", progress = "I know you want me to talk, but I can't.\n\nWhatever you do to me, Sarkareth's punishment would be a thousand times worse.", completion = "You... didn't have to do that.\n\n<The <race> fidgets with his bindings.>\n\nI'm grateful you did, though." }
WordHunterWoW_QuestEN[73082] = { title = "Dragonrider Racing - Southern Reach Route", description = "", objectives = "" }
WordHunterWoW_QuestEN[73083] = { title = "Dragonrider Racing - Caldera Coaster", description = "", objectives = "" }
WordHunterWoW_QuestEN[73084] = { title = "Dragonrider Racing - Forbidden Reach Rush", description = "", objectives = "" }
WordHunterWoW_QuestEN[73085] = { title = "Cold Feet", description = "If Marithos and Amythora want to run off and play adventurer, that's their choice. I have a sense of loyalty.\n\n<Despite his bold words, the messenger looks uncertain.>\n\nYou don't know what Sarkareth is capable of, all right?\n\nLook through my things and draw whatever conclusions you'd like. But I won't tell you anything. I can't.", objectives = "Examine the apprehended dracthyr's belongings for clues about the Sundered Flame.", progress = "Did you find anything? And why do you look like you've been in a scuffle?\n\n...Oh. I see. That's quite troubling.\n\n<Marithos sighs.>", completion = "Thank you for going above and beyond, <name>. I suspect this won't be the only fight to break out as we try to rebuild.\n\nI'll see what sense I can make out of the information you found.\n\nOh, and I'll make sure to return this horn signet to our captured friend. I'm not sure of his fate, but at least I can offer some peace of mind." }
WordHunterWoW_QuestEN[73086] = { title = "Healthy Competition", description = "More of my creche mates have been welcomed under Emberthal's leadership, but there are still tensions between the former Sundered Flame and the dracthyr we've hurt.\n\nFortunately, I think I've found a way to work out those tensions in a productive, dracthyrian method that will reinforce our bonds as evokers. Sparring!\n\nNow, come on. Try me! We can show all these louts how it's done.", objectives = "Beat Amythora at sparring.", completion = "Well done! That's a lesson they'll never forget. And I reckon there's some things I could learn from you, as well. Though don't let your head hit your wings about it." }
WordHunterWoW_QuestEN[73088] = { title = "Decipher the Runes", description = "Ancient ruins?! Here?!\n\nThis ancient tablet may tell us more about who lived here. Analyze them with these handy goggles and try to find their twins amongst the rubble.", objectives = "" }
WordHunterWoW_QuestEN[73089] = { title = "What's Behind The Next Door", description = "If we're going to keep exploring these vaults, we're going to need to open more doors! And that means we'll need more keys.\n\nSee if you can find more keys around Forbidden Reach. Every door is another opportunity!", objectives = "Enter the vault and open 3 more doors using Zskera Vault Keys.", progress = "Have you opened more doors?", completion = "Good work in there, my friend. We can continue our exploration as long as we have keys. \n\nI'm sure we'll find another vault to explore in a few days. My curiosity is killing me!" }
WordHunterWoW_QuestEN[73090] = { title = "Regrets in Crystal", description = "I have some idea of what Lanigosa might be doing in Crystalsong Forest, although I cannot imagine why she has taken it upon herself to do it.\n\nThat forest conceals within it the ruins of Shandaral, a former highborne settlement and the site of one of the mortal race's first clashes with the blue dragonflight. If Lanigosa truly is in Crystalsong, then it may well have something to do with Shandaral.\n\nSeek her out there, {name}, and try to convince her to return to us.", objectives = "Speak to Lanigosa in Crystalsong Forest.", completion = "Forgive me, <class>. I mistook you for a tormented arcane apparition.\n\n...do not give me that look! You would be surprised at how easy a mistake that is to make out here." }
WordHunterWoW_QuestEN[73091] = { title = "Crystalsong Forest", description = "The blue dragon Lanigosa lent her aid to mortals during the most recent war against the Burning Legion. However, she failed to respond to the call of the Isles.\n\nHas something befallen her? Or has she simply chosen not to return? Whatever her reasons, Azuregos's globe seems to suggest that she was last seen in Crystalsong Forest.", objectives = "Speak to Kalecgos.", completion = "Lanigosa has always been cordial with me. I hope she is all right." }
WordHunterWoW_QuestEN[73092] = { title = "Something Like Family", description = "Grab a bite! Scaralesh's Special! If you're a hungry dracthyr in need of cheer, this is the place!\n\n<Scaralesh lowers his voice to talk to you.>\n\nBetween you and me, {name}? Our people have been through a lot lately. We need something to help us relax, and remind us that we've always got each other. I think a family meal could be just that.\n\nRommen and I can handle the cooking. Will you bring plates to dracthyr who need a warm bite to eat?", objectives = "Bring plates of food to dracthyr at the party in Weyrnrest.", progress = "Ah, that smells incredible! We've really improved on creche food, don't you think?", completion = "Any other hungry bellies left to feed? No? Good.\n\n<Scaralesh lowers his voice to talk to you.>\n\nThanks for that, <name>. I see some of these <race> smiling for the first time in a long time tonight." }
WordHunterWoW_QuestEN[73093] = { title = "Empty Chairs", description = "I don't want to detract from the festivities, but there's someone missing who should be here.\n\nThis is a time for all dracthyr to come together, but Rathane might not see it that way-- he was Sundered Flame, just like us. And though he left them after what happened at the Aberrus, I fear he's still grappling with the guilt. He seemed rather distressed.\n\nWould you go find him? And make sure he's alright, and that he knows he's welcome?", objectives = "Find Rathane.", completion = "There is a lot of work to be done, a lot of things to be mended.\n\n<Rathane looks down at the broken horn signet in his hand.>\n\nBut we can help each other." }
WordHunterWoW_QuestEN[73094] = { title = "Aiding the Expedition", description = "Sarkareth must pay for his crimes.\n\n<Emberthal steels herself.>\n\nWe cannot let any more dracthyr suffer because of Sarkareth's twisted ambitions. \n\nIf the Sundered Flame is threatening the Dragonscale Expedition, then our allies need our help.", objectives = "Meet Scalecommander Emberthal and Ebyssian at Stormsunder Crater in the Forbidden Reach.", completion = "Too many have suffered. Too many have died.\n\nEnough is enough. Sarkareth is responsible, and he must pay." }
WordHunterWoW_QuestEN[73107] = { title = "Sending Stone: Initial Report", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Find a Sending Stone.", progress = "What have you found?", completion = "They... they knew. They knew we were not broken but still kept us in stasis.\n\nI will have this translated for all to read. May it provide insight." }
WordHunterWoW_QuestEN[73108] = { title = "Sending Stone: The Prisoner", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Find a Sending Stone.", progress = "What have you found?", completion = "So, Raszageth had a jailor. Or was Adamanthia our jailor? \n\nPuzzling. I shall have this translated and added to the volumes for others to read. My thanks, <name>." }
WordHunterWoW_QuestEN[73109] = { title = "Receiving Stone: Final Warning", description = "<This receiving stone still holds ancient words spoken by Neltharion in an old draconic dialect.>\n\n<The dracthyr scalecommanders would have a great interest in the contents of this document.>", objectives = "Bring the Receiving Stone to Scalecommander Azurathel.", progress = "What have you found?", completion = "What? What was Neltharion attempting to stop Adamanthia from doing?\n\nI will have this translated and added to the logs. It is good these messages come with a sense of time encoded in their magic. \n\nBut why were they not destroyed after use?" }
WordHunterWoW_QuestEN[73110] = { title = "Journal Entry: Experiments", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Collect a Journal Entry.", progress = "<name>, find any information of interest?", completion = "Ah! Excellent. More hints to our past.\n\n<Cindrethresh reads over the journal entry growing more and more enraged.>\n\nExperiments?! We were just... \"things\" to them?! They couldn't control us so we... aahhh!\n\nThank you for bringing this to me. We need to get this translated so others can read it." }
WordHunterWoW_QuestEN[73113] = { title = "Journal Entry: Relics", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Collect a Journal Entry.", progress = "<name>, find any information of interest?", completion = "Order. Always the enforcement of order.\n\nThank you, <name>. I will have this added to the translations." }
WordHunterWoW_QuestEN[73114] = { title = "Journal Entry: The Creches", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Collect a Journal Entry.", progress = "<name>, find any information of interest?", completion = "It is quite disturbing to read this, even knowing what happened and how it ended.\n\nI will have it translated for the others. Thank you, <name>." }
WordHunterWoW_QuestEN[73115] = { title = "Journal Entry: Silence", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Find a Journal Entry.", progress = "This may prove quite insightful.", completion = "A silence that lasted for how many thousands of years all because of one order.\n\nAnd to think I would have followed such an order without question until the day of my death.\n\nThank you for bringing this journal entry to me, <name>. I will add it to our translations." }
WordHunterWoW_QuestEN[73119] = { title = "A Wealth of Whelp Snacks", description = "Agapanthus says there are more snack orders ready to be retrieved, but we both have our hands full.\n\nWould you run out and collect snacks while we tend the whelps?", objectives = "Gather snack orders from vendors in Valdrakken.", progress = "Luckily we are not meant to eat the snacks ourselves, just understand what the whelps want so we can provide that. Cheese and crackers are clearly what they desire.", completion = "Thank you for bringing in more snacks. This will tide them over for now." }
WordHunterWoW_QuestEN[73120] = { title = "Appetizing Aftermath", description = "Today's activities were interrupted by a spontaneous food fight. This has attracted several undesirable visitors to the daycare!\n\nPlease help clean up.", objectives = "Help put the Little Scales Daycare back into order.", progress = "It is interesting, being a janitor, educator, and minder, but I suppose that is what all caretakers become.", completion = "I wish it were possible for all this to just stay clean for a few minutes!\n\nIn any case, thank you, <name>." }
WordHunterWoW_QuestEN[73124] = { title = "Hoard Behavior", description = "The whelps like to spend time with Sir Pringly, but their treading over the space has worn down his habitat.\n\nWould you retrieve another shrubbery for him? And while you are out, he could use an adorable new toy. And incense.\n\nWe cannot let his space fall into disrepair, of course.", objectives = "Gather materials for Sir Pringly's habitat.", progress = "Beyond the particular shade of green, Sir Pringly only cares that a natural material adorn his space.", completion = "The habitat is looking wonderful, <name>.\n\nThis should last Sir Pringly for a while until the whelps wear it out again." }
WordHunterWoW_QuestEN[73126] = { title = "Arts and Crafts and Baths", description = "Our arts and crafts activities today have gotten well out of hand. One of the whelps enchanted their brush and the rest followed suit. Now there is a coat of paint over everything.\n\nPlease clean up the daycare while we get the paint off the whelps.", objectives = "Help clean up paint around the Little Scales Daycare.", progress = "This paint was supposed to be washable, but it sticks to whelp scales like nothing else.", completion = "You came by just in time, <name>. Thank you. This was a three-person job.\n\nNow to reprimand Sir Pringly for indulging the whelps' poor behavior..." }
WordHunterWoW_QuestEN[73128] = { title = "Off the Page", description = "{name}, the whelps are begging us to tell them a story from their favorite anthology, but we are absolutely exhausted.\n\nThe book the whelps gravitate towards is enchanted and makes every retelling a workout.\n\nWould you mind taking over for a spell and tackle story time for us?", objectives = "Battle the villains of various stories for the whelps at the Little Scales Daycare.", progress = "I have heard these stories many times now. Battling them every day is tiring, to say the least.", completion = "Once the whelps learned we could conjure story elements to display them, they demanded all stories be told in that manner.\n\nThank you for giving us the chance to rest!" }
WordHunterWoW_QuestEN[73130] = { title = "Fowl Runic Scribblings", description = "Our magic rune lesson yesterday has apparently bled into today. The whelps are keen on practicing their runes anywhere they can, prudent or not.\n\nThis fascination has led to an interesting playtime period! Please, help us return the toys to their proper place and dispel any runes you come across.", objectives = "Help put the Little Scales Daycare back into order.", progress = "We really ought to teach them runes for something helpful, like stone polishing...\n\nThat would have gone a long way here.", completion = "Thank you for the assistance, <name>. That sandbox has a mind of its own! \n\nWe will do our best to keep the whelps from stirring it up again via runes." }
WordHunterWoW_QuestEN[73131] = { title = "Dignified Disguises", description = "{name}! I have crafted masterful disguises for me and my friends, but there is only one way to know if they are perfect.\n\nLet's play hide and seek! Find us in Valdrakken and I will know my disguises need work!", objectives = "Find Belastrasza and her friends in Valdrakken.", completion = "That was fun! And now I have new inspiration for the disguises. I am going to go work on them right away!\n\nYou can go now!" }
WordHunterWoW_QuestEN[73132] = { title = "Scanning the Stacks", description = "Hi, {name}! Do you want to play a game?\n\nI have been reading about the greatest hide and seek game in all of Azeroth!\n\nI think I can improve on the strategies this book suggests. Let us play a round and test my hypothesis!", objectives = "Find Zaleth and his friends in Valdrakken.", completion = "I need to refine my strategy. You are really good at finding!\n\nI love hide and seek! Let us play again sometime!" }
WordHunterWoW_QuestEN[73133] = { title = "Cozy Camouflage", description = "<Posidriss yawns.>\n\nI just can't sleep. Let's play a game instead!\n\nMaybe there's a comfy hiding spot out there somewhere. I bet you can't find me in the city!", objectives = "Find Posidriss and their friends in Valdrakken.", completion = "Thanks, <name>! That was really fun!\n\nI just wish I could get to sleep..." }
WordHunterWoW_QuestEN[73134] = { title = "Eternal Escapades", description = "Ah--ACHOO!\n\nSorry. Do you want to play hide and seek? I found new places to hide and I want to play!\n\nI hope my allergies don't stir up any trouble!", objectives = "Find every Zhusa in Valdrakken.", progress = "I don't remember you coming back so soon. You were fast this time!", completion = "Wow, the other Zhusas had really amazing hiding spots! I have a lot left to learn.\n\nThank you for spending time with me!" }
WordHunterWoW_QuestEN[73135] = { title = "Obsidian Obfuscation", description = "Hi, {name}.\n\n<Ruszi looks around nervously.>\n\nDo you want to play hide and seek with me? I think it would be very good training. \n\nI need to watch out for danger, so it is good to know where to hide. Will you help me practice?", objectives = "Find Ruszi and her friends in Valdrakken.", progress = "If I am hiding, then maybe they will not find me!", completion = "You found all of us! I think I am getting better at hiding. I cannot wait to play again!\n\n<Ruszi does a spin.>\n\nThis was super super fun!" }
WordHunterWoW_QuestEN[73137] = { title = "Chasing the Flame", description = "\"He awaits you in the darkness\"?\n\n<Emberthal's eyes narrow.>\n\nI know where Sarkareth is.\n\nI'll need your help holding him to account. If you want, you could stay here a while and pick through these ruins, but I think we have more pressing needs at hand. If you're willing to see this through to the end, then I need you to follow me.\n\nI'm going to Dragonskull Island.", objectives = "Meet Scalecommander Emberthal on Dragonskull Island.", completion = "I knew you'd come. \n\nThank you, <name>." }
WordHunterWoW_QuestEN[73139] = { title = "Deep Sea Supplies", description = "We are accustomed to threats emerging from the sea. But there are some enemies that should never be allowed on our shores.\n\nIn the east, naga are advancing on our beaches and coves. They've brought supplies with them. If we could reduce the local naga population and seize their supplies, our chances of survival here would increase.  \n\nHere's the plan: take those supplies from their caches or their corpses, and slay their leader. Lives are on the line.", objectives = "Slay Farscale Naga and gather their supplies.", progress = "Have you collected those supplies?", completion = "Thank you for facing waves and waves of naga. Their supplies will certainly help us support our settlement, so we can make a home here." }
WordHunterWoW_QuestEN[73140] = { title = "Sunder the Crater", description = "The Primalists have moved into Stormsunder Crater. They're raising elementals and exploiting the land.\n\nThey should be dealt with in a swift and decisive manner. Thin their ranks. Destroy their totems. Help us make the Forbidden Reach safe for the dracthyr, the tuskarr, and all the dispossessed who want to call it home again.", objectives = "Slay Primalists in Stormsunder Crater.", progress = "Have you taken care of the Primalists in Stormsunder Crater?", completion = "Well done. You just did some serious damage to their plans here in the Forbidden Reach." }
WordHunterWoW_QuestEN[73141] = { title = "Everburning Embers", description = "Warmth and heat are constant concerns for us at the homestead. We don't want to burn through everything we brought, and we don't like collecting driftwood on hostile shores. Too risky!\n\nThe Primalists, though, carry some of their own fire with them.\n\nIf you could slay some powerful fire Primalists, take their Everburning Embers, and bring those embers back here, we could make good use of them.", objectives = "Collect Everburning Embers from powerful fire Primalists in the Siege Creche.", progress = "Everburning Embers could certainly help keep the camp warm all year round.", completion = "These are perfect! They will help keep us warm on the coldest nights. Even when the weather is terrible, they will help keep the cooking fires lit.\n\nThank you! May you always have a warm welcome here." }
WordHunterWoW_QuestEN[73142] = { title = "Busting Blues", description = "Malygos left behind forces to monitor us while we slept. He's gone, but his minions are still here, making life difficult for everyone.\n\nScouts have seen them using Arcane Foci. I think we could make better use of them. Go collect some. Their security forces might put up a fight, but that won't be a problem for you, will it?\n\n<Cindrethresh snorts.>\n\nMaybe they'll take the hint and leave.", objectives = "Collect Arcane Foci from Blue Security forces in the Old Weyrn grounds.", progress = "Have you collected those foci?", completion = "That's a relief. Thank you. Now we can all sleep a little better at night." }
WordHunterWoW_QuestEN[73146] = { title = "Cutting Wind", description = "", objectives = "Defeat Vortex in a Pet Battle." }
WordHunterWoW_QuestEN[73147] = { title = "Shifting Ground", description = "", objectives = "Defeat Tremblor in a Pet Battle." }
WordHunterWoW_QuestEN[73148] = { title = "Combustible Vegetation", description = "", objectives = "Defeat Wildfire in a Pet Battle." }
WordHunterWoW_QuestEN[73149] = { title = "Flood Warning", description = "", objectives = "Defeat Flow in a Pet Battle." }
WordHunterWoW_QuestEN[73151] = { title = "Hats Off", description = "", objectives = "" }
WordHunterWoW_QuestEN[73155] = { title = "The Forgotten Ring", description = "<The ring bears unusual markings. It might be of interest to one of the dracthyr at Morqut Village.>", objectives = "Deliver the ring to Researcher Imareth at Morqut Village.", completion = "Oh! I have not seen a relic like this since before our awakening! It is a special ring, clearly crafted by Neltharion's smiths.\n\nYou should keep it. Keep it close. It might be of use to you." }
WordHunterWoW_QuestEN[73156] = { title = "Return to Viridia", description = "I should entrust you to Viridia. She's working with the Healing Wings in Morqut Village to build a safe place for the dracthyr, the tuskarr, and our other allies in the Reach.\n\nWe have a home here... and I... I have some thinking to do. I'm grateful that you walked beside me through this trial.\n\nThis isn't over. But at least I know that the next time we face Sarkareth, we can count on you. Thank you.", objectives = "Meet with Viridia in Morqut Village at the Forbidden Reach.", completion = "Welcome back, <name>. I can tell from the look on your face that wasn't easy.\n\nI'm not looking forward to dealing with Sarkareth again, but we'll be ready next time. For now, we have more pressing matters at hand. We won't be done until we've made the Reach safe for everyone." }
WordHunterWoW_QuestEN[73157] = { title = "Wings of Mercy", description = "With the lifting of the storms, we dispatched scout teams to explore the island. \n\nSeveral of our teams have not returned. We fear they may have fallen to unknown dangers.\n\nCan you search the island for them? Once you locate them, use the Mender's Signal to summon a medic.", objectives = "Aid Dracthyr Scouts at three locations on the Forbidden Reach.", progress = "Have you found the scouts?", completion = "I am grateful for the help you have given our scouts." }
WordHunterWoW_QuestEN[73159] = { title = "Exploring Our Past", description = "With your help, we can now delve deeper into the secrets of this land.\n\nNearby lay the Zskera Vaults. Within these large underground chambers, Neltharion stored various treasures and forgotten research. Exploring these vaults would be most beneficial.\n\nPlease travel with Tacha and Jeb and assist them as needed.", objectives = "Meet Jeb and Tacha at the entrance to the Zskera Vaults.", completion = "Behind these massive doors lies a multitude of chambers to explore. Are you ready, <name>?" }
WordHunterWoW_QuestEN[73160] = { title = "Helping Hand and Claw", description = "Members of the Dragonscale Expedition traveled here to help explore ruins on this island. Their efforts may help us uncover more details about our past.\n\nMy scouts have spotted three of them shipwrecked on Sharpscale Coast. See if you can help them reach the village safely.", objectives = "Aid Jeb, Tacha, and Wulferd at the Sharpscale Coast.", progress = "Is it safe to travel to Morqut Village?", completion = "With your help, Jeb and I are safe. And our supplies are safe, too!\n\nA tuskarr fisherman has agreed to give us a lift to Morqut Village. We hope to see you there soon." }
WordHunterWoW_QuestEN[73169] = { title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in a celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in Stormwind at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", objectives = "Talk to the Lunar Festival Harbinger in Stormwind City.", completion = "Welcome, <name>. You're here to join us in our celebration?" }
WordHunterWoW_QuestEN[73170] = { title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in a celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in Orgrimmar at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", objectives = "Talk to the Lunar Festival Harbinger in the Valley of Wisdom in Orgrimmar.", completion = "Welcome, <name>. Are you here to join in the festivities?" }
WordHunterWoW_QuestEN[73171] = { title = "Gain New Look: Maiev", description = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", objectives = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", progress = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", completion = "Congratulations! Your Maiev miniature now has an extra look!" }
WordHunterWoW_QuestEN[73172] = { title = "Shikaar Elder", description = "", objectives = "Your spirit burns with life, young <class>.  I accept the homage you pay, and offer in return this token..." }
WordHunterWoW_QuestEN[73173] = { title = "Gain Even Newer Look: Maiev", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", progress = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", completion = "Congratulations! Your Maiev miniature now has an extra look. It's the best!" }
WordHunterWoW_QuestEN[73174] = { title = "Gain New Look: Sneed", description = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", objectives = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", progress = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", completion = "Congratulations! Your Sneed miniature now has an extra look!" }
WordHunterWoW_QuestEN[73175] = { title = "Gain Even Newer Look: Sneed", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", progress = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", completion = "Congratulations! Your Sneed miniature now has an extra look. It's the best!" }
WordHunterWoW_QuestEN[73178] = { title = "Hands Off Our Booty!", description = "The Irontide Pirates have been stealing from dracthyr and tuskarr. They're taking anything and everything. It's all just booty to them!\n\nYou should recover our stolen goods. Make them regret coming here.", objectives = "Defeat Irontide Pirates and recover Stolen Goods.", progress = "Did you teach those pirates a lesson?", completion = "That'll teach them!" }
WordHunterWoW_QuestEN[73179] = { title = "Soupocalypse Now!", description = "The Irontide pirates think they can sail in and take over the islands. They clearly have no idea who they are dealing with. Our Morqut friends will provide you with the transportation. We dracthyr will provide the... munitions.\n\n<Cindrethresh smirks.>\n\nFusethrian has been trying to learn to cook the tuskarr way with mixed results. Ask him for his more volatile attempts. We can get some safe disposal and run off these pirates in one go!", objectives = "Defeat Irontide Pirates to drive off the invasion.", progress = "Did you teach those pirates not to sail into our waters?", completion = "Heh. I love the smell of soup-based munitions in the morning. Smells like victory." }
WordHunterWoW_QuestEN[73181] = { title = "Zeroing Debt", description = "I do hope that is the last we see of the Baron. Truth be told, I respect his seat of power in Stranglethorn.\n\nWe were lucky to find Zeros still alive. He must have developed quite the positive relationship with the Baron before all this nonsense, or else he would not have been given so much time.\n\nLet us return to the Archives.", objectives = "Return to the Azure Archives.", completion = "I am rather spent from this mission, <name>. Let me rest for awhile." }
WordHunterWoW_QuestEN[73183] = { title = "Wanna Play a Game?", description = "<You open a scribbled note.>\n\nHeya pal! The name's Mizzen, and I hear you're pretty good at findin' stuff.\n\nSee, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins.\n\nHow about we meet up and I'll tell you where to find some?", objectives = "Speak with Mizzen in Valdrakken.", completion = "Hey there, glad you could make it!\n\nYou gotta check out this machine!" }
WordHunterWoW_QuestEN[73188] = { title = "The Sullied Banner", description = "So long as there has been magic, there have been those willing to utilize it for nefarious ends.\n\nI am not certain what grievances these rogue mages hold that has prompted Surigosa to chase them down, but I am inclined to trust her judgment on the matter. Let us go to her, {name}; perhaps we can solve this rogue mage problem and convince Surigosa to return in a single turn.", objectives = "Find Surigosa in Theramore.", completion = "Greetings, mortal. You and your hangers-on have arrived just in time to see me obliterate this pack of miscreant magi." }
WordHunterWoW_QuestEN[73189] = { title = "Creche Cache", description = "I'm glad you're here. Beetles infected our support creche, so we evacuated in a hurry. That meant leaving a lot of supplies behind.\n\nNow we've got a lot of injured explorers, and we could sure use those supplies. Can you help us?\n\nWe need you to retrieve as many as you can. Just don't let the toxins get to you.", objectives = "Collect 6 Mender Supplies in the Support Creche.", progress = "Hey, have you retrieved those supplies?", completion = "Thank the Aspects! These supplies will go a long way to getting us back on our feet. Thank you." }
WordHunterWoW_QuestEN[73190] = { title = "Toxic Infestation", description = "The Healing Wings need access to our support creche, but it's still overflowing with an infestation of toxic beetles.\n\nI'm sure Viridia would appreciate it if we helped exterminate those pests.", objectives = "Kill beetles in the Caldera of the Menders.", completion = "We're clearing out that infestation, day by day. Every bit helps. Only a matter of time until those beetles are gone forever!" }
WordHunterWoW_QuestEN[73191] = { title = "Snake Wrangling", description = "The same toxins that plague our Support Creche are seeping into migrating watersnakes.\n\nWe need to relocate the snakes back to their original pools. If we don't, that invasive species is going to wreak havoc on the environment.\n\nI can loan you a friendly water elemental to help you transport the snakes. It's for our own safety as much as theirs.", objectives = "Relocate 6 Toxic Watersnakes to the pools in the Caldera of the Menders.", completion = "This is great! We're really making progress revitalizing the Caldera of the Menders." }
WordHunterWoW_QuestEN[73192] = { title = "Feathered Fiend", description = "The trinket appears to be some sort of Noblegarden decoration. It should probably be returned to the festivities in Goldshire.", objectives = "Bring the Noblegarden Trinket to Zinnia Brooks at Goldshire.", completion = "Ah, thank you for returning this. I'll see to it that any stolen decorations are restored!" }
WordHunterWoW_QuestEN[73194] = { title = "Up Close and Personal", description = "The great proto-dragons are some of the fiercest creatures to roam the Forbidden Reach.\n\nTaking them down isn't easy, but we have many weapons in our arsenal.\n\nTake this spear and harpoon. You'll need them. If you get caught in a proto-drake's maw, you'll need to fight tooth and claw with everything you've got to survive.\n\nIt isn't easy, but I know you can do this.", objectives = "Slay a proto-dragon using the Proto-Killing Spear.", completion = "That's the way to do it! Nothing like being caught in the jaws of death to make you feel alive." }
WordHunterWoW_QuestEN[73196] = { title = "Tarecgosa's Rest", description = "{name}, hold a moment.\n\nBefore you leave... I have one more thing that needs to be done. There is one last member of my kin that deserves rest.", objectives = "Speak with Kalecgos about Tarecgosa.", progress = "Grief is a burden shared...", completion = "This feels as if I am saying goodbye to a piece of myself, but it must be done." }
WordHunterWoW_QuestEN[73197] = { title = "Love Unending", description = "Alongside a proper conduit to house Tarecgosa's soul during the ritual, we need enough magical essence to ground the flower. The bronze dragonflight was involved in creating the staff you hold, so I believe it best we use their magic again.\n\nSome of the sand within the Temporal Conflux should suit this purpose perfectly. Just make sure it's of the more magical variety.", objectives = "Gather Ephemeral Sand from the Temporal Conflux.", progress = "How goes the hunt for the sand?", completion = "Time is a fickle thing even when it flows properly. I do not understand how my kin can master it." }
WordHunterWoW_QuestEN[73198] = { title = "Forget Her Not", description = "The staff was made with the bough of a world tree, so the receptacle that the soul is transferred to needs to be comparable. Within the adverse conditions of Vakthros there may be a flower that is tenacious enough to grow.\n\nHowever, it will be fragile given the circumstances. Find it, and then bring it to one of the green dragonflight's groves to help strengthen it.", objectives = "Collect a Manaheart flower and bring it to the Ancient Bough to bloom.", progress = "Did you find it? It grows very rarely.", completion = "The flower only grows in specific conditions and due to that it contains quite a bit of magical energy. This should be a perfect conduit for Tarecgosa." }
WordHunterWoW_QuestEN[73199] = { title = "Rhapsody in Blue", description = "It is time. I cannot delay this any longer.\n\nLet us say our farewells.", objectives = "Assist Kalecgos in sending off Tarecgosa.", completion = "<Kalecgos holds silent for a moment.>\n\nThank you, friend." }
WordHunterWoW_QuestEN[73221] = { title = "A Clear State of Mind", description = "", objectives = "" }
WordHunterWoW_QuestEN[73226] = { title = "Dragonskull Shoal", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", objectives = "Collect fish to restock the fishing hole and mount your drake to drop them from above.", progress = "Have you dropped those fish yet?", completion = "Ha! The legends are true, how fantastic!" }
WordHunterWoW_QuestEN[73227] = { title = "Jade Forest", description = "Daughter of Malygos and Saragosa, Kirygosa survived the turbulent Nexus War that ripped away her life and family.\n\nAfterwards, Kirygosa sought a permanent summer in Stranglethorn. Finding warmth but not quite peace, she moved on to Dawn's Blossom, a small village nestled in the Jade Forest.\n\nThe blue dragonflight would welcome her return.", objectives = "Speak to Kalecgos for more information.", completion = "...Kiry. Yes, I know where she is." }
WordHunterWoW_QuestEN[73371] = { title = "Gain New Look: Night Elf Huntress", description = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", objectives = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", progress = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", completion = "Congratulations! Your Night Elf Huntress miniature now has an extra look!" }
WordHunterWoW_QuestEN[73372] = { title = "Gain Even Newer Look: Night Elf Huntress", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", progress = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", completion = "Congratulations! Your Night Elf Huntress miniature now has an extra look. It's the best!" }
