WordHunterWoW_QuestEN[73392] = { title = "Gain Even Newer Look: Murloc", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", progress = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", completion = "Congratulations! Your Murloc miniature now has an extra look. It's the best!" }
WordHunterWoW_QuestEN[73393] = { title = "Gain Even Newer Look: Whelp Egg", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", progress = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", completion = "Congratulations! Your Whelp Egg miniature now has an extra look. It's the best!" }
WordHunterWoW_QuestEN[73398] = { title = "Too Far Forward", description = "Our forward forces pressed too aggressively into a Sundered Flame stronghold. Now they need help. We really need to send you in to extract them.\n\nHelp them get out of there. You can use your own magic or these healing draughts from Viridia. And while you're there? Put some hurt on the Sundered Flame. They certainly deserve it.", objectives = "Slay Sundered Flame and heal injured Dark Talons and Obsidian Warders.", completion = "It's good to see our forces returned safely, even if their pride is a little wounded. We need every soldier we have for what's to come." }
WordHunterWoW_QuestEN[73399] = { title = "The Search for Blue Dragons", description = "Thank you for your help so far, {name}. We've still got more blue dragons to track down.\n\nI'll give you the honors of choosing where to go next.", objectives = "Choose an area to investigate the missing blue dragons." }
WordHunterWoW_QuestEN[73404] = { title = "Lost Blue Dragons", description = "The Azure Archives are starting to feel much more lively, thanks to your help.\n\nChoose which location you'd like to investigate next.", objectives = "Choose an area to investigate the missing blue dragons." }
WordHunterWoW_QuestEN[73405] = { title = "A Pair of Blue Dragons", description = "I appreciate your aid so far, {name}. \n\nWhere would you like to look next?", objectives = "Choose an area to investigate the missing blue dragons." }
WordHunterWoW_QuestEN[73406] = { title = "The Last Missing Blue Dragon", description = "We've only one more blue dragon to locate now, {name}.\n\nLet's finish this, shall we?", objectives = "Choose an area to investigate the missing blue dragons." }
WordHunterWoW_QuestEN[73408] = { title = "Sniffen 'em Out!", description = "", objectives = "" }
WordHunterWoW_QuestEN[73550] = { title = "Honeyfreeze Mead", description = "Right, so now that we've established somewhat friendlier relations and learned a wee bit of Winterpelt, it's about time tae make friends in the proper dwarf manner.\n\nWhat gesture of friendship is better than a stiff drink tae ward off tae cold? Both dwarves and furbolgs have a long history of brewin', so we can call it somethin' of a cultural exchange too!\n\nI saw some hearty lookin' bees a bit south of here. And where there's bees, there's honey. And where there's honey, there could be mead.", objectives = "Collect 8 Honeyfreeze Honey for Sonova Snowden.", progress = "I can almost taste it already.", completion = "This'll do nicely." }
WordHunterWoW_QuestEN[73692] = { title = "Hive Maintenance", description = "It wouldn't do tae steal a hive's honey without ensurin' they have enough food tae make it through the cold. Especially if we might want more down the line.\n\nFrostbell pollen's sticky stuff an' a wee bit fragile. But if ye run through some of the bloomin' plants, it'll be on ye like fleas on a kobold.\n\nThen, all ye have to do is bring it back tae a bee afore it blows away--they'll lick it right off ye! Tickles a bit too!", objectives = "Bring pollen to the Honeyfreeze bees.", progress = "It's a rough life out there for a wee bee.", completion = "That ought tae keep 'em goin' for a while." }
WordHunterWoW_QuestEN[73694] = { title = "Stuck in Stasis", description = "When the first dracthyr awakened from millennia of slumber, we left the Forbidden Reach for the Dragon Isles. Yet not all of the dracthyr are free. Some are still in stasis, hidden deep within their creches.\n\nWe need your help. Travel to Froststone Vault. See if you can find more of our friends. One of my Healing Wings would be glad to accompany you. Choose someone who best suits your need.\n\nIt is time for all dracthyr to rejoin the world as we have.", objectives = "Free dracthyr trapped in stasis within Froststone Vault.", completion = "It warms my heart to see so many new arrivals. We will do our best to orient them on all the changes in the world since they were last awake.\n\nThank you, friend." }
WordHunterWoW_QuestEN[73698] = { title = "Rolie Polie Molie", description = "", objectives = "" }
WordHunterWoW_QuestEN[73703] = { title = "A Summon to Orgrimmar", description = "{name}, Eitrigg has requested your presence in Grommash Hold. \n\nHe seemed like he had much to tell you.", objectives = "Speak to Eitrigg in Grommash Hold, Orgrimmar.", completion = "Ah, <name>. Thank you for coming. We have much to talk about." }
WordHunterWoW_QuestEN[73704] = { title = "Local Flavors", description = "Now that we have the base o' the brew figured out, we need tae add the spice.\n\nPut that rudimentary Winterpelt I taught ye tae use and ask around for local ingredients tae blend into the flavor profile. Try talkin' with Kazzi. From what I gather she's somethin' of a trader. \n\nThe finished brew will be a mix of dwarven and Winterpelt traditions which seems appropriate for the circumstances.\n\nAn' if we're lucky, it won't taste half bad!", objectives = "Ask Kazzi for ingredients to flavor the brew.", progress = "Get out there an' ask. She won't bite.\n\nUnless ya inadvertently ask her tae, I suppose.", completion = "Right, let's see what we can do with these." }
WordHunterWoW_QuestEN[73707] = { title = "TICKET: Glimmerogg Games", description = "<Written in sloppy handwriting that makes it almost impossible to read.>\n\nCONGRATULATIONS, LOAMM VISITOR! YOU'VE FOUND A TICKET TO THE BEST COMPETITION IN ZARALEK CAVERN: THE GLIMMEROGG GAMES!\n\nYou'll find the games in the south of Zaralek Cavern. Just look for a bunch of happy drogbar! Don't miss our fun activities like...\n\n<The rest of the page is illegible except for the name \"Brogg.\">", objectives = "Pay a visit to Glimmerogg in the south of Zaralek Cavern.", completion = "Lucky you! You found a ticket to the Glimmerogg Games!\n\nNow, that isn't all you need to get in, brul." }
WordHunterWoW_QuestEN[73708] = { title = "Pay to Play", description = "It doesn't matter if you were invited or if you just showed up. Drogbar, niffen, or {race}, everyone pays for the Glimmerogg Games! \n\nEven I did, and I'm runnin' this show!\n\n<Brogg points aggressively to a ticket of his own.>\n\nI know you can't pay in drogdollars, but you can pay in snacks for everyone. And we love mushrooms and fish! Bring Brogg some food, and we're square, okay?", objectives = "Collect 4 Glimmer Mushrooms and 4 Echoed Lurker Flesh near Glimmerogg.", progress = "Have the fee in full? And no, can't pay later. Brogg had enough from deadbeats.", completion = "Good work, uplander. Now Brogg has snacks for the week!\n\n...I mean, we have snacks for everyone!\n\nNow, get out of here. And have some fun, brul!" }
WordHunterWoW_QuestEN[73709] = { title = "Favor on the Side", description = "Brogg counts more people than fees today. It's not sitting well with me neither. I'm gonna blow my top!\n\nSure, Glimmerogg is popular, but it's not all fun and games. We have rules and everyone must follow them.\n\nYou look like someone who can read fine print and follow rules. If you get rid of the intruders that are cheating Brogg, I may have something for you.", objectives = "Uncover 6 intruders and kick them off the Glimmerogg Games.", completion = "Brogg thanks your good eye and discipline, little brul. \n\nRemember to play by the rules... If a rock lifts by itself, somebody is cheating." }
WordHunterWoW_QuestEN[73710] = { title = "Rock By Rock", description = "Ah, a challenger! So, you think you can defeat Storul Heavystone in his famous rock-lifting marathon challenge? \n\nHA! Silly uplander. No one can compare to Storul! No one has EVER matched my strength.\n\nBut maybe you try. Defeat will teach you a valuable lesson: true strength comes from struggle!\n\nOr, Storul will have a new friend to spot him at the gym! Get it, brul!", objectives = "Complete Storul Heavystone's weight lifting spree.", progress = "What? You're not afraid to lose, are you? Don't let fear consume you before you start.\n\nJust do it, brul. Storul will give you a fair trial.", completion = "Good, brul, good! You a weakling no more! \n\nBut even though you've proved you can lift as much as me, you're still not as great as Storul. \n\nNot yet.\n\nThere are more rocks ahead for a great challenger like you." }
WordHunterWoW_QuestEN[73711] = { title = "Marked Champion", description = "You did good on Storul's challenge, but that does not make you a champion like him.\n\nTo get on my level, you have to lift the greatest rock--not a real rock, a spirit one.\n\nYou must face what every drogbar fears... and venerates! You must be blessed by the Carcaxas, The Great Daughter-Worm.\n\nBut Carcaxas only bestow her mark on those who are DETERMINED and don't FEAR SMELLING BAD!\n\nAre you ready to take on this challenge? CAN YOU DO IT, BRUL!?", objectives = "Receive Carcaxas's mark.", progress = "Did you get your blessing from The Great Daughter-Worm? No? \n\nYou're not visualizing hard enough. See yourself beating Carcaxas. Now go!", completion = "<race>! I can smell Carcaxas's mark upon you.\n\nThe Great Daughter-Worm made you a champion like me! Strorul can tell you are stronger. You SMELL stronger!\n\nNow you can lift every rock in your path. Remember to stay focused. Greatness requires constant physical and mental strength. One day you'll be as great as Storul. That is the Glimmerogg way!\n\nAnd don't forget--we spotting partners now. See you in the gym next weekend." }
WordHunterWoW_QuestEN[73715] = { title = "Driftwood Derby", description = "One of the challenges of any new village is finding enough raw building materials. Fortunately, the ocean often brings us exactly what we need.\n\nTake my boat and sail around the island. Along the way, you can collect driftwood in nets. But be wary. You may attract some unwanted attention!", objectives = "Collect driftwood in Tukkaraq's boat.", progress = "How goes the hunt for driftwood?", completion = "Excellent work! This will help us build new homes, tools, and everything we need for a life here.\n\nWe'll put it all to good use." }
WordHunterWoW_QuestEN[73716] = { title = "Aylaag Elder", description = "", objectives = "Your spirit burns with life, young <class>.  I accept the homage you pay, and offer in return this token..." }
