WordHunterWoW_QuestEN[73864] = { title = "Tracking Quest", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[74117] = { title = "Rare Prey", description = "Rare and dangerous creatures lurk around the creches of the Forbidden Reach. If you and your allies want to stay safe, you should hunt down these threats.", objectives = "Hunt down the special threats across the Forbidden Reach.", progress = "Are there still dangers roaming the land?", completion = "I'm glad you dealt with those threats. I'm sure they got what they deserved." }
WordHunterWoW_QuestEN[74118] = { title = "Spelunking the Den", description = "Did you have a chance to visit the Skyfox Den? A very exciting place, from what I've heard. Expedition's spelunkers started surveying the cave and even installed a few grappling hooks on the ceiling, but they were scared away by violent slyverns.\n\nCan you do me a favor? Get inside the Skyfox Den, grab the abandoned gear, and check the ceiling for any hidden crevices. Who knows what could be hidden inside?", objectives = "Explore the Skyfox Den's ceiling using Dragonscale Expedition climbing gear inside the cave.", progress = "Found anything exciting there?", completion = "Well done! My research and writing never end. I'm glad you've seen what's in the den firsthand." }
WordHunterWoW_QuestEN[74119] = { title = "Angler's Challenge", description = "Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots to cast a line. \n\nWhy don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.", objectives = "Catch or restock fish in the Dragonskull Fishing Hole.", progress = "My belly's rumbling... can't wait for those fresh fish!", completion = "We'll have a feast tonight, thanks to you!" }
WordHunterWoW_QuestEN[74120] = { title = "A Spring Awakening", description = "If you're looking for something to do, I hear there are mages in the settlements near capital cities - Goldshire, Kharanos, Dolanaar, and Azure Watch - who have been recruiting egg hunters for help with some research they're doing. I'm not sure of the particulars, but I'm sure they'd tell you.", objectives = "Talk to a Spring Collector in Goldshire, Kharanos, Dolanaar, or Azure Watch.", completion = "Yes! Yes, I think I have just the task for you..." }
WordHunterWoW_QuestEN[74282] = { title = "Authentic Authorization", description = "The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course!\n\nIf I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans!\n\nIf you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!", objectives = "Find a Sealed Letter to Neltharion.", progress = "Did you find anything?", completion = "What an amazing find. The mind reels. \n\nOh, and I can't wait to write about this discovery and publish our findings. We will publish... or perish trying!" }
WordHunterWoW_QuestEN[74291] = { title = "Blue is My Favorite Color", description = "Oh, Kiry's here! I wonder if she has made her decision.\n\nPlease ask her for thoughts, {name}.", objectives = "Speak to Kirygosa and then return to the Azure Archives.", completion = "Let's get back to work." }
WordHunterWoW_QuestEN[74292] = { title = "Deephollow Mysteries", description = "", objectives = "" }
WordHunterWoW_QuestEN[74293] = { title = "Not Forgotten", description = "Viridia is confident that more dracthyr may slumber in these chambers, long forgotten amongst Neltharion's relics.", objectives = "Free dracthyr trapped in stasis within the Zskera Vaults.", completion = "It warms my heart to see so many new arrivals. We will do our best to orient them to the changes since they were last awake.\n\nThank you, friend." }
WordHunterWoW_QuestEN[74294] = { title = "The Keys You Need", description = "Can I trust you? These are the only keys we have. If we lose them, we can't open any locked doors.\n\nHere. Take them. Use them on the doors within this chamber. You look like a hero. Be bold! Throw those doors wide! You'll find glory or... um... something that is not glory but is still amazing! Just don't die.\n\nWe might find more, but we'll have to search the island to find them.", objectives = "Take the keys from Tacha at the Zskera Vaults.", completion = "Be sure to not to lose those keys. Did I say that? I think I said that." }
